/* 平成21年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h21.committeeSessions.push(...[{"id":"h21-20090414-6","meetingId":"h21-cm04","date":"2009年4月14日","dateIso":"2009-04-14","committee":"区民委員会","time":"午後１時０２分～午後３時２１分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を49件整理しています。","topics":[{"id":"topic-01","title":"の「組織改正に伴う事業部等の所管事項の変更について」","agenda":"の「組織改正に伴う事業部等の所管事項の変更について」","exchanges":[{"speaker":"若林委員","kind":"質問・要望","question":"１点だけ、シルバー人材センターとサポしながわが、ものづくり・経営支援課にしたというのは、ちょっとイメージがわかないんですね。ご説明いただきたい。","respondent":"福島ものづくり・経営支援課長","answer":"シルバー人材センター、サポしながわが所管移行になったことにつきましてお答えします。昨年度ですと人口のうち３３％を超えているという中で、より支援が進むだろうということがございまして、こちらのほうに移管したものです。","id":"exchange-001"},{"speaker":"宮崎副委員長","kind":"質問","question":"１点聞きたいんですけれども、スポーツのほうは少年少女スポーツ普及に関する事務を青少年育成課ということだと。組織としてどういうふうな仕切りになっているんか尋ねました。","respondent":"堀越文化スポーツ振興課長","answer":"それからスポーツ協会との連携ですとか、それから大人という形で分けて、このような組織という形で構成しているものです。","id":"exchange-002"},{"speaker":"宮崎副委員長","kind":"質問","question":"例えば、野球場とかそういうものが変わったんですけれども、そういう管理とかというのは、子どもが使う場合は違う申し込みとか、いわゆる施設の場合はどういうふうになるんか尋ねました。","respondent":"堀越文化スポーツ振興課長","answer":"全体的な施設の予約受付、利用調整等全般的な事項については、私ども文化スポーツ振興課のほうで担当いたします。そのほか大会の使用に関しての優先の使用等については、青少年育成課と連携をしながら会場の確保に努めていくというものです。","id":"exchange-003"}]},{"id":"topic-02","title":"の「近隣セキュリティシステム端末まもるっちの更新について」","agenda":"の「近隣セキュリティシステム端末まもるっちの更新について」","exchanges":[{"speaker":"安藤委員","kind":"意見","question":"第３世代への切りかえというのが理由だったと思うんですが、区として言うべきことをきちっと言ったのかというところがちょっとわからなかったので、ご説明のほうをお願いしたいと思いますとの意見を述べました。","respondent":"矢部生活安全担当課長","answer":"平成２０年度中の３Ｇシステムへの移行を再三申し入れしたところであったんですが、期間の延長がということと、今年度の３Ｇシステムへの移行が不可能となったということであります。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問","question":"第３世代への移行が必要なんだということもおっしゃっていたと思うんですが、そういった点で区としてはこれを納得されたということなんでしょうか。やむを得ないことだというふうに思っているのか。","respondent":"宮地地域振興事業部長","answer":"２月２０日以降、ものづくり品川宿、そして区と会議を重ねてきたところです。１２月末までにものもでき、最終的にはソフトバンクテレコム社と契約をするということで方向性が決まったものです。","id":"exchange-005"},{"speaker":"安藤委員","kind":"質問","question":"にかかる費用に関しては平成２０年度予算の事故繰越で開発してということで、今回、区としての判断が間違っていたのか。そこら辺の認識はどのようにお考えなんか尋ねました。","respondent":"宮地地域振興事業部長","answer":"できるという判断で進めておりますので、それをどう解決していくかという、その本社の実施部隊の体制等には問題があったのではないかとは思います。プロポーザルの選定上には問題はないというふうに考えております。","id":"exchange-006"},{"speaker":"渡部委員","kind":"確認","question":"状況を伺ったんですが、確認を含めてなんですけれども、それはソフトバンクのほうで何か根拠があっていっているのかどうかというのがまず１つ。使い方が変わってきてしまう可能性が、デザイン云々もひっくるめて何か変わってくるようなことがあるのかどうか、あわせて説明を求めました。","respondent":"中山地域活動課長、福島ものづくり・経営支援課長","answer":"ただ単に当初予定したものをおくらせるというだけではなく、確かに当初想定していたものよりもより軽く、機能的にも安定したもの。そのもとのシステムの修正も含めたものもこの当初の経費の中で考えていくべきだという中で… ものづくり品川宿と３者で共同して開発していきますので、１２月末までに必ずつくるようにしていきたいというふうに思ってあります。","id":"exchange-007"},{"speaker":"本多委員","kind":"質問・要望","question":"その辺ちょっと教えていただきたいのと、納期が延長というから、平成２０年度で見ていた予算をそのまま平成２１年度で見るという考え方でいいのか。それとも、見積もりとか何かその辺に変更があれば説明を求めました。","respondent":"中山地域活動課長","answer":"実際の執行は平成２０年度予算、実際の支出が平成２０年度で編成した予算がそこに充当できる、執行できるという扱いになるものです。このことを議会には後ほど繰越の報告をする予定になっているものです。","id":"exchange-008"},{"speaker":"若林委員","kind":"質問","question":"再プロポーザルはやらないという。そこら辺の総務省も含めたやりとりの経緯を細かくお聞きしたいのと、そこら辺の何か懸念されているところがあればお聞きしたいと思います。","respondent":"宮地地域振興事業部長","answer":"このシステムそのものは何ら問題はありませんので、こういった１システムを使いながら、それそのものは問題はありません。ただ、第５世代とまたあると思いますが、より精度を高めていくという中での開発のステージだというふうにご理解いただければと思います。","id":"exchange-009"},{"speaker":"若林委員","kind":"質問","question":"前段のほうは、再プロポーザルをやらないという判断をされたわけですね。その判断をされた要因として、ソフトバンク社と品川区と総務省との３者の関係の中でどのようにされたかというのをお聞きしたかったんです。","respondent":"宮地地域振興事業部長","answer":"この間の１２月末までには開発できるというこのスケジュールを見ましても、もう４月早々からやっていきませんとぎりぎりの段階です。平成２０年度の繰越分しかありませんし、先行してまずソフトバンク社の方針といいますか、プロポーザルには踏み切れなかったです。","id":"exchange-010"},{"speaker":"若林委員","kind":"意見","question":"何回もすみません。そういう国とのやりとりがあったのかということが１つと、万が一来年の３月３１日、不都合があった場合のことは準備を想定されているのかというとの意見を述べました。","respondent":"宮地地域振興事業部長","answer":"安心という面からいえば、私たちがそれをどう責任を持って開発し、つなげられるかというのは常に万全の体制でいきたいというふうに考えております。","id":"exchange-011"},{"speaker":"宮崎副委員長","kind":"質問","question":"ちょっと何点か伺いたいんですけれども、通信の不適合、この２つがちょっと具体的にどういうふうなものなのかというのを聞きたいと思うんです。２Ｇから３Ｇへ全体的に動いている中で、なぜ製造が中止になるのか、その辺がよくわからないんですけれども。","respondent":"矢部生活安全担当課長","answer":"当初予定していました通信モジュールという部品らしいんですけれども、それのまず組み込む予定だった部品につきまして、当初組み込む予定だった部品の組みかえがまずできなくなったということで。","id":"exchange-012"},{"speaker":"宮崎副委員長","kind":"質問","question":"やはりそこはちゃんと把握しておかないと、私はこれを進めるのが本当に技術的にも流れに乗っているのかどうなのかという問題なわけですよ。そこの見通しについてはどういうふうに見ているのかというのをお聞きします。","respondent":"宮地地域振興事業部長","answer":"今までこれが広く広がっていかなかった１つの要素としては、そういったものがあって大変難しいシステムだと聞いております。１部品がなくなったらもうそれでだめというようなことですと、そういった安全性も反省して今後取り組んでいきたいというふうに思っております。","id":"exchange-013"},{"speaker":"宮崎副委員長","kind":"質問","question":"万歳ですなんて言われたら、頼むほうはじゃあ、自分たちでつくりましょうなんていうことはできないですからね。どういう対応が出てくるのかなというのが非常に心配なんですけれども、どうなんか尋ねました。","respondent":"福島ものづくり・経営支援課長","answer":"私から答えしますけれども、ソフトバンクは具体的にはかなりの人的体制を組んでいるということで、向こうから報告いただいています。それの改修ということになりますので、全面的にゼロになるということはないと考えていますので、１２月までにできるものと確信しております。","id":"exchange-014"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"もしかしたらマイナスかもしれない。これ以上言ってもしようがないけれども、やはりこっちも引き続いて、変化があったらいろいろ聞かせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"安藤委員","kind":"質問","question":"移動通信システムというのが変わるたびに、「まもるっち」のシステムというのは更新していかなくちゃいけないということなんでしょうか。その点だけお聞きしたいんです。","respondent":"福島ものづくり・経営支援課長","answer":"世代が変わりますと、やはりそれに合わせる形で通信の中身も全部変えていかなければいけませんので、子機の改修は必要になります。行いました３Ｇへの対応というのができなかったことですので、ただ、それらは更新していかざるを得ないというふうに思ってあります。","id":"exchange-016"}]},{"id":"topic-03","title":"の「文化芸術・スポーツ振興ビジョンの策定について」","agenda":"の「文化芸術・スポーツ振興ビジョンの策定について」","exchanges":[{"speaker":"稲川委員","kind":"質問","question":"このアンケートの比重というんですかね、その策定に対してどれぐらいの重みのあるアンケートなのか。どういう形のアンケートなのか、手元にないのでわからないので、その辺を説明を求めました。","respondent":"堀越文化スポーツ振興課長","answer":"回収率ですが、委員からご指摘がありましたけれども、率としてはこの種の調査といたしましては一般的な数値であるというふうに認識しております。これは集計作業が第２回目に向けて行っていますので、第２回目の策定委員会のほうにお出しして、ご意見を伺うです。","id":"exchange-017"},{"speaker":"稲川委員","kind":"意見","question":"もう１点、無作為に２,０００通出したと思うんですけれども、戻りというのはあったのかどうなのか。１つのものについて５つぐらいのあれだとなかなか答えてくれないんじゃないかなと思うんですけれども、その辺を説明を求めました。","respondent":"堀越文化スポーツ振興課長","answer":"それから選択肢についてもいろいろな活動がありますので、そのほかなるべくお答えしやすいように工夫をして行ったつもりです。上がっておりますので、なんとかそれなりの結果を得られたのではないかというふうに認識しています。","id":"exchange-018"},{"speaker":"安藤委員","kind":"質問","question":"やはりこういう場で直接自分の意見を述べるということで、これを４名にした理由がよくわからないというのをお伺いします。これはあらゆる団体に全部聞いたほうがいいと思うんですけれども、対象はどこら辺まで考えているのかお伺いします。","respondent":"堀越文化スポーツ振興課長","answer":"それともう１つは、そういう方についてもあわせてその要素に入れて選定をしていきたいというふうに考えてあります。懇話会については６月のできるだけ早い段階でという形で予定をしておりまして、５月から６月にかけてというところで予定をしております。","id":"exchange-019"},{"speaker":"安藤委員","kind":"質問・要望","question":"それをたたき台にした上で、委員会の策定というような点では、なるべくそこら辺を努力していただきたいと私は思っております。この中で何でこういうアンケートをしたかという課題、今後のあるべき姿を、この時点で区の考えがあったらお伺いしたいと思います。","respondent":"堀越文化スポーツ振興課長","answer":"基本的にはいろいろな材料、データ等を見て、策定委員会の中でご検討をいただくのが大事だろうというふうに考えています。いろいろな人ですとかいろいろな資源の再認識ですとか、情報提供ですとか、そういう点も含めてご検討いただきたいというふうに考えているところです。","id":"exchange-020"},{"speaker":"安藤委員","kind":"質問","question":"ビジョン策定の上で区民としては現時点で環境整備という点で、施設の問題についてはどのように考え、現時点では認識されているんか尋ねました。","respondent":"堀越文化スポーツ振興課長","answer":"そういった状況を説明させていただいた上でどのような形で工夫を図って、皆さんでこれらの活動を振興していくのか。そういった面についてもご検討いただきたいと思いますし、今、ご意見は策定委員会の中でもお伺いをしていくというような形になろうかと思います。","id":"exchange-021"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"それは具体的にどういうところなのか伺いたいんですけれども、町会連合会、具体的に団体というのはどういうものなのか。施設利用団体等となっていますが、それをどういうふうに考えているのかを教えてほしいと求めました。","respondent":"堀越文化スポーツ振興課長","answer":"文化振興事業団ですとかスポーツ協会のほうからもご意見を伺い、策定委員会のメンバーとして団体関係者として入っていただくことを予定しております。","id":"exchange-022"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"２０名という枠の中で考えていくということになると、公募のほうもこんなになっちゃいますというような説明だったんですけどね。今のこの策定委員会の具体的な名前がどうのこうのということを言うつもりはないんですけれども、実際に携わっている人たちが余りにも少ないんで。","respondent":"堀越文化スポーツ振興課長","answer":"さまざまな場面でこの団体の方々は文化芸術・スポーツ活動とつながりのある方だというふうに認識をしています。重層的にさまざまな面からご意見を聞きながら、このビジョンをつくっていきたいというふうに考えておりますので、ご理解をいただきたいと思います。","id":"exchange-023"},{"speaker":"宮崎副委員長","kind":"質問","question":"私はそうじゃなくて、本来はスポーツとか芸術というのは区民の固有の権利ですから、やはりそこをしっかり保障していく。それが結果的にまちづくりにどういうふうにつながるかというのは、そういうところで活躍されている方、そういう人が中心になるべきだ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"}]},{"id":"topic-04","title":"の「プレミアム商品券発行事業への助成について」","agenda":"の「プレミアム商品券発行事業への助成について」","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"過去にプレミアム商品券という事業は行われているわけですけれども、前回の発行からの販売状況というのはどのようなものだったのかというのを教えていただきたいのと、あわせて今回の販売状況をどのように予想されているのかということをお聞きしたいと思います。","respondent":"諸岡商業・観光課長","answer":"平成１５年にプレミアムつき第１弾ということで発行いたしました商品券につきましては、非常に高い回収率となっています。今回につきましても、前回と同様のような人気を呼ぶのではないかというふうに考えております。","id":"exchange-025"},{"speaker":"安藤委員","kind":"質問","question":"例えばどのような層の方が購入しているのかとか、どういうところで実際にこれが売り上げにつながっているのか、使用されているのか。いわゆる波及効果の実態といった点で、前回の発行のことも踏まえてどんなふうに把握をされているんか尋ねました。","respondent":"諸岡商業・観光課長","answer":"これの発行が区内の経済にどのようなプラスの効果があったということの統計とか数字的なものはなかなか調べるのは難しいことだろうと思っています。大型店についてはこの商品券の対象となっておりませんので、商店街のほうの振興に非常に役立っているというふうに考えております。","id":"exchange-026"},{"speaker":"安藤委員","kind":"確認","question":"確認なんですけれども、いわゆる大型店というところは、よく商店街と連携とかをしているケースもあるんですけれども、この商品券というのは大型店で使えるところは区内では１件もないということでよろしいんか尋ねました。","respondent":"諸岡商業・観光課長","answer":"今回店舗数約２,２００店舗、これはいわゆる商店街連合組合等に加盟をしている商店が中心となっておりまして、大型店については両方ありますけれどもご遠慮いただいているという状況です。","id":"exchange-027"},{"speaker":"安藤委員","kind":"質問・要望","question":"そういうことであればわかりました。追跡というのをしていただきたいなと思うんですけれども、それはぜひやっていただきたいという思いで質問いたしたいと思いますが、どうか尋ねました。","respondent":"諸岡商業・観光課長","answer":"区内の波及効果というものをどのような方法で調べるかという調査方法は、研究はしますけれども、非常に難しい部分があると思います。もう１点、あるいは今後の経済事情などをよく見すえながら、今後について検討していきたいというふうに思っております。","id":"exchange-028"},{"speaker":"若林委員","kind":"質問・要望","question":"さっきの２,２００店舗一覧というのは、購入したときにお渡しできる体制は整っているのかというのを１つ伺いたいと思います。次の施策を打つときの参考にどういうふうにデータをとっていくのかという、そこら辺のスケジュールの仕組みをお聞きかせほしいと求めました。","respondent":"諸岡商業・観光課長","answer":"１つは郵便局区内４３カ所で販売をする予定ですけれども、これが月曜日から金曜日の９時から５時です。まだ検討中ですけれども、なるべく加盟店が明確にわかって、買われる方が便利なように工夫していきたいと思っています。","id":"exchange-029"},{"speaker":"若林委員","kind":"質問・要望","question":"あくまでも検討段階、４月２０日はもうすぐですので、ちょっと対応をもう１回確認をさせていただきたいと思っています。これは例えば１週間単位で押さえていくのか、２カ月単位で抑えていくのか、そういうところを具体的に教えていただきたい。","respondent":"諸岡商業・観光課長","answer":"もちろん区商連のほうにあるんですが、これがすべての店に行き渡るように配れるかということは今検討しているというふうに聞いております。","id":"exchange-030"},{"speaker":"若林委員","kind":"確認","question":"一覧表については、商店街の店舗ではなくて郵便局に行って買いますね、窓口で。何枚くださいと買ったときにその場で郵便局員が一緒に入れるとかというのを区商連から聞いた覚えがあるので、そこら辺の確認をしたいと思います。","respondent":"諸岡商業・観光課長","answer":"申しわけありません。早速確認をして、できるだけ検討を進めるように話をさせていただきたいと思っています。","id":"exchange-031"}]},{"id":"topic-05","title":"の「大規模小売店舗（仮称）勝島ＳＣの新設の届出について」","agenda":"の「大規模小売店舗（仮称）勝島ＳＣの新設の届出について」","exchanges":[{"speaker":"稲川委員","kind":"質問","question":"ちょっとお伺いしたいのは施設の運営方法というのが、ここに名称が４つの名前が出ているんですが、これは公募でここに入ったのか。その辺を説明を求めました。","respondent":"諸岡商業・観光課長","answer":"ただ、そのようなファーストフードのお店を予定していますという程度の現状についてのお話でございました。駐車場の整理等につきましても、常駐の警備員等が配置されて、混乱のないように対応していくということで話を聞いております。","id":"exchange-032"},{"speaker":"安藤委員","kind":"質問・要望","question":"それまでにどのような流れでこれが続くのかというスケジュールを教えていただきたい。区としてはどのように近隣商店街と消費者への影響を認識して、調査をしているのかしていないのか、どのように考えているのかお伺いします。","respondent":"諸岡商業・観光課長","answer":"それを受けて、東京都が設置者に対して意見がある場合については意見を申し述べるという、そのようなスケジュールになっております。近隣への影響というよりは、湾岸地区の大型店同士の競合ということが大変要素としては強いのではないかというふうに理解をしております。","id":"exchange-033"},{"speaker":"安藤委員","kind":"質問","question":"都から区長へ意見聴取があるのはいつぐらいなのかということと、都から業者に、そうした意見を聴取した上で意見が出るのはいつぐらいかということ。あるいは商業を営んでいる皆さんへの説明というのは、この要綱の中で行われるのかなと思うんですが、それはいつぐらいになるのか説明を求めました。","respondent":"諸岡商業・観光課長","answer":"これは制度的には４カ月以内ぐらいですが、今般まだ３月に出されたばかりということで、具体的な日程については聞いておりません。それから、説明会ですが、これは法令、それから東京都の要綱等に基づきまして、３月２３日に説明会が地元で実施されたというふうに聞いております。","id":"exchange-034"},{"speaker":"安藤委員","kind":"質問","question":"対象はどういった方々が対象だったのかということと、品川区の商店街の意見をきちっと聞くべきではないかと思いますが、そういったことを行うお考えはあるんか尋ねました。","respondent":"諸岡商業・観光課長","answer":"この説明会についてですけれども、大体半径５００メートルぐらいの方々を対象にして、地元の施設で開催されたです。それがまいりますと、交通関係などについて照会をいたしまして、その結果を都に報告するというようなことになる予定です。","id":"exchange-035"},{"speaker":"安藤委員","kind":"質問・要望","question":"ですから、影響調査、意見聴取を私はすべきだと思います。ぜひお願いしたいんですが、いかがか尋ねました。","respondent":"諸岡商業・観光課長","answer":"そういうことで、設置者のほうでそれについてきちんと対応したということで、東京都へ報告がなされたというふうに聞いております。先ほど申し上げましたように、非常に商店街も重要ですので、そのためにこれからも十分きめ細かく対策をとっていきたいというふうに思っております。","id":"exchange-036"},{"speaker":"安藤委員","kind":"質問","question":"やはり何か、説明会のことに関しても実際３月２３日に行われたということですが、区職員というのはそこに出席をしたんでしょうか。その説明会をもって区としては、この大型店の出店をよしというふうにお考えなのかどうかというのをあわせてお伺いしたいと思います。","respondent":"諸岡商業・観光課長","answer":"説明会の内容ですが、３月２３日、２４名の方々が出席をされて実施されています。１つは、店舗前にバス停を設置してほしいという要望、主なものはそのように聞いております。","id":"exchange-037"},{"speaker":"安藤委員","kind":"質問・要望","question":"内容を紹介していただいたんですが、まだまだそういった関係者の方々の声を拾い切れていないんじゃないかなという思いが強くいたしました。必要であればそういった説明会をしてほしいという要望があれば、そういった要望にはこたえていただくような用意はおありか尋ねました。","respondent":"諸岡商業・観光課長","answer":"そういった意味では今回の説明会が東京都の要綱あるいは法律等に基づいて実施をされて、設置者の説明を聞き、それについて回答する。そのようなことを予定しております。","id":"exchange-038"},{"speaker":"安藤委員","kind":"質問・要望","question":"そこにとどまらず、独自にきちんと意見も聞いた上で、区長から都に意見を上げていただきたいということを強く私は要望いたしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"渡部委員","kind":"質問","question":"２点伺います。それと、駐車場の６４９台というのは基本的に東京競馬で運営していますけれども、競馬場開催時には共用になるのかどうか、わかれば説明を求めました。","respondent":"諸岡商業・観光課長","answer":"その数とかどういう業態のものが入るかということについては、現在のところ私どもにはまだ知らされていないという状況です。これについては、この駐車場自体、そういう方々についての料金等についてはどうするかというのは今検討しているというふうに聞いております。","id":"exchange-040"},{"speaker":"宮崎副委員長","kind":"意見","question":"もう一つ、具体的にどういう影響、数字的に把握していなくてもどういうふうになっていくのかというのは考えているのかというのを１つ聞きたいのと。もう一つ、区というのはこの場合どういうふうにかかわってくるのかというのが、もう一度聞きたいんですけれどもとの意見を述べました。","respondent":"諸岡商業・観光課長","answer":"周辺の小売店等への影響をどう考えているかですが、立会川商店街の場合、一部競馬場の集客に依存している部分があるのも事実だろうと思います。地元の方々もそういうことを目指して品ぞろえ等そういうことについて努力をしていただければというふうに思っているところです。","id":"exchange-041"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"区のほうはどういうふうに聞いているのか。今の本業のほうが、もう一つ、区がこういう計画に対して参画できるのかできないのかというところはどうなんか尋ねました。","respondent":"諸岡商業・観光課長","answer":"その中の一環として、今回、競馬場が持っている駐車場を活用してショッピングセンターを開いたというふうに理解をしています。近隣等に不都合な点があれば、区としても会社のほうに申し入れをするというような、そういったことが区の役割であるというふうに認識をしています。","id":"exchange-042"},{"speaker":"宮崎副委員長","kind":"質問","question":"区というのは２３区、品川区もそうなんですけれども、これはどういう立場なのかというのがあるんですよね。ちょっとそこのところどうなんか尋ねました。","respondent":"諸岡商業・観光課長","answer":"東京都競馬は株式会社です。競馬場との関連はありますけれども、株主といたしましては東京都、この点では直接品川区との関係というのはないというふうに思っております。","id":"exchange-043"},{"speaker":"宮崎副委員長","kind":"質問","question":"どういうふうになるんでしょうか。だから、こういうのを聞いたのかということですよ。","respondent":"諸岡商業・観光課長","answer":"出店について設置者から東京都に法律に基づいて届出が出されて、そのことが東京都から情報提供がございましたので、この当委員会で商業・観光課としてご報告させていただいたです。","id":"exchange-044"},{"speaker":"宮崎副委員長","kind":"質問","question":"区としてどうするかというのが問われているんですから、部長、区としてどうするのかというのが問われているんですよ。どうなんか尋ねました。","respondent":"宮地地域振興事業部長","answer":"大店舗法の手続き上、所管として商業・観光課が通知を受けたものですから、情報提供という形でここにお話をさせていただきました。特別区競馬組合のほうに意見を申し上げていくという形になろうかと思いますので、ご承知おきいただきたいと思います。","id":"exchange-045"},{"speaker":"宮崎副委員長","kind":"質問","question":"やはり私は普通の会社があって、とりわけ行政との関係ですから、そのところはやはり品川区全体としていろいろな角度からしっかり意見を言う。ひとつよろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"}]},{"id":"topic-06","title":"の「平成２１年度品川区中小企業事業資金融資あっ旋制度について」","agenda":"の「平成２１年度品川区中小企業事業資金融資あっ旋制度について」","exchanges":[{"speaker":"井桁委員","kind":"質問・要望","question":"簡潔にお伺いしたいんですが、４番の周知のところで、どのようなことがあって貼り直しになったのか。その経費がわかれば教えてほしいと求めました。","respondent":"諸岡商業・観光課長","answer":"図柄等について不具合がございましたので、実行委員会の皆さん方と協議の上、刷り直しをさせていただいたものです。経費につきましては、約１２万円です。","id":"exchange-047"},{"speaker":"安藤委員","kind":"意見","question":"区がこうした自主的な取り組みにあわせて、いろいろなこういった区主催の普及啓発イベントというのを開催する経緯というのがよくわからないので、そこをちょっと説明してほしいと求めました。","respondent":"諸岡商業・観光課長","answer":"武蔵小山駅、完成の記念式典を区の事業として実施するものですけれども、お祭りのようなことをにぎやかに実施をされるということになりました。それに伴いまして、区もイベントを組んで荏原地区を中心に盛り上げていこうということで、実施することが決まったものです。","id":"exchange-048"},{"speaker":"安藤委員","kind":"質問","question":"式典のほうなんですけれども、これは区で実施ということなんですけれども、ここに地元住民の方の実行委員会というのも一緒にやるということなんですが、式典自体にどういうふうに自主的な地元の地域の方の組織というのがかかわっているのかというのを伺います。","respondent":"諸岡商業・観光課長","answer":"記念式典につきましては、あくまで区の主催事業として実施します。ここについては区が主催ということで実施をするというものです。","id":"exchange-049"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/911630?Template=document&Id=2546#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":42270,"voices":160}},{"id":"h21-20090414-7","meetingId":"h21-cm04","date":"2009年4月14日","dateIso":"2009-04-14","committee":"厚生委員会","time":"午後１時０３分～午後３時１２分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を41件整理しています。","topics":[{"id":"topic-01","title":"請願・陳情審査","agenda":"請願・陳情審査","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"緊急時は対応できるというご説明だったのですが、もうちょっとその辺、具体的に内容がわかったら教えていただきたいんです。１泊２日の受入れというところで、受け入れてくださるところがあるのかどうか、ちょっとその辺も含めて説明を求めました。","respondent":"高橋障害者福祉課長","answer":"都内で対応できているということで、板橋区の心身障害児総合医療療育センター等がありますので、その数があります。１泊２日がショートステイの基本的な考え方で、今後、昼間の場合でも可能になるということで検討を進められているということは聞いております。","id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問","question":"それは通所で通う人の場合ですよね。ほかにそういうのが可能な施設というか、場所があるのかどうか、説明を求めました。","respondent":"高橋障害者福祉課長","answer":"緊急に通えるというと、その日だけということになると、やはりショートステイの中で、その日に朝早く行って、必要がなければ、夕方、午後に帰っていただくという形が一番適切かなと、今の段階では、そういうふうに考えております。","id":"exchange-002"},{"speaker":"阿部委員","kind":"確認","question":"前回のときに、ヘルパーの派遣で足りるというようなご答弁が中にあったかと思うんです。これは確認なんですけれども、どうか、確認させてください。","respondent":"高橋障害者福祉課長","answer":"重度訪問介護ということで、重度の方のヘルパー派遣という形かと思います。ものによっては１２時間まで可能ということで、１日の時間帯を、その方の必要度に応じて使い分けていただいているという状況です。","id":"exchange-003"},{"speaker":"阿部委員","kind":"質問","question":"あるとすると、どのぐらいまで使えているのかということを教えてください。時間的な利用制限ということです。","respondent":"高橋障害者福祉課長","answer":"その方の受給者証を発行しますので、８時間から１２時間ということで、３１日あればずっと３１日分という月単位になります。ですから、３６５日の時間数を受給者証として発行しますので、利用する方については、その時間利用ができると考えております。","id":"exchange-004"},{"speaker":"阿部委員","kind":"質問","question":"しんどいなと思うときには、この制度を自由に使ってちょっと休むというようなことが、現実的に可能な運用であるということでよろしいのか尋ねました。","respondent":"高橋障害者福祉課長","answer":"今の段階ではヘルパーがやることはできませんので、このサービスが使えるかというと、今のところは難しいと考えております。","id":"exchange-005"},{"speaker":"阿部委員","kind":"質問","question":"ちょっと蒸し返しになってはいけないんですけれども、一番しんどい家庭のところに手が届いていないというのが今の制度であって、そこに対して、何らかの方策が必要であろうと、それは区とか、都とか、国とか、いろいろあると思うんですけれども、どうお考えなんか尋ねました。","respondent":"高橋障害者福祉課長","answer":"医療依存度が高い方については、前回と同じような答えになるかと思いますが、そちらのほうで看護のほうはやっていただくという内容になります。両方の連携の中で、実際上、在宅生活を続けていっていただいているというのが現状です。","id":"exchange-006"},{"speaker":"阿部委員","kind":"質問","question":"今日の議題は、あくまでも医療依存度の高いケースですので、ヘルパー派遣の話は、今回はむしろ関係ないと言ってもいいかもしれないです。むしろ、今おっしゃった訪問看護のほうだと思うんですけれども、これは、区内で十分に使える状況になっているのか尋ねました。","respondent":"高橋障害者福祉課長","answer":"医師の指示書に基づいて行われていますが、医師が判断したということで、それぞれの看護ステーションなりから派遣されているということです。私のほうでは、現在、その状況が満ぱいなのか、不足しているのかということについては、ちょっとつかんでおりません。","id":"exchange-007"},{"speaker":"阿部委員","kind":"質問・要望","question":"ちょっと教えていただきたいのと、この状況をどういうふうに運用されていて、ぜひ区でも把握をしてほしいと求めました。結果的に、使いにくいまま、だれも使いにくさに気づくことなく制度が放置されているということにはならないでほしいと思います。","respondent":"高橋障害者福祉課長","answer":"私どもで実際上、プラスアルファの部分については、状況の把握はちょっと難しいかと思います。今、医療法の中で法律上決まっておりますので、区独自で行うということは困難であろうかと考えておるところです。","id":"exchange-008"},{"speaker":"阿部委員","kind":"質問・要望","question":"訪問看護師が必要に応じて派遣してもらえるような状況になっているかどうかということを把握してほしいということであって、人数を伺っていますので。区として要望を出すなり、どういうふうに困っているかということがないと、これは要望にとどめておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"どういう形になっていたのかちょっとわからないんですけれども、そういうのが、今どうなっているのかということと。そういうものをつくることはできないのかなと思うんですけれども、そこら辺のところも、ちょっとお聞かせほしいと求めました。","respondent":"高橋障害者福祉課長、木下健康福祉事業部長","answer":"何なり、医療が必要だということになりますので、そちらにご相談していただいたほうがよろしいかと思います。ということで、申しわけないんですが、医療ショートステイということでの制限のある部分については… 昔の話で、いわゆる高齢者用として、ＮＴＴ東日本関東病院と北品川病院に医療ショートというのを確保してありました。","id":"exchange-010"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"私も知らなかったし、その間に地域の方から訴えられたことでしたので、そういう状況の中でお聞きしている問題です。区としても、ぜひご検討いただけないかなと思うんですけれども、いかがか尋ねました。","respondent":"木下健康福祉事業部長","answer":"これはやはり、一区がどうこうしても解決できない、つまり、家族はやってもいいんだけれども、その他の者はできない。現在のところでは、やはり東京都の療育センター等のショートステイ以外に対応がされる制度的なものがないというのが、現在の状況であるです。","id":"exchange-011"},{"speaker":"鈴木（真）委員","kind":"意見","question":"今までの４回の質疑にいつも出ていますし、今の段階で受け入れることはできないと、私どもは判断しております。派遣できるような福祉支援ということに対しましては、請願者の方には申しわけないですけれども、願意に添いがたいというのが自民党の結論ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"},{"speaker":"堺委員","kind":"質問","question":"看護できる環境がほしい、あるいは子どもたちが安心して生活できる環境もつくってほしいと、いろいろおっしゃっておられました。その思いがどうしても法律の壁にぶち当たって、健康福祉事業部長のご説明を伺うにつけ、そういうようなことがございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"飯沼委員","kind":"質問・要望","question":"意見陳述を伺っていて、今日、また強く感じたわけです。４回目ということですけれども、国も自治体も持っていかなければいけないというところにおいて、趣旨採択をしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"阿部委員","kind":"質問・要望","question":"ただ、それを今すぐ、やれと言うわけにはいきませんので、そういったちょっと広くとらえつつも、いろいろな方法を考えていただきたい。この項目に書いてあるような手法での改善というのはやはり難しいということで、申しわけないんですけれども、願意に沿いがたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"}]},{"id":"topic-02","title":"の(2)高齢者見守りネットワーク事業","agenda":"の(2)高齢者見守りネットワーク事業","exchanges":[{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"町会にやっていただくということで出されていますが、町会に対しては、このペーパーが出るという判断でいいんですか。区内に２００町会ぐらいある中で、どの町会をという判断材料を、ちょっと教えていただきたいのが１点。","respondent":"冨岡高齢者福祉課長","answer":"団地、ある程度実施の段階までいけるようになったところで、いよいよゴーサインが出てから具体的な支援かなとは考えているところです。実際にこれをご説明申し上げる中で、その段階で、もう一度整理をさせていただいて進めてまいりたいと思います。","id":"exchange-016"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"そこら辺を考えると、実際にこの見守りはやってもらいたいんですけれども、もう少し時間的に余裕を持ってほしいという感じがしたんです。そこら辺、詰めていく段階の話なのか、もう決まってしまったのか、そこら辺も説明をほしいと求めました。","respondent":"冨岡高齢者福祉課長","answer":"６月３０日ではちょっと早いというお考えもあるかと思いますが、今まで、出していただいた後に集約していかなければいけない部分もあるかと思います。そういうふうにお考えなのかなと、事業の進め方として、１回区切りをつけさせていただきたい。","id":"exchange-017"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"ちょっとそこに疑問を感じたんですけれども、それが判断になっちゃうのかなという気もするし、その辺はお答えにくいかもしれません。わかりました、結果的には、高齢者見守りのほうをうまくやっていただきたいということをお願いして、さっきの件は要望にしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"阿部委員","kind":"質問","question":"「まだ、具体的なプランはないが区と相談して検討したい」とありますが、この相談の締切りが６月と考えてもよろしいんでしょうか。予算の話はいいですが、課題の大きさにくらべて、打ち出し方がどうも地味な感じがするんですけれども、率直にどうお考えなのか、説明を求めました。","respondent":"冨岡高齢者福祉課長","answer":"「まだ具体的なプランがないが区と相談して検討したい」という部分も、それからご相談しながら固めていくということがあるかと思っています。もちろん広報活動もやってまいりますけれども、じっくりどんどん広げていきたい、また広がっていくものだと理解をしています。","id":"exchange-019"},{"speaker":"阿部委員","kind":"質問・要望","question":"ということは、先ほどの質問にもありましたように、結果的に５件を超えることもあり得ると考えてよろしいんでしょうか。後半のほうは要望です。","respondent":"冨岡高齢者福祉課長","answer":"６月３０日までに、そこから話をまとめてまいりますので、５件で打切りということではございません。ちょっとまだわかりませんが、当然、５以上のものが出てくる可能性はあるだろうと思います。","id":"exchange-020"},{"speaker":"飯沼委員","kind":"質問・要望","question":"それから、調査検討会議の到達点というのが、この見守りが大事というところだという解釈でいいんでしょうか。今後の見通しあたりを、品川区がどうとらえているのかを、まずお聞きしたいんですが。","respondent":"冨岡高齢者福祉課長","answer":"万が一のときに対応できるような、その一番初めの取りかかりにこれからお入りいただけたらというところで、この事業について取り組んでいると。","id":"exchange-021"},{"speaker":"飯沼委員","kind":"質問","question":"７５歳以上の方、どういう状態で暮らしていらっしゃるのかということをつかむのが、数字的なものでおもてに出していただけたらいいなと思います。ひとり暮らしではなくて、世帯というところにおいて考えていく必要があるのではないかと思うんですが、いかがか尋ねました。","respondent":"冨岡高齢者福祉課長","answer":"ひとり暮らし高齢者等の実態調査を、今後活用するということで、基本的にはやはり、ひとり暮らしの高齢者を今回は考えてまいりたいと考えています。","id":"exchange-022"},{"speaker":"飯沼委員","kind":"質問・要望","question":"基本的なことを一つ教えていただきたいんですが、今回、「孤立死」という取り上げ方ですね。その辺の考え方の違いというか、どこにあるのか、基本的なところで教えていただけたらと思います。","respondent":"冨岡高齢者福祉課長","answer":"家族などだれにもみとられずに自宅で亡くなって、しかも何らかの手助けがあれば防げたかもしれない不本意な死というふうに受けとめております。いわば社会から孤立した状態で亡くなられたということで、孤立死というふうに考えているところです。","id":"exchange-023"},{"speaker":"飯沼委員","kind":"質問","question":"では、そういった見方、精査をして出されたのが、平成１９年度のこの１５件ということですか。１０２件というのはどういうことなのか、もう１回、そこのところを聞かせてください。","respondent":"冨岡高齢者福祉課長","answer":"そういうところで対応されていると思うんですが、これは、在宅介護支援センターと高齢者福祉課で把握した部分ということで。たしか１０２になるかなと思いますので、この部分が１０２件ということで、トータルを端折って１０２件と申し上げました。","id":"exchange-024"},{"speaker":"浅野委員","kind":"質問・要望","question":"例えば配食サービスなんかも一つでございまして、隣の港区は、配食サービスを６回から７回にするというような新聞記事もありました。意見だけで終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"阿部委員","kind":"質問","question":"すみません、１点なんですけれども、ひとり暮らし高齢者というのは、別の目で見ると、災害弱者でもあるかと思います。このネットワーク事業と、例えば防災関係を組み合わせるなり、何か連携を取るようなことを考えていらっしゃるかどうか、説明を求めました。","respondent":"冨岡高齢者福祉課長","answer":"対象者がぴったり合うかどうかという部分はあるかと思いますので、その辺も含めて、今後の課題になってくるかなと思います。","id":"exchange-026"},{"speaker":"阿部委員","kind":"意見","question":"さっき、浅野委員がおっしゃったような、見守ってくれなくていいという方でも、防災についてであれば、門戸を開く可能性もないわけでもないかもしれないなどと考えると、やはり何かの連携があってもいいかなと思いますので、ご検討ほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-027"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"それからもう一つは、これからこれをどうなくしていくかというところに、対策の中で結びつけていくことが大事だと思うんです。どうすれば孤立死を防げたのかという、どう考えられているのかということについて、ちょっと説明を求めました。","respondent":"冨岡高齢者福祉課長","answer":"それを踏まえた上で、こういう形の今後の地域の見守りが、今の対応としては一番いいのではないかということで結びつけていったことであります。","id":"exchange-028"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"それを踏まえた、全体的なとらえ方をした上での対策というところで、ご報告いただけたらありがたいと思っています。そこら辺のところは、ぜひ、今後の課題ということでお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-029"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"さっきの報告で、ちょっと数字が早くて聞き取れなかったので、介護施設の１４１名の次が、どこの施設で何名だったか、もう１回説明を求めました。","respondent":"平澤生活福祉課長","answer":"申しわけございませんでした。１７名が入居され、うち１０カ所、１３名が都外です。","id":"exchange-030"},{"speaker":"飯沼委員","kind":"質問","question":"どういう経過をたどって、どういう方が選ばれるというか、その辺のことをお伺いしたい。これはどういう中身なのか、ひとつお伺いしたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"飯沼委員","kind":"質問","question":"アパートとかが見つからない緊急の場合なんかに入居されるということなんですけれども、その後、アパートをご自身が探さないとだめなんですか。品川区に住み続けたいという願いを持っていらっしゃったら、品川区内に戻ってこれるのか尋ねました。","respondent":"平澤生活福祉課長","answer":"特にご本人がこういった施設があるということを病院でお知りになったとか、業者の紹介があったということであります。こちらの方の自立度と申しましょうか、どの程度生活が可能なのかという状況によりまして、それぞれのケースで判断していきたいと考えております。","id":"exchange-032"},{"speaker":"鈴木（真）委員","kind":"質問","question":"そういう言葉が出てきた中で、例えば、生活保護の方が有料老人ホームに入っているというイメージになってしまうと思うんですよ。ですから、ちょっとその辺、説明していただけますか尋ねました。","respondent":"平澤生活福祉課長","answer":"したがいまして、東京都の特別基準、単身ですと、５万３,７００円以下となっております。各施設を見ましても、そういうことになっておりまして、安いところですと３万５,０００円とか、かなり低額なところもあります。","id":"exchange-033"},{"speaker":"鈴木（真）委員","kind":"質問","question":"何か方法がないんでしょうか。施設は、これしか書きようがないということですよね。","respondent":"平澤生活福祉課長","answer":"老人福祉法第２９条に定めるということになりますので、ちょっと内部で考え方をまとめていけるかどうか、この方法しか考えつかないです。申しわけございません。","id":"exchange-034"},{"speaker":"阿部委員","kind":"確認","question":"これは例えば生活保護の方を主に対象とした施設なんですか、事実上、あるんでしょうか。あるいは、ここの６人が入っていらっしゃるのは、まさにそういうものなんか尋ねました。","respondent":"平澤生活福祉課長","answer":"２点のお尋ねです。したがいまして、こういったところがあるということで、ご理解いただければと考えています。","id":"exchange-035"},{"speaker":"阿部委員","kind":"確認","question":"信頼の置けるところであるということで、その中から紹介して選んでもらっているという形でいいのか、その辺を確認させてください。お伺いしたのは、生活保護の方が主に利用されるような形で運営されているものなのか、どうか。","respondent":"平澤生活福祉課長","answer":"入居される場合には、必ずケースワーカーが同行いたしまして、その施設で実際にどのような処遇が行われるかということを見てまいります。これで二つまとめてのお答えになったか、どうか、いかがでございましょうか。","id":"exchange-036"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"大体要介護４とか５でないと、要介護度はどれぐらいまで入られているのか、教えていただきたい。有料老人ホームが６名で、無届けの施設が１７名ということで、ちょっと教えていただきたい。","respondent":"平澤生活福祉課長","answer":"先ほどちょっとご紹介しました第２９条に当たるところなんですけれども、施設面で不十分であったとしても、届出をしなさいという指導をしています。今回、申し上げました施設には入っておりませんので、よろしくお願いします。","id":"exchange-037"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"介護を受けられて、入浴サービスにきてもらったりとかではなくて、そこの施設内で介護も受けられるという施設ということでいいんでしょうか。それから、先ほどちょっとお聞きした介護度がどれぐらいの方が入られているかということも、わかったら教えてほしいと求めました。","respondent":"平澤生活福祉課長","answer":"こういったところから、有料老人ホームとしての位置づけがなかなかできないようなこともあるのではないかなと思います。全部で１２カ所と申し上げましたが、４カ所につきましては食事の提供もしていないということで、私どもで着目しているです。","id":"exchange-038"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"要介護状態の方が、特別養護老人ホームにはまだ入れない要介護度の方が生活保護を受けながら入る施設というとらえ方でいいでしょうか。最後にこれだけ教えていただいて、終わります。","respondent":"平澤生活福祉課長","answer":"全体で都内の施設も入れまして１７カ所ですので、統計上、その点をご承知おきの上ということになっております。６０歳代の方もいらっしゃるですので、生活保護法自体の考え方ですので、そういったところでご理解いただければと考えています。","id":"exchange-039"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"そうしますと、この有料老人ホームの６名も、１７名も同じような施設と考えていいわけですよね。多分有料老人ホームで、特定施設とかの介護保険の制度は使っていないで、生活保護費だけで大体運営をしているという施設と考えていいんか尋ねました。","respondent":"平澤生活福祉課長","answer":"ちょっと申しわけございませんが、できませんので、なかなかわかりづらい。以上、わかりにくい説明で恐縮ですが、よろしくお願いしたいと思います。","id":"exchange-040"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"そうしますと、この介護保険というのは、有料老人ホームで特定施設をとっているというのではなくて、住居としてヘルパーにきてもらったりとか、そういう形での介護保険の制度を使っているという考え方か尋ねました。","respondent":"平澤生活福祉課長","answer":"そうです。","id":"exchange-041"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/854582?Template=document&Id=3232#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":33056,"voices":129}},{"id":"h21-20090414-8","meetingId":"h21-cm04","date":"2009年4月14日","dateIso":"2009-04-14","committee":"建設委員会","time":"午後１時０２分～午後２時４３分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を25件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"井上委員","kind":"質問・要望","question":"区民にとってどういう影響があるのかと思うんですけれども、清掃事務所というと、わりと遠い存在だと思うんです。そういったところがどのようになっていくのか、何かお考えがあれば、少しお聞かせほしいと求めました。","respondent":"工藤環境課長","answer":"私ども環境課のほうに清掃担当が置かれますので、基本的には変更はないと、手続上も変更がないと考えているところです。環境課の清掃担当と品川区清掃事務所のリサイクル推進係が連携をとりながら、区民からの手続きに対応したいと考えております。","id":"exchange-001"},{"speaker":"井上委員","kind":"質問","question":"そういう部分はどういうふうになっているのかというようなことは、清掃担当のほうが把握し、問い合わせにも答えていくというような関係か尋ねました。","respondent":"工藤環境課長","answer":"現場での問い合わせは、基本的には清掃事務所で対応していただくということになります。やはり庁舎のほうに、仕事の連携がうまくいくということがありますので、そちらの部分だけは清掃担当ということで残っているということです。","id":"exchange-002"},{"speaker":"井上委員","kind":"質問","question":"こっちの植栽はちょっと違いましたみたいなこととか、公園のこれからの改良なんかに２つの係がどういうふうに関係していくのかは、どのように考えているんか尋ねました。","respondent":"藤田水とみどりの課長","answer":"もともと同じまちづくり事業部の中でも２つの部署で行っておりましたので、基本的には大きく変わるものではないです。みどりの係がものを考え、お互いに連携をとりながら、これまでどおり進めていきたいと考えております。","id":"exchange-003"},{"speaker":"井上委員","kind":"意見","question":"品川区は結構、事業部制でいろいろ取り組むというところがあったのかと思いますので、事業部をまたがっても、きちんとした連携ができるようにということだけはしっかりとお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"},{"speaker":"菊地委員","kind":"質問","question":"区民委員会であったんですか。この建設委員会に報告をされるという意味合いだったんでしょうか、そこがちょっとよくわからない。","respondent":"久保田都市環境事業部長","answer":"これからも継続していくだろうということが１つありましたので、そういうところの窓口対応も含めて、残さざるを得ないだろうということで。大井町店は全く近くですので、その辺はこれからも少し対応も必要になってくるので、これも残そうということです。","id":"exchange-005"},{"speaker":"菊地委員","kind":"質問・要望","question":"工期との関係で１点お聞きしたいのは、これを見ると、工事そのものはもう始まってからの説明会ということなんですか。それともう１つ、あの地域の町会の皆さんからいろいろな要望が出されていて、ちょっと東京都から聞いていればお聞かせ願いたいという点。","respondent":"松代都市計画課長","answer":"目黒幹線のボックスカルバートの敷設工事を１１月までの予定で進めております。そういったときの対応としては、また地元の方といろいろとお話しながら、十分対応を練っていると聞いているところです。","id":"exchange-006"},{"speaker":"菊地委員","kind":"質問・要望","question":"住民の皆さんの要望に対して、脱硝装置をつけるようになった理由というのがあれば教えていただきたいのと、この３カ所にもこの装置をつけるということになるんか尋ねました。","respondent":"松代都市計画課長","answer":"地域の方々からの強い要望を含め、そういったものにきちんと対応してほしいということがあったことを受け、東京都は設置の方向にもう一歩踏み出した。","id":"exchange-007"},{"speaker":"原委員","kind":"質問","question":"私も菊地委員に続けて質問なんですけれども、東急の例の立体化をもう１回やり直しという、おくれている部分です。この辺のところに関しては、東京都からの一連としてのものなのか、それとも個別でという感じなのか、その辺をまずお聞きしたい。","respondent":"松代都市計画課長","answer":"しかしながら、全体工事の中で、工事のステップということを説明しています。私どももその点も踏まえ、今回の説明を受ける際、これまでと同様に地元に対してはきちんと説明をしてきたんですけれども。","id":"exchange-008"},{"speaker":"原委員","kind":"質問","question":"もう１回、これは面積が減るものですから、品川区のほうにセンターをつくっていますよね。実際に被害というんですか、売上高も３割、４割落ちているという状況に現実的にきているんです。","respondent":"松代都市計画課長","answer":"今回地元からの要望に対して都がかなり早い時間に検討して、回答を出したというのは、すごく評価できるのではないかと思います。そういったことから、換気塔の大きさも４分の１ぐらいでやっているんですけれども、影響等を少なくするという対応をしてくれると聞いてあります。","id":"exchange-009"},{"speaker":"三上委員","kind":"質問・要望","question":"これが１年後になると、また少しでも改善されて進んでいくということですから、これをちょっとお願いしておきたいと思います。そういう準備というのは十分した上でお願いしたいと思うんですけれども、どうか尋ねました。","respondent":"松代都市計画課長","answer":"今回の工事説明会は、下部工事の説明会ということで、実はその上部の具体的な内容を若干説明しましたが。当然そういったことが説明会等で、出るでしょうから、東京都に示していただくことは改めてこちらのほうからも申し上げたいと考えています。","id":"exchange-010"},{"speaker":"三上委員","kind":"質問・要望","question":"ですから、東京都のほうにはきちんとやりなさいということは、住民からも声が出ているということは伝えていっていただきたいです。そういうお願いをしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"菊地委員","kind":"質問","question":"大田区の単位の中に入る部分なんだと思うんですけれども、この跡地を取得する主体というのは、何を意味しているものなんですか。まさか品川区があそこの土地を買うということはあまり考えられないんだけれども、どういうことなんか尋ねました。","respondent":"松代都市計画課長","answer":"将来の２４時間就航等にあわせて、ホテルだとか、いろいろなものが考えられるわけです。それを検討しながら、そういったものを主体的にだれがやっていくのかというのが、まさに今後検討されるものだと考えている次第です。","id":"exchange-012"},{"speaker":"菊地委員","kind":"質問・要望","question":"そうすると、実際に国からどこが買い取って、どうするかということは、これからの問題として、こういう計画がありますという話なんですよね。品川区の副区長がこの協議会に参加しているという、それの理由だけ、ちょっともう１回教えてほしいと求めました。","respondent":"松代都市計画課長","answer":"２４時間就航することが開始されますと、品川区に対しても、品川区としてもそういうものは引き続ききちんと注視していかなければいけない。そういったことも協議会の中できちんと情報をとりながら、意見を求められたときにはきちんと意見を述べる、そういった立場です。","id":"exchange-013"},{"speaker":"三上委員","kind":"意見","question":"１５０万円を３００万円にしたと言ったって、助成を受ける人にとってみると、そんなことについては全く眼中にない。そういったことでの考え方を、もう一回精査するような形での支払い方法というのを考えてもらいたいと思うんですとの意見を述べました。","respondent":"柏原住宅担当課長","answer":"こちらのほうでいろいろ検討する中で、実際に東京都であるとか、国はそういった動きをしているようです。あっという間に助成の金額がなくなってしまうことも考えられますので、その辺、いかに迅速にできるかというのは検討させていただければと思います。","id":"exchange-014"},{"speaker":"三上委員","kind":"質問・要望","question":"住民は要望しているんだと思ったら、６月補正だって、９月補正だってあるじゃないですか。そうだったら、そういう気概というのを示すという意味合いで、もうちょっとしっかりやったほうがいいんじゃないか尋ねました。","respondent":"岩田防災まちづくり事業部長","answer":"万が一申込者が総枠で３００万円を超えた場合は、当然補正等の手続きを検討することになろうかと思いますが、今の時点ではまだこういう制度で走る。住民の方が使いやすい制度に、それは検討していきたいと思いますので、ご理解をいただければと思います。","id":"exchange-015"},{"speaker":"三上委員","kind":"質問","question":"これは戸建て住宅に限らずですか。マンション等については、管理組合等、いろいろな形で申請してきた場合には、対象になるのかならないのか。","respondent":"柏原住宅担当課長","answer":"一応戸建てということで、募集しております。","id":"exchange-016"},{"speaker":"三上委員","kind":"質問","question":"もう１つは、今、古い共同住宅はこの問題でいっぱい悩んでいます。だから、戸建て住宅だけじゃなくて、共同住宅にしても使える制度にしていかないとおかしなことになってくるんじゃないですか、どうなんか尋ねました。","respondent":"柏原住宅担当課長","answer":"先ほども出ましたけれども、今のところ件数が伸びてきてはおりますけれども、今後どういう動きになるか。東京都のほうは集合住宅のほうも対応するような助成制度のようですので、きちんと考えなければいけないんだろうとは考えております。","id":"exchange-017"},{"speaker":"三上委員","kind":"質問","question":"この制度そのものというのが、省エネルギー型設備設置工事、断熱・遮熱化工事、シックハウス対策工事と３つのことを言っているわけでしょう。となれば、シックハウスというのは、戸建て住宅だけにあるんか尋ねました。","respondent":"片田建築課長","answer":"シックハウスについては、マンションとか、戸建て住宅を問わず、住宅については、シックハウス、揮発性有機化合物を生じさせないような材料を使っていただくということでの考え方で今進めている状況です。","id":"exchange-018"},{"speaker":"三上委員","kind":"質問・要望","question":"だから、制度そのものというのを、そういうことで、もう１回だれでもが使いやすい制度にしてもらいたいということなんです、基本的には。そうであるならば、やっぱり見直しできるところについては、早急に見直しはやっていただきたいとお願いしたいと思います。","respondent":"岩田防災まちづくり事業部長","answer":"環境対策として区がこういった自然エネルギー対策にどこまで踏み込むかというのが、まだはっきりとした方針が出ておりません。あるいは指導というもの、誘導策をとっていけるかということは、今後十分検討してまいりたいと思います。","id":"exchange-019"},{"speaker":"井上委員","kind":"意見","question":"今回区内のＣＯ2を把握した上で、この辺をもう一言踏み込んでお答えいただければ、ありがたいのですけれどもとの意見を述べました。","respondent":"柏原住宅担当課長","answer":"ただ単に住宅だけの話ということではなくて、環境全体の話ということ、それは関連の課と協議等、いろいろ話をしながら、どういったことができるのか、どういった政策が一番いいのかというのは、今後詰めていきながら、こういった政策を進めていきたいと考えております。","id":"exchange-020"},{"speaker":"井上委員","kind":"質問","question":"それができないのかなと、実際にはこういったところに１行、その部分でこれだけのメリットがありますというものがここにあってもいいと思うんです。たったの２行もあればいいわけで、これがもうこのまま１３日に出されてしまっているんですけれども、そういったところは考えないんか尋ねました。","respondent":"柏原住宅担当課長","answer":"今回に関しては、申しわけないんですが、載せないでいってしまったという面がありました。東京都のほうは２年間だけの助成事業のようですので、その辺も考えながら、どういった形が効果的なのかというのはちょっと検討したいと考えています。","id":"exchange-021"},{"speaker":"井上委員","kind":"質問・要望","question":"出し惜しみしないでいただきたいなというのは、情報を得たいという人たちの気持ちに沿って、ぜひ情報提供していただきたいということを要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"井上委員","kind":"質問","question":"このＥＢＡＲＡ夢フェスタは、駅の完成記念式典と伺っていたと思うんですが、夢フェスタ２００９とあるということは、実行委員会の方たちのお話かもしれないんですが、恒例にしていこうという、それで２００９なんか尋ねました。","respondent":"松代都市計画課長","answer":"そういう夢はあると思いますが、現在のところ、私どもが一緒にやっている中では、まずは今回を成功させようと、そこの１点に集中していますので、その結果等を見て、地元の方々の発意等があれば、また引き続き続けていけるものではないかと思ってあります。","id":"exchange-023"},{"speaker":"原委員","kind":"質問・要望","question":"１点だけ、ちょっと前にこの夢フェスタという、何か配布物を配って、回収してまた配っているということを聞いたので、その辺、簡単で結構なので、教えていただきたい。","respondent":"松代都市計画課長","answer":"委員ご指摘のとおりでございまして、チラシ、ポスターをつくりました。大変不手際ですけれども、回収して、今新しいものを作成しています。","id":"exchange-024"},{"speaker":"三上委員","kind":"質問","question":"予算特別委員会でも、５００万円は何かという私の質問に、リース料だというだけで終わってしまったんです。そこに聞けば、すべてわかりますということであってもいいんじゃないかなと思うんですけれども、どうか尋ねました。","respondent":"松代都市計画課長、岩田防災まちづくり事業部長","answer":"それを具体化するようになったのは、ここ１年のことだと考えています。一応私どもが取りまとめておりますので、今後駅前広場等の式典のお問い合わせは私のほうにいただければ、きちんとお答えします。こういった行事を計画されておりますので、一緒に共同で行うということで、今回は共催という形をとらせていただいております。","id":"exchange-025"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/814084?Template=document&Id=3940#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":29486,"voices":116}},{"id":"h21-20090414-9","meetingId":"h21-cm04","date":"2009年4月14日","dateIso":"2009-04-14","committee":"文教委員会","time":"午後１時０３分～午後３時１８分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を42件整理しています。","topics":[{"id":"topic-01","title":"の組織改正に伴う事業部等の所管事項の変更","agenda":"の組織改正に伴う事業部等の所管事項の変更","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"はじめに教育委員会のほうで１点なんですけども、位置づけがどう変わるのか、変更の理由をもう少しご説明いただけるでしょうか。位置づけの変更はあるのかどうか、理由を含めて説明を求めました。","respondent":"田村庶務課長","answer":"いわゆる学事係、いわゆる学級数だとか、そういう事業は当然学務課の事業として残ります。もともとの名称が昨年３月までが、今までの３月までの学務課の事業と庶務課の事業というのは今までの現行どおりの仕事の内容と、そういう形です。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"似たような質問なんですけど、そこに何か変更があるのか、そこを説明していただきたいというのが一つ。児童センター、子ども未来事業部というところは何歳から何歳までの事業なのか、政策的な意味合いも含めてちょっと初めなのでご説明いただけますか。","respondent":"田村庶務課長、小林青少年育成課長","answer":"今までも学務課とは調整をしながら学級数の見込みを含めて、それを名称も変更すると同時に、連携しながら。学事制度を統合したから、そこが統合、統廃合のセクションになるという形では一切ございません。 １点目の奨学金の位置づけですけれども、特に移管に伴いまして視点の変更等はございません。そういった事業の視点を明確にしたということで、子どもの未来、子ども未来事業部というふうに考えております。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"大井・八潮地区、解説というよりもねらいをもうちょっとご説明いただきたいというのと、そこはどんなふうにやられているのか教えてください。もう一つ一緒に伺うんですけど、子育て支援課、保育課と地域担当がある。","respondent":"小林青少年育成課長","answer":"保護者の方への周知ですけれども、こうした組織の考え方あるいは事業の流れというのは、その中で十分その趣旨を説明していければと思います。子育て支援課というところへきちっと集約して、３課長が共同して、そのように努力をしていきたいというふうに思っております。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"もちろん３人の課長が気持ちも一緒にというのは、実際どこまで横の連携ができるのかなと、そういう不安もあわせてあるんですよね。実際どれぐらいの数だったのか少し教えていただきたいんですけれども、４月入園を申し込みながら、そこだけ教えていただけますか。","respondent":"小林青少年育成課長、吉岡保育課長","answer":"１人の課長がすべての園を持っていたよりも、園の把握も保護者との対応もきめ細やかな対応ができるかと思います。４月１日時点での在園状況については、保育課長のほうから説明をします。 これは前年に対しますと大体１.３％ぐらいの増加となっております。現在４月の入園状況と申し込み状況を照合しまして、また事務事業概要の説明の際に説明をさせていただきたいと思っているところです。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"地域割、担当割といいますか、これをどのように機能するのか、正直まだ不安が残るなと思います。子どもや保護者の実態と合わせて進めていただきたいなというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"西本委員","kind":"質問","question":"幼稚園代表が上のような感じがありますが、これは同じようなレベルで、この形になるんですか。そこはどういう連携をつくるのか、どうなんだろうというところがちょっと見えないので、お考えがあればお聞きしたいと思います。","respondent":"小林青少年育成課長、田村庶務課長","answer":"この３地区、同じ連携を強めるということで、形成していくというのが経営委員会のねらいと考えております。学校、小学校、中学校との連携を意識しながら地域での活動を考えていきたいというふうに考えております。既にすまいるスクールは放課後対策ということで３８校の小学校で実施しておりますけど、特にブロック、ブロック会というのを全体会と設けています。","id":"exchange-006"},{"speaker":"西本委員","kind":"質問・要望","question":"要望はありますけれども、いろいろお互いが接するようなことをやっていただきたい、幼稚園と保育園の間ですね。せっかくこういう形にしているんですから、もうちょっとと思っていますので、それに対するお考えが聞きたいと思います。","respondent":"小林青少年育成課長、吉岡保育課長、古川子ども未来事業部長","answer":"前段の保護者の関係は、同時に子どもを育成していくという関係の一つとして、親育ちの点も含めて対応していきたいと考えています。… 保育園ＰＴＡと幼稚園ＰＴＡの連携のコラボレーションのお話がございました。ご説明いたしましたように、地区の中での子育ての総合的な展開ということで考… 例えば品川も今回移転したことによって大井地区に移っているんですね、住所、所在地としては。","id":"exchange-007"},{"speaker":"川西委員","kind":"質問","question":"平成２１年度組織改正全般のところで、今までこの業務をやっておられた職員が、単純に庶務課に異動されたというふうに理解しておいていいのかどうか。１回区切ります。","respondent":"小林青少年育成課長、吉岡保育課長、田村庶務課長","answer":"それから、幼稚園の園児募集ですけれども、これも従前どおり統一したスケジュールで区立幼稚園の園児募集は行います。各園で受け付けたものは… 園長ＯＢの配置ですけれども、その辺につきましては、保育課のほうの配置になってあります。 ＰＴＡの調整の事業ですけれども、基本的には現行３月まで生涯学習でやっていた方が庶務課のほうに異動したです。","id":"exchange-008"},{"speaker":"川西委員","kind":"質問・要望","question":"もう一つは、これは素人ですから申しわけない言い方になるけど、この際、学校長と公立園長の兼務は整理統合できなかったんでしょうかね。その辺は専門的な立場からいかがか尋ねました。","respondent":"古川子ども未来事業部長、小林青少年育成課長","answer":"なかなか２３区共通の教育委員会との関係、さまざまございまして、品川区の９園にすべて園長を置くというのはなかなか難しい。それと兼任の園長、いわゆる小学校の校長先生のお力をかりながら９園の幼稚園をそれぞれ運営していきたいと… 幼稚園の入園の件ですけれども、より多くの入園希望に柔軟に対応していくという考え方で対応しております。今後基本的な対応の手法、やり方は今後も維持されていくべきものというふうに考えております。","id":"exchange-009"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"除かれたところはどうするのかとか、この限るというのはどういう意味なのかとか、そこら辺がどう読んでもよく理解できなかったんですよ。この辺の説明をもうちょっとしていただけるとありがたいな。","respondent":"小林青少年育成課長","answer":"より職員の顔が見える３課の課長、園長、そして館長で対応していく。そういった極めて上位に位置する二元的な政策形成については青少年育成課で３課の知識を持ち寄って対応していくというイメージで考えております。","id":"exchange-010"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"ぜひわかるようにしていただきたい。そこの運営係で児童センター、それから幼稚園等も全部そういう修繕だ、何だというのを一括管理して予算執行をしていくという理解でいいんですかね。","respondent":"小林青少年育成課長、古川子ども未来事業部長","answer":"説明が不十分になってしまって。新たな施設で子育て支援課がキッズ館を除きまして全体を統括し、そして施設の管理等も行っていくということで対応を予定しております。 ちょっと先ほど来説明している中で、幼稚園、これは全く同じに今回は扱っていないということです。児童センターは引き続き今年度検討しながら、来年度に保育園、幼稚園と同列に持っていきたい。","id":"exchange-011"},{"speaker":"石田（秀）委員","kind":"意見","question":"このＡ３のやつなんだけど、今のご説明で大体はわかったんですけど、青少年育成課長のところの下に事務局と丸がありますよね。だから、そういう部分を全部統括してある程度意見を集約して、事業部の中の考えをここでまとめていくよという課と思えばいいという理解でいいのかとの意見を述べました。","respondent":"古川子ども未来事業部長","answer":"それは部の庶務担当課である青少年育成課が当然担っていく役割だろう、こういうことです。委員のご指摘のとおりです。","id":"exchange-012"},{"speaker":"中塚委員","kind":"質問・要望","question":"大井第２、大井第３、八潮とあります。それなのかどうか教えていただきたいのと、この中だと、どこに入るのか教えていただきたい。","respondent":"小林青少年育成課長","answer":"地域に根ざすといったときに、一番従前地域割として明確になっている地域センターの管轄を参考に対応していくという考え方です。全１０私立保育園同様に、別な意味で対応、連携をとりながら認可保育園としての一体性を持っていくということです。","id":"exchange-013"}]},{"id":"topic-02","title":"平成２１年度学級編制","agenda":"平成２１年度学級編制","exchanges":[{"speaker":"川西委員","kind":"質問・要望","question":"小学校のほうで、１５番の原小学校、それから大井第一小学校のことなんですけれども、何学級まで教室の収容能力があるのか教えておいてください。伊藤学園のほうは、ここも教室数としては５学級が限度なのか、これが６学級まで行った場合に教室があるのかどうか教えておいていただきたい。","respondent":"富田学務課長","answer":"それと、最近では各学年４学級ということが多い傾向ですが、年度によりまして５学級まで増えた学年も最近あったかと思います。中学校につきまして、６番の伊藤学園ですが、施設的には５学級を想定した施設です。","id":"exchange-014"},{"speaker":"中塚委員","kind":"質問・要望","question":"もう一回教えていただきたいんですけど、それと結果としてどうしても入れなかった学校、ちょっと教えていただけますか。","respondent":"富田学務課長","answer":"小学校についてですが、抽選を行いましたのは、６番城南第二小学校、８番第二日野小学校、１０番第三日野小学校、１５番原小学校の４校です。中学校につきましては、私学等への辞退の方などが多くいらっしゃいまして、すべての学校で繰上げにしております。","id":"exchange-015"},{"speaker":"中塚委員","kind":"質問","question":"なぜ伺ったのかというと、昨年の秋ぐらいの文教委員会だったでしょうか、学校選択制の受入枠の説明がありました。どう言ったらいいのかよくわからないんですけども、受入枠の状況でどういうことになったのか、そこを教えていただけますか。","respondent":"富田学務課長","answer":"今回希望申請で抽選をした学校というのがありますけれども、本来の通学区域の方しか入れなかった学校というのはございません。","id":"exchange-016"},{"speaker":"中塚委員","kind":"質問・要望","question":"６０人という説明だったけど、ここには７９人と載っているので、その辺がよくわからないので教えていただきたい。この８校では、選択制がされなかったという、ちょっとよく意味がわからないので説明を求めました。","respondent":"富田学務課長","answer":"新入学者の入学につきましては、学校選択制もそうですけれども、できる限り保護者の意向に沿ってということにしています。６０人等といった受入枠はあくまでも目安ということでございまして、各学校長と調整をしながら、このような形になったものです。","id":"exchange-017"},{"speaker":"中塚委員","kind":"質問","question":"ということは、中学校のほうも超えているということは、同じ理由だということでよろしいんでしょうか。その辺の判断の基準がよくわからなかったので、その受け入れの目安ということの説明を教えていただけますか。","respondent":"富田学務課長","answer":"あくまでも目安として受け入れの人数というものを示したところです。小学校については６年間、どの辺までオーケーかということを各学校長とぎりぎり調整した結果です。","id":"exchange-018"},{"speaker":"中塚委員","kind":"質問","question":"あのときの受入枠を決めましたというその説明は何だったのかよくわからなくなっちゃうんですけども、もう一度、その意味というか、理由というか、そこを教えていただけますか。","respondent":"富田学務課長","answer":"何回も繰り返すようですけれども、受入枠というのは、施設上の都合を勘案した、状況を勘案したところでの受け入れる学級、人数の目安です。","id":"exchange-019"},{"speaker":"西本委員","kind":"質問","question":"３９人で適用になったということなんでしょうけど、山中小学校は４３人で２学級というのはどういうこと、もともと２クラスではなかったんですかね。ところが、特別支援が１クラスになっているんですが、これはどういう意味か尋ねました。","respondent":"富田学務課長、冠木指導課長","answer":"クラス替えにより安定した学級経営や児童・生徒への継続的な支障が生じる理由がある場合ということで、また減の場合でもあるのですけれども。こうしたことから、結果として２学級のままでありましたけれども… これは宮前小学校と戸越小学校に通うお子さんの障害の状況であるとか、そういった部分での違いだというふうに考えてあります。１カ月以下、清水台小学校のほうから病院のほうに赴いて指導等がなされていると、そういう状況もあります。","id":"exchange-020"},{"speaker":"西本委員","kind":"質問","question":"それから、清水台小学校については、今長期の入院の方はいらっしゃらないということですけれども、クラスが一つというのはどういう意味なんですかね。一つの部屋を確保しなきゃいけないということなのか、あるかもしれないということで、クラスだけは確保しておきましょうということですかね。","respondent":"冠木指導課長","answer":"清水台小学校のさいかち学級については、委員ご指摘のとおりです。戸越小学校の通級学級につきましても、今委員おっしゃったように子どもの数に合わせて、教員の数、学級とかが決まりますので、そのとおりです。","id":"exchange-021"},{"speaker":"西本委員","kind":"質問","question":"２３人で２クラスなわけですよ。それだったら、２１人で３クラスで、２３人で２クラスというのは、どういう意味なんか尋ねました。","respondent":"若月教育長","answer":"聴こえと、それから言葉と、この２種類があるんですね。いつそういう子どもが出ても、そういう子どもをすぐに受け入れられるように学級認可だけは維持していますよと、そういう意味です。","id":"exchange-022"},{"speaker":"山元委員","kind":"質問・要望","question":"特別支援の生徒数が２２人ということで３クラスということなんですが、内訳を教えていただけますでしょうか。何年生に何人とかということを教えていただけますか。","respondent":"富田学務課長","answer":"すみません、特別支援学級の学年ごとの内訳はちょっと手元に本日持ってきておりません。申しわけありません。","id":"exchange-023"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"これは非常に早い時点で減ることを前提に申請をするかということが１点教えていただきたいのと、私、例えば品川小学校みたいに７９人だと。それでいいのかどうか。","respondent":"富田学務課長","answer":"８１人から３学級になるですが、４月７日現在の児童・生徒数で変更があった場合には、そのようにすることが可能になってくるかと思います。ただし、それを過ぎた場合には、年度当初に編制した学級は原則として変更は行わないことというふうに定められております。","id":"exchange-024"},{"speaker":"石田（秀）委員","kind":"意見","question":"だけど、品川小学校みたいに７９人で２人増えたと。そのときには、別にクラスの中でどうということではなくて、２年になるときには３クラスになるんでしょうという理解でいいのかどうかとの意見を述べました。","respondent":"富田学務課長、若月教育長","answer":"申しわけありませんでした。８１人を超えた場合、３学級となることを学校のほうで希望する場合にはそのままでいれば３学級になるということです。 だから、さっき説明の中で、増減と言ったでしょう。でも、いいんですという場合、それはじゃあ認めましょうと、そういう制度だということなんです。","id":"exchange-025"},{"speaker":"石田（秀）委員","kind":"意見","question":"これは来年も３クラスで、もし７９人になったとしても、３クラスでお願いしますよというのを早目に申請するんでしょう。品川区の考え方で、品川区は前もってその人数が増えた場合は３クラスにしますよというのを申請しておかなくちゃいけないわけとの意見を述べました。","respondent":"若月教育長","answer":"そうです。","id":"exchange-026"}]},{"id":"topic-03","title":"の平成２１年度品川区立幼・小・中学校（園）長、副校（園）長異動者名簿","agenda":"の平成２１年度品川区立幼・小・中学校（園）長、副校（園）長異動者名簿","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"ちょっと教えていただきたいんですけど、中学校の校長、その辺の仕組みが前からよくわかっていなかったので教えていただけますか。関連になるんですけど、品川で採用した５人の区の教員の先生がいらっしゃったと思うんですけども、どこの学校に配置されたのか教えていただけますか。","respondent":"和氣小中一貫教育担当課長、冠木指導課長","answer":"副校長もうちでは３名ですが、両方入れるようにしておりますので、それぞれその内容で承認をいただいているところです。特にそこについてこれじゃなきゃいけないというしばりはございません。 後段の質問についてですが、区費の教員の配置先ですけれども、１名が大井第一小学校、１名が第二延山小学校、１名が大崎中学校、１名が鈴ヶ森中学校、１名が冨士見台中学校です。","id":"exchange-027"},{"speaker":"中塚委員","kind":"質問","question":"小学校に籍がある、中学校に籍があるという意味ですよね。そうすると、厳密に決めていないということなのか、それとも一応決めてあるのか、よくわからないので教えていただけますか。","respondent":"和氣小中一貫教育担当課長","answer":"ただ、それは変更可能です。という形で、そこは協議をして対応できますので、実際の学校の今後の方針も含めまして検討して配置を決めているところです。","id":"exchange-028"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"すみません。言えれば番号で言っていただきたいんですけど、小学校何人とかでもいいんですけど、再任用の方を教えてほしい。","respondent":"冠木指導課長","answer":"再任用の校長先生につきましては、現在９番の芳水小学校、それから２６番の大原小学校、３０番の第二延山小学校でございまして、中学校のほうは２番の城南中学校と１１番の荏原第三中学校です。","id":"exchange-029"},{"speaker":"石田（秀）委員","kind":"質問","question":"なければいいんですけど、幼稚園はないのかというのと、あと副校長先生はないのかというのも教えていただければありがたい。","respondent":"冠木指導課長","answer":"幼稚園の園長先生には再任用の方はいらっしゃいません。それから、副校長のほうにも再任用の副校長先生はいらっしゃいません。","id":"exchange-030"},{"speaker":"石田（秀）委員","kind":"質問","question":"幼稚園もそういう方向性で少し考えるのか、保育園は多いからね、園が。いい人がいればそういうことも考えるということか、お考えを説明を求めました。","respondent":"若月教育長","answer":"基本的に教育委員会として幼稚園だから、小学校だから、中学校だからという明確な区別をするようなことは考えておりません。そこにおいては、だから、校種別において差は一切設けておりません。","id":"exchange-031"},{"speaker":"西本委員","kind":"質問・要望","question":"初めてですかね、これは今後どういう形で小中一貫校の校長先生として、考え方として何かあるのかな。人事権は都になるわけですから、それをどれぐらい品川区の要望というのは取り入れられているものなのか、ほとんど品川の要望どおりになるのか。","respondent":"冠木指導課長、和氣小中一貫教育担当課長","answer":"１００％それが認められるという現状もなかなかございませんで、なかなか厳しいところでやりとりをしているという現状はあります。しかし、品川区の教育改革を進めていく上で… 小中一貫校の校長先生は中籍じゃなきゃいけない、小籍じゃなきゃいけないという考えはございません。力があれば、どなたでもというふうに考えてあります。","id":"exchange-032"},{"speaker":"西本委員","kind":"質問","question":"６、これは今後どういうふうになってくるのか、関連でお聞きしたいと思います。そういう考え方をちょっとお聞きしたいなと思います。","respondent":"和氣小中一貫教育担当課長、若月教育長、市川教育次長","answer":"悪いところがありますので、それをしっかり出し合って、新しい教育文化をつくろうというのが品川の考え方です。… それなのに、教員はやっぱり中学校じゃなきゃ、ああいう学校は運営できないんだよ、小学校の校長は一段下だよ、そういう意識が現実にあるんですよ。だから… 私から名簿についてのご説明をします。","id":"exchange-033"},{"speaker":"石田（秀）委員","kind":"意見","question":"副校長にどういうふうに、校長先生も副校長先生も町会長レベルの地域の方々も非常に困る場合が結構あると思うのね、一緒にかえちゃったときは。そこら辺のフォローはどう考えられているのかとの意見を述べました。","respondent":"市川教育次長","answer":"当然学校運営そのもの、学校運営本体とそれから例えば地域との関係ですとか、さまざまな支障が生ずることも十分考えられます。そういう場合には、そういった対応をしてまいりたいと考えています。","id":"exchange-034"}]},{"id":"topic-04","title":"その他","agenda":"その他","exchanges":[{"speaker":"西本委員","kind":"質問","question":"それからもう一つは、５月１７日１１時の記念式典なんですが、これは対象となる例えば委員会とかはあるんですか、委員側からいうと。それが全員がとか、対象全員だとかいろいろあるんですけど、そういう区別があるんか尋ねました。","respondent":"安井子育て支援課長","answer":"それから、ご招待とか、式典のほうのご招待の関係については、まだちょっと詳しいところは決まっておりません。申しわけございません。","id":"exchange-035"},{"speaker":"西本委員","kind":"質問","question":"いろんなものがあるんですかね、全体も何かあるんですか、そういう冊子とか。そういうものがあれば、全体図が見えないので。","respondent":"安井子育て支援課長","answer":"今チラシとかは作成している段階だというふうには聞いておりますが、まだ私どものほうには手元に来ておりませんので、そういう段階です。","id":"exchange-036"},{"speaker":"中塚委員","kind":"質問","question":"日本保育サービスの認証保育園ということですけれども、品川区との調整というか打ち合せというか、いつごろから始まって、どういう経過で今日こういう報告になったか、その経過を教えていただけますか。","respondent":"吉岡保育課長","answer":"それにつきましては、ちょっと時期がいつというのは手元に持ってございませんけれども、昨年度来、こちらの株式会社日本保育サービスのほうからお話を受けまして、保育課として行政指導する中で、今申し上げたような開設の運びになったものです。","id":"exchange-037"},{"speaker":"中塚委員","kind":"質問","question":"昨年から話があって、その経過が見えないので、どういう調整をして今日に至ったのか、その経過を教えていただけますか。","respondent":"吉岡保育課長","answer":"経過ですけれども、一応開設をするに当たって定員をどうするかとか、園児の受け入れについてとか、施設の内容等々を調整してまいりまして、今申し上げたような結果になったところです。","id":"exchange-038"},{"speaker":"中塚委員","kind":"質問・要望","question":"どうしてそんなことを聞いたのかというと、今年から認証保育所の誘致が１,０００万円から３,０００万円に上がりましたよね。これは昨年から話があったんだというところの整合性がよくわからないので教えていただきたい。","respondent":"小林青少年育成課長","answer":"昨年度中から施設の設置、特段１,０００万円、３,０００万円ということが起因するものではございません。その１,０００万円、３,０００万円というのが開設の初期投資にかかわるものですけれども、１,０００万円ベースの積算が求められているところです。","id":"exchange-039"},{"speaker":"中塚委員","kind":"確認","question":"この日本保育サービスは１,０００万円の開設だということなのか、それとも３,０００万円ということなのか、そこをもう一回確認させてください。","respondent":"小林青少年育成課長","answer":"３,０００万円というのは限度額を規定しているもので、実際にはかかった費用のうち助成対象になるものだけを積み上げてやっていくものです。","id":"exchange-040"},{"speaker":"西本委員","kind":"質問","question":"今認証保育所のほうは、ある程度どこまで言える権限を区として持っているのか。してくださいと言うのか、しなさいと言うのか、どこまで権限を持っているものなんか尋ねました。","respondent":"小林青少年育成課長","answer":"東京都の認可ですけれども、ともに協力して指導に当たるということになっておりますが、実際に日々接触して指導しているのは区なんですね。不適切な運営がされれば、一定の限度はありますけれども、指導を受けているというものです。","id":"exchange-041"},{"speaker":"西本委員","kind":"質問・要望","question":"やはり、そこは窓口というのをきちんと告知でもしていただきたいな、改善要求するというのをつくってほしいと求めました。やっぱり保育の内容をよくするということは、区のほうからもどんどんやってほしいと求めましたが、ご意見をお聞きしたいと思います。","respondent":"小林青少年育成課長","answer":"基本的に親と十分連携して子育てということが可能になるという現状からいえば、区も十分な指導をして意思疎通がきちっとできるように指導してまいります。","id":"exchange-042"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/298846?Template=document&Id=4664#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":38352,"voices":156}},{"id":"h21-20090414-5","meetingId":"h21-cm04","date":"2009年4月14日","dateIso":"2009-04-14","committee":"総務委員会","time":"午後１時０２分～午後４時２３分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を43件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"林委員","kind":"質問","question":"総務委員会の議事係の方が２人、一遍に動かれているんだけれども、これは委員長、事前にお聞きになっているんか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"林委員","kind":"質問","question":"２人も一緒にかわってしまうということのデメリットみたいなものはないんか尋ねました。","respondent":"須藤委員長","answer":"まるっきり新しくということではなくて、議会の状況を知っているというようなことの説明をいただきました。私自身もそれで、その話については承知をしました。","id":"exchange-002"},{"speaker":"林委員","kind":"質問","question":"委員長はそういうわけで納得された。これを実績に、本来は議長がやるべきところの仕事も入っているかもわからないけれども、そういう点についての配慮というのはないんか尋ねました。","respondent":"榎本人事課長","answer":"人事異動一括で、それぞれの仕事の内容をお聞きして動かしておりますけれども、細かい事務分担というところまでは、すべてを網羅するというのはなかなか難しいので、なるべく網羅はしていきたいと考えていますけれども、結果としてこうなる場合もあるかなと感じております。","id":"exchange-003"},{"speaker":"林委員","kind":"質問","question":"細かい点までなかなか考慮がいかないということがあれば、事務局長にお聞きしますけれども、一たん内示というか、そういうときに、この人とこの人を一度に動いちゃうと、議会事務局としては、こういうことで配慮をしてほしいというようなことを言うような仕組みにはなっていないんか尋ねました。","respondent":"桑村区議会事務局長","answer":"委員長がおっしゃられたように、あるいは違う配慮は私ども事務局の中でやるとか、一定の中でやっぱり調整せざるを得ないということだろうと思います。その意味で、すべてを議会のほうでの考え方というのを私が通すというわけには、なかなか難しいのかなと考えておるところです。","id":"exchange-004"},{"speaker":"林委員","kind":"質問・要望","question":"急ぎますけれども、いろいろ、全体的なことも考えなきゃならないという、いろいろな配慮が必要だとすれば、僕は議長に相談すべきだと。こういうふうにたまたま同じ委員会の議事係の方が２人、一遍に２人の方というのは異様に映るので、ぜひ考慮しておいてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"}]},{"id":"topic-02","title":"の組織改正に伴う事業部等の所管事項の変更","agenda":"の組織改正に伴う事業部等の所管事項の変更","exchanges":[{"speaker":"林委員","kind":"確認","question":"本当に９時ぐらいまで、残っている人がこの中にいればわかるだろうけれども、こうこうと電気がついていた。中の細かい整理をされていたんだろうと思うんだけれども、確認の意味で、大丈夫だったんでしょうね。","respondent":"久保田行財政改革担当課長","answer":"職員としましては確かに夜９時ぐらいまでは残っていた姿を多々見ておりますけれども、区民に対しまして混乱はなかったと聞いてあります。","id":"exchange-006"},{"speaker":"林委員","kind":"質問・要望","question":"４月になってからは、３７７７－１１１１で、何々係長さんをお願いしたいんですけれども」って。相当、ご本人は耳に栓をしておいてもらって、説明をしてくださった行財政改革担当課長に答えていただきたい。","respondent":"久保田行財政改革担当課長","answer":"私が先ほどご説明で変更がないと言いましたのは、会計管理室の組織上の変更はないです。会計管理室の設置規則で書かれておりますので、そういう組織上の変更ということではございませんけれども、これから区政を進めていく中では。","id":"exchange-007"},{"speaker":"林委員","kind":"意見","question":"これから企画室、企画部というところの仕事はどういうふうに区として考えておられるのか、説明つきますか。当事者でもいいし、変えたほうでもいいし、区の責任者でもいいとの意見を述べました。","respondent":"本間副区長","answer":"特に今回の組織改正で軽重が変わったということじゃございませんが、会計管理室につきましてはそのような考えでやったです。それから、具体的な中身につきましては、これ、人事に関することですので、ひとつご了解のほどよろしくお願いいたします。","id":"exchange-008"},{"speaker":"林委員","kind":"質問・要望","question":"ですから、その仕事につく方の意欲も、きちんと燃えたぎらせていっていただきたいということをひとつお願いしておきます。最後に１つだけ、１ページ目の施設整備課という新設された課があって、こういうことになったんか尋ねました。","respondent":"榎本人事課長","answer":"もちろん専門職、技術職の専門職の中で有資格者は多数おります。建築士とか、そういう中で人材育成を図っていきたいという形で、ここにはそういう資格者を優先的に配置するという考えがあります。","id":"exchange-009"},{"speaker":"林委員","kind":"質問","question":"事故につながるような部署ですので、きちんとした資格を持った人にきちんとした指示を与えて、仕事をしていかれるようにお願いをしておきます。いずれお聞きしたいと思いますけれども、きょうはこれでやめておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"南委員","kind":"提案","question":"なかなかどういう、事務のことを説明いただくのにどういうふうな、幾つか伺いたい。いわゆる消費者行政についてどういうふうに提案というレベルのところがどういうふうになっていくのかというのをちょっと知っておきたいと思いますとの意見を述べました。","respondent":"久保田行財政改革担当課長","answer":"教育委員会が基本ですけれども、その運営の部分について補助執行という形で、保育課でやっていくということのご説明をさせていただいたところです。そういった部分との連携も図りながら、またはいいセンターとしての機能、役割を担っていきたいと考えているところです。","id":"exchange-011"},{"speaker":"南委員","kind":"質問・要望","question":"長短、あるいはこういうところが組織的に管理運営としてこちらの部分になったことでよかったよみたいに聞いているところというのはないですか。ちょっとその辺、わかる範囲でいいですけれども、教えてほしいと求めました。","respondent":"久保田行財政改革担当課長","answer":"幼保一体の連携というのは非常に必要だという形で考えておりますし、幼保一体を進めてもらいたいという声も寄せられていることは事実です。私どもでは細かいところまでは把握してございませんけれども、全体の流れとしましてはそういった部分というふうに考えてあります。","id":"exchange-012"}]},{"id":"topic-03","title":"２番目の品川区長期基本計画および品川区総合実施計画（第１次）の策定","agenda":"２番目の品川区長期基本計画および品川区総合実施計画（第１次）の策定","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"ですから、ここに課題が４つあって、やらなきゃいけない課題があると思うんです。その辺についてはどういうふうにとらえているのか、必要ないということで記述していないのか、その辺の考え方を伺っておきたいと思います。","respondent":"久保田行財政改革担当課長","answer":"４３ページに親育ちサポート事業の充実の中で、若いうちからそういう認識を持ってもらうというような取り組みは進めているところです。ですけれども、そういったことも検討の一つではあるのかなというふうには認識をしています。","id":"exchange-013"},{"speaker":"南委員","kind":"質問","question":"そこのところは税収の関係でどういうふうに見ているのかというのは、この一覧表を見たときに非常に気になったんです。その辺の見方という、予想、どういうふうに見ておられるのかを伺っておきたいと思います。","respondent":"久保田行財政改革担当課長、金子企画財政課長","answer":"私のほうの説明が足りなかったかもしれませんけれども、３年間の計画事業ですので、実施計画の本体に載っている事業につきましては。平成２２年度の予算編成の中で精査してまいりますので… こちらの実施計画の中にありますとおり、平成２３年度にかけては減少していくというふうな見込みを立てております。","id":"exchange-014"},{"speaker":"南委員","kind":"質問・要望","question":"ちょっと気になって、もう一回、再確認なんですけれども、税制改正のところの今、説明なんですが、税制改正というと具体的にどういう内容の税制改正というふうに見て、今のを説明していただいたのか、その辺を詳しく教えてほしいと求めました。","respondent":"金子企画財政課長","answer":"ご案内のとおり、現在、新経済対策ということで、また税制改正が見込まれているところであります。そういったことについてはこの計画には一切見込めておりませんので、それが本年度に影響する部分について見込んでいるです。","id":"exchange-015"},{"speaker":"林委員","kind":"質問","question":"ほかの収入にしても、経費にしても、毎年上がっているというのは、１年上がって、次下がるとかあるんだけれども、３カ年ずっと上がりっ放しという。これは品川区でやってきた行財政改革という大きい勲章を外すという意味になるんか尋ねました。","respondent":"日下部企画部長","answer":"ただし、そうなりますと逆に委託の経費、物品費が上がってまいりますので、これがこういう形で、逆な形ではね返ってくると。そういうことでご理解をいただきたいと思います。","id":"exchange-016"},{"speaker":"林委員","kind":"質問","question":"それから、公債費はどういう仕組みで、これ、１割も減るんだよね。上がるものはしようがないでしょうという、そういうふうにも受け取れるんだけれども、そんなことなんか尋ねました。","respondent":"日下部企画部長","answer":"ちょっとご説明しますと、この１０カ年の計画の前提といたしましては、平成２１年度予算で城南小学校の学校誘致の取得をいたしました。ただ、あともう一つの増要素としましては、実は施設が老朽化してまいりますので、維持補修の経費をやはり年々、一定額を見込まざるを得ない。","id":"exchange-017"},{"speaker":"林委員","kind":"意見","question":"あれは取り消すべきだと僕は思うんだけれどもね。すごい世知辛い考え方で、あれは載っているんだけれども、その辺についての説明をしてくださいとの意見を述べました。","respondent":"日下部企画部長","answer":"このような認識に立っております。定額給付金の実施に当たりまして、そういうふうな趣旨もありますので、ぜひともご理解をいただきたいと思います。","id":"exchange-018"},{"speaker":"林委員","kind":"質問","question":"これでいくと１,３８３億円から１,２７５億円という数字が並んでいるんだけれども、１割弱の減になっている。そういう考えでいいんか尋ねました。","respondent":"日下部企画部長","answer":"全体の年間の予算の総額の関係でまいりますと、確かに平成２３年度、平成２２年度ぐらいまでかなり集中をしている面があります。こういった取り組みを通して、区と区民とのきずなをより一層強めていきたいという趣旨ですので、その辺は何とかご理解をいただければと思います。","id":"exchange-019"},{"speaker":"林委員","kind":"意見","question":"必要なときは、あなたも今言ったように、必要だから一緒に協働作業してほしい。はっきり言っておきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-020"}]},{"id":"topic-04","title":"３番目の平成２１年度オリンピックムーブメント事業","agenda":"３番目の平成２１年度オリンピックムーブメント事業","exchanges":[{"speaker":"土井委員","kind":"意見","question":"ということは、要するに１,０００万円来ますけれども、これくらいのことをやれば渡しっ切りでもらいますよという金だと。オーバーするほうがどうも濃いように思えてしようがないものだから、聞いているんですとの意見を述べました。","respondent":"久保田行財政改革担当課長","answer":"区役所からスポーツ協会に委託をいたしまして、この事業にかかわる直接の区の職員の人件費というものは基本的にはないと考えています。そして、オーバーすることもございませんので、予算の９００万円の中でやっていただくというところを予定しています。","id":"exchange-021"},{"speaker":"南委員","kind":"質問・要望","question":"あまりよくわからなかったんですけれども、そのお金を使って夢フェスタも含めて９００万円でやれますよと、そういうことなんですか。その辺を確認するのと、わかるように説明していただきたいと思うんですけれども、その辺も含めて教えてほしいと求めました。","respondent":"久保田行財政改革担当課長","answer":"私が今説明しました９００万円は、夢フェスタの経費はこの中には含まれてございません。ＥＢＡＲＡ夢フェスタですけれども、こちらは今年度初めてやる事業でございまして、今までやっていた事業ではございません。","id":"exchange-022"},{"speaker":"南委員","kind":"質問","question":"認識を伺っておきたいし、去年１１月もたしか呼んで、講演しましたよね。ムーブメントに対する取り組み方の区の意識というのでしょうか、認識というのでしょうか、その辺を伺っておきたいと思います。","respondent":"久保田行財政改革担当課長","answer":"それに加えまして、そういった事業ではこうしたものを取り組んで、推進していきたいと考えているところです。健全な育成に結びつけていきたいというところもありますので、こういった取り組みを今年もやっていきたいと考えているところです。","id":"exchange-023"},{"speaker":"南委員","kind":"意見","question":"この時期にやっぱり私はやるべきじゃないということを意見として、こういうことよりも、むしろ暮らしを支えるところだと思うんですね。そういう点で……との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-024"},{"speaker":"南委員","kind":"質問","question":"自説じゃないですよ。区民の一部の意見ですからね、それは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"須貝委員","kind":"質問・要望","question":"私からの要望なんですが、うまく相乗効果が出るように、やはり双方が盛り上がるように工夫をしてほしいと求めました。地域の人が中心にいろいろ、イベントに対していろいろお力を使っていると思いますので、その辺に対しては。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"金野委員","kind":"質問・要望","question":"１点だけ。事業内容で教えていただきたいところが、４番目のこのセミナーに関しては、決まっていれば教えてほしいと求めました。","respondent":"久保田行財政改革担当課長","answer":"アスリートではございませんけれども、コンディショナートレーニングをされている方とか、そういった専門家の方のセミナー教室みたいな開催のイメージで考えているところです。","id":"exchange-027"},{"speaker":"金野委員","kind":"質問・要望","question":"つけたようなイメージをどうしても持ってしまうので、この(4)に関してだけ状況をお聞きしながら進めていただきたいという希望、ここも目玉になるようなものをぜひお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"林委員","kind":"質問","question":"きょうは、たまたまオリンピックの調査がきょうから始まったというふうに聞いているんだけれども、何かと関係があるんでしょうか。この５月１６日。","respondent":"久保田行財政改革担当課長","answer":"すみません、５月１６日については特にオリンピックと何か関係のある日というふうには伺ってございません。夢フェスタを５月１６日、１７日にありますので、１６日の開催になったというところが経緯です。","id":"exchange-029"},{"speaker":"林委員","kind":"質問","question":"とすると、武蔵小山の駅前、西小山は１７日と聞いているんだけれども、お客さんが分散されちゃわない？武蔵小山の駅前の祭典とかイベントを妨害、妨害とまではいかないけれども、同じような時間帯にされるとという心配はないか尋ねました。","respondent":"久保田行財政改革担当課長","answer":"私どものほうとしては、私どもは庁内で連絡検討会を立てまして、横の連携も図ってあります。は１６日のほうでは、後ほどご説明がありますけれども、工夫はしていきたいと思っています。","id":"exchange-030"},{"speaker":"林委員","kind":"質問","question":"だったら循環バスか何か出すぐらいの心意気で、寄附が集まったのをバス代にしたらいかがですか。お願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"}]},{"id":"topic-05","title":"４番目の男女共同参画のための品川区行動計画（第４次）素案の策定","agenda":"４番目の男女共同参画のための品川区行動計画（第４次）素案の策定","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"どういうふうに１次から２次、どういうふうにとらえていらっしゃるのか、改めてその辺の説明をしていただきたいと思うんです。生活だけで精いっぱいで、それは極めて国の問題、どういうふうにすみ分けをしていこうかなと思っているのかが３つ目に聞きたいところです。","respondent":"中山人権啓発課長","answer":"２点目のＤＶについてなんですが、ＤＶの支援というのはすごく難しいと思います。あるいはその先の生活をしていくための就労支援、すごく長期間、幅広い対応が必要になってくるところです。","id":"exchange-032"},{"speaker":"南委員","kind":"質問・要望","question":"経済的な部分のとりわけ整備が本当に求められていると思いますので、必要な関係機関への働きかけ、そのことをあえて申し上げたいと思います。この事業の推進の大前提ですから、どういうふうになっているかなというのがイメージできますので、教えてほしいと求めました。","respondent":"中山人権啓発課長","answer":"ここの1)の「ワーク・ライフ・バランス支援事業の促進」というところの一番上のワーク・ライフ・バランスコンサルタント費用等の助成というのは。平成２１年度から、ワーク・ライフ・バランス企業支援資金というものも新設するところです。","id":"exchange-033"},{"speaker":"南委員","kind":"確認","question":"企業というのがどういうふうな状況にあるのか、どの程度あるのか、全事業所も含めて。そういう確認をしたいなと思ったので、そんな質問をしたんですけれども、どんななんか尋ねました。","respondent":"中山人権啓発課長","answer":"連携しまして、６２ページに策定に至る経過、この体系に入ってきているところです。商業観光課ですとか、ものづくり・経営支援課のところでも、この視点に立った積極的なこういった施策を出していただいているところです。","id":"exchange-034"},{"speaker":"南委員","kind":"質問・要望","question":"もう少し品川区内の事業所がどういう状況にあるのか、あるいはという、そういうつかみをする必要があると思うんですね。ですから、品川区の、そういう姿勢と状況になっているんだという中身にしていただきたいということをあえてお願いしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"林委員","kind":"意見","question":"例えば事業家の集まりの東商だとか、そういうところで経営者の人たちと品川でこういう第４次を始めたいと、おそらく相談はされている。学校も含め、幼稚園も含め、保育園も含めとの意見を述べました。","respondent":"榎本人事課長","answer":"それで、特に経済的な差別というものが、区の場合、賃金体系がまずありませんので、そこが出発点で、男女平等の考え方が成り立っていると思います。１００％近い取得ということで、その辺を少しずつ、着実に進めていきたいという形で思ってあります。","id":"exchange-036"},{"speaker":"林委員","kind":"質問・要望","question":"特に女性が自立して、１人で子どもを生み、育てられる。できる範囲、品川区で取り組んでいってほしいと求めましたけれども、覚悟のほどを決めていただけますか。","respondent":"市岡総務部長","answer":"制度は徐々に整いつつあるので、あとは意識の問題はかなり大きいと思いますので、それらを考慮して施策の展開を努力していきたいと思います。","id":"exchange-037"},{"speaker":"須貝委員","kind":"質問","question":"すぐここに行けば、まちを歩けばわかるような、そういう表示とか何かというのはしてあるんでしょうか。ちょっと説明を求めました。","respondent":"中山人権啓発課長","answer":"そして、広報広聴課の区民相談室、それから子育て支援課のところにも婦人相談員という形でおります。何か悩んでいることを声に出していただければと考えていますが、相談窓口についての案内を積極的にしていきたいと考えています。","id":"exchange-038"},{"speaker":"須貝委員","kind":"質問・要望","question":"ありとあらゆるところに、ＡＴＭのところに入ればいろんな声が聞こえて、「大丈夫ですか」。は２４時間とかは無理だと思うんですが、そういうふうにすぐ救済を求められる、もしご検討願えればありがたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"}]},{"id":"topic-06","title":"５番目の総合区民会館第４期舞台照明設備改修工事請負契約","agenda":"５番目の総合区民会館第４期舞台照明設備改修工事請負契約","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"当然、これ、９月１１日から工期ということで、何日間か、何週間かは閉館になるわけですよね。大舞台の(3)のところの工事の状況によって、どのぐらいの工期というんですか、それを教えてほしいと求めました。","respondent":"阿部経理課長","answer":"今、今の予定では平成２１年７月２７日から９月１１日までの期間、大ホールを閉めるというふうに聞いております。今申し上げた期間、７月２７日から９月１１日までの間は閉館をして、工事をするという予定です。","id":"exchange-040"},{"speaker":"林委員","kind":"質問","question":"仕事の質からいって、どうせこの会社がずっとやるんだろうというようなことが見えているのかな。結果的に３社が辞退という事態が起きると、これからまだいろんな仕事が出てくると思うんだけれども、こういう状況は続くんか尋ねました。","respondent":"阿部経理課長","answer":"その結果として、先ほど申し上げたように、２社としては、特に商店街の工事ですので、工事が夜間しかできない。エントリーした会社が３社から４社を見まして、もう１社につきましてはご承知のとおり、この結果が続くというような認識は持ってはおりません。","id":"exchange-041"}]},{"id":"topic-07","title":"８番目の第６投票区投票所の変更","agenda":"８番目の第６投票区投票所の変更","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"校庭にずっと上がると、ちょっと坂になっているような気がするんですけれども、かなりの勾配のね。段差も結構あったと思うので、その辺はどういうふうに考えているかというのを教えていただきたい。","respondent":"早津選挙管理委員会事務局長","answer":"選挙当日には、そこに誘導をかねた職員を配置いたしまして、車いす等のサポートも行いたいと考えています。そのほか、体育館までの段差等については、段差解消にスロープ等を設置する予定です。","id":"exchange-042"},{"speaker":"林委員","kind":"質問","question":"養護学校の決まり事として、浅間台にするならずっと浅間台でやればいいのになと思うんだけれども、浅間台でやっちゃいけない理由があるんですか。ゼームス坂のあの養護学校じゃないと、投票所には当てはらまないんだというような理由があるんか尋ねました。","respondent":"早津選挙管理委員会事務局長","answer":"これは特にございません。第６投票区の中のセンターに近いのがこの大塚ろう学校のほうで、第６区の有権者の利便を全体的に考えたときに、こういう関係で選んでいるものです。","id":"exchange-043"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/829737?Template=document&Id=1816#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":63361,"voices":144}},{"id":"h21-20090415-14","meetingId":"h21-cm04","date":"2009年4月15日","dateIso":"2009-04-15","committee":"行財政改革特別委員会","time":"午後１時０２分～午後２時５３分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を22件整理しています。","topics":[{"id":"topic-01","title":"公有財産の有効活用に関すること","agenda":"公有財産の有効活用に関すること","exchanges":[{"speaker":"安藤委員","kind":"確認","question":"この財産がどうなるかという点でちょっと確認しておきたいなと思っている点がありまして、それがどういう状況で区のものになるのか。それとも貸与という形で借りるのか、そこら辺をちょっと確認しておきたいと思いまして、どういった感じになるんか尋ねました。","respondent":"久保田行財政改革担当課長","answer":"大崎第二地域センター移転に当たりましては、再開発組合のほうから無償で譲渡されるというふうに聞いております。そして、その後の扱いですけれども、無償譲渡の後、行政財産ということで、地域センターとして活用して扱っていくと聞いております。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"どういった専門家による、どういう調査をしていくつもりなのかということをお伺いしたいのと、していないのか。もし、しているのあれば、どのような意見があるのかというのも、ちょっとあわせてお伺いしたいと思います。","respondent":"久保田行財政改革担当課長","answer":"調査の方法ですけれども、先ほどもご説明いたしましたように、この辺の権利関係等もまずいろいろと調べていかなければならないかなと考えています。周辺の町会の方から、区のほうで特定の団体に区の施設をお貸しするということは難しいというところでは、お答えはしています。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"これからこの地域にこういう施設があってほしいというふうに考えている方もいろいろさまざまな立場で、さまざまな団体でいらっしゃると思うんです。そこら辺のお考え、この委員会で議論してきた上に立っての区の現時点での区民意見を聴取するという点でのお考えを改めてお伺いしたいと思います。","respondent":"久保田行財政改革担当課長","answer":"私どもは、先ほどご説明しましたように、今後、この跡施設の活用について調査・研究をしていくといったところです。区の行政需要等をかんがみまして、区としての方針も決めながらも、地域の方のご意見というものもお伺いをしていきたいと考えております。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"そういう非常に対話、やはり計画段階の地点からどれだけ区民の皆さんの声を伺うのかというところで、注意をしていただきたいと思うんです。パブコメに出す前の区の素案をつくる上での意見聴取という点では、どのように区民の声を聞くようなお考えがおありか尋ねました。","respondent":"久保田行財政改革担当課長","answer":"区が一定の方向性というか、我々としてもパブリックコメントという制度としては、そういった意味での活用をしていきたいと考えております。区民の方の代表です議員の方のご意見も伺いながら、幅広く区民の方の意見にも耳を傾けていかなければならないのかなと考えてはあります。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問・要望","question":"その中で２４時間生活をしている方々の意見を伺うですとか、あるいはもっと広い意味で、その当事者の声を伺うということが非常に大事だと思います。そこら辺に関してはいろいろなあらゆる手で聴取するよう努めていただきたいなと私は思いますので、要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"井上委員","kind":"質問","question":"長期的な行政需要として、品川区は今現在、どういったものの需要が必要であると思っているのかということ。これからも公有財産が出てきますけれども、その部分でどのように今回の取り組みも踏まえて考えていこうとされているのか、お伺いしたいと思います。","respondent":"久保田行財政改革担当課長","answer":"そういった中で多角的に検討を進めながら、施設全体の配置のバランス等も考えながら検討をしていきたいなと考えています。所管の委員会のほうに、今、品川区にある跡地はということで一覧表にまとめましてご説明をさせていただいているといったところがありますので。","id":"exchange-006"},{"speaker":"井上委員","kind":"質問・要望","question":"今、まずはパブリックコメントということではなくて、どういうものの需要があるのかというところの調査というのはなかなかないと思うんです。区民から１回、ほんとうに区全体としてどういうところが足りないんだろうという、ぜひ検討していただきたいと要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"須藤委員","kind":"質問・要望","question":"区民要望というといろいろなもの、そうではなくて、このスペースでどんなことが可能だろうということを何点か挙げていただいて。どういったことが可能だということを見せていただいて、また行政側に提言していきたいと思っていますが、そういう考えはいかがか尋ねました。","respondent":"久保田行財政改革担当課長","answer":"私どもとしましてもあそこの立地のところ、そういった立地の条件というのはかなりあるのかなとは考えております。どういう施設が必要なのかといったところも、私ども企画財政課のほうで主体になりまして、検討をしていきたいと考えております。","id":"exchange-008"},{"speaker":"阿部委員","kind":"質問","question":"このままであればどのくらい使えるものなのかというのを、もしかしたら前回伺ったかもしれませんけれども、もう１回教えてください。公有地がいつまでもこのような形であるというのは決して望ましい形ではないと思いますので、その可能性についてどうお考えなのか、説明を求めました。","respondent":"久保田行財政改革担当課長","answer":"耐震のお話ですけれども、先ほどもご説明いたしましたように、ここの建物が鉄骨造ということがありますので、また建築年が昭和４７年です。","id":"exchange-009"},{"speaker":"阿部委員","kind":"確認","question":"今のご答弁の内容のちょっと確認なんですけれども、シルバーセンターとあわせた活用についても検討の俎上に上るということですね。近隣の方との協議というのは、それもまた土地や権利関係も含めて一緒にやっていくというようなことも含めた検討になるのか、そこも説明を求めました。","respondent":"久保田行財政改革担当課長","answer":"平成２１年度ですけれども、まずは公有施設の調査・研究です。そうした上で、次のステップとしてそういうのも可能性としてはあるのではないかなという意味で、先ほどお答えさせていただいたところです。","id":"exchange-010"},{"speaker":"浅野委員","kind":"確認","question":"今回、話に出たかどうかは記憶にないのでもう１回聞くことになるかもしれませんけれども、またそれ以上有効に使えるようなものなのかどうか。ちょっとそこら辺、確認のために教えてほしいと求めました。","respondent":"久保田行財政改革担当課長","answer":"集会室の数ですけれども、３室というところでは変更はございません。２番目の広さのところが４２m2、次が３８m2程度になると伺っておりますので、そうした意味では現在よりも広さ的には広くなると考えております。","id":"exchange-011"},{"speaker":"浅野委員","kind":"質問","question":"広くなるということで、これは今まで使われていた方にとりましてはいい方向かなと思うんですけれども、今の利用の頻度というものは満杯なのか、あふれているのか、それとも少ないのかということがもしわかれば、その点も教えてほしいと求めました。","respondent":"久保田行財政改革担当課長","answer":"夜間につきましては５９.７％ということで、合計で５０.６％です。平成１９年度ですけれども、２月末現在で全体としまして、時間帯の合計としましては５６.６％というふうになっております。","id":"exchange-012"},{"speaker":"浅野委員","kind":"質問","question":"今度のこの土地の件についてどう使うかということで、これから、大体目安としていつぐらいまでに新しいものをつくり上げるのか。平成２１年度は、目安というものはどのくらいに置かれているのか、お伺いします。","respondent":"久保田行財政改革担当課長","answer":"跡地活用の今後の計画ですけれども、平成２１年度はそういった意味で、活用の可能性について調査・研究をしていきたいです。平成２２年度から工事とかそういったものはできるのかなと考えていますけれども、今、中期的な検討が必要なのかなというふうには想定をしています。","id":"exchange-013"},{"speaker":"浅野委員","kind":"質問","question":"シルバーセンターがあるので、例えば公園なんかもいいのかなと思ったりするんですけれども、さまざまな意見が地域の方からも出てくるかと思います。やはりしっかりとこの平成２１年度は調査・研究をしながら、また専門家の意見も伺いながら、。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"菊地委員","kind":"質問","question":"その辺で、需要として今後どうなのかというところがちょっと。実際にそういう調査をされて今度の新しいところに移ろうとしているのか、その辺がよくわからないので、ちょっとそこを教えていただけますか。","respondent":"久保田行財政改革担当課長","answer":"大崎第二地域センターということではなくて、大崎第二地域センターというものも含めて検討をする必要があるのかなとは考えているところです。","id":"exchange-015"},{"speaker":"菊地委員","kind":"質問","question":"単純に新しいところに移ったので、これまでのところをどういうふうに活用するかということよりも、実際に需要そのものがどういうふうに拡大をするか。活用について、やはりセンターそのものの需要に対する調査というのを確実にすべきではないかなと思いますけれども、どうか尋ねました。","respondent":"久保田行財政改革担当課長","answer":"この地域センター、今回のこの再開発に当たりまして、そういった意味での検討はしてきているところです。可能性の１つとしてはあるのかなというところではありますけれども、研究をしていきたいと考えているところです。","id":"exchange-016"},{"speaker":"菊地委員","kind":"質問・要望","question":"だから、もし開発組合のところできっちり調査をしたんだよというのであれば、そうした資料も含めて私はやはり議会に示していただきたいなと思います。意見だけ、ちょっと言っておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"}]},{"id":"topic-02","title":"の特定事件調査のまとめ","agenda":"の特定事件調査のまとめ","exchanges":[{"speaker":"須藤委員","kind":"意見","question":"２番目も「十分な対策」、その次３番も「経緯を十分踏まえて」、ちょっと読んでいてもう少しまとめられないのかなと。構わないよというのならそれまでだけれども、ちょっとそれが気になるところで、もう少し整理したらいいかなと思っていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"},{"speaker":"阿部委員","kind":"質問","question":"最後いろいろとお伺いして検討されたいということなんですが、全区的な公共施設の配置のバランスというようなことも少し出ていたかなと思います。これも一応言葉として出ていたほうがいいのではないかなと私は思いますので、ぜひご検討ほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"井上委員","kind":"質問・要望","question":"どういうふうなものを含めてこういう表現になっているのかということを確認をさせていただければなと思っています。少しここのところで含めてほしいなというのを私は要望したいと思っているので、そこも含めて、意図をお伺いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"本多副委員長","kind":"質問","question":"それ以前でも委員会のこの１年討議をしてきた中で、そのパブリックコメントに対してこの委員会で意見が出ていたものですから、また言ってください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"井上委員","kind":"質問・要望","question":"では、これについて変更を求めるものではありませんが、そういったところの議論を行政側がしっかりと把握をしていただければいいかなと思います。そのことを防災担当の方々にもしっかりと伝わるような形で文言をできれば入れていただければなという検討をほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/592995?Template=document&Id=5858#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":18778,"voices":58}},{"id":"h21-20090416-16","meetingId":"h21-cm04","date":"2009年4月16日","dateIso":"2009-04-16","committee":"街づくり特別委員会","time":"午後１時０２分～午後３時３６分","status":"正式会議録","sourceType":"formal","overview":"街づくり特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を10件整理しています。","topics":[{"id":"topic-01","title":"品川区震災復興マニュアル","agenda":"品川区震災復興マニュアル","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"どういうふうに考えているのか、その理由を教えていただきたいのと、実際は通常の状態ではない事態が当然想定されるわけですよね。このマニュアル自体が職員の対応についてのというご説明であれば、そういう点はどんなふうに考えているのか教えていただけますか。","respondent":"中山防災課長","answer":"基本方針を被災後２週間以内に策定することができるかどうかということが基本にありまして、これには事前の準備が当然必要になってくるです。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問","question":"阪神・淡路大震災の経験の何を生かすのかという点でお伺いしたいのは、阪神・淡路大震災では、すごくやっぱり混乱したというふうに伺っています。通常の形でも問題はあると思っていますけれども、通常ではない状態がつくられるわけですから、その考え方を教えていただけますか。","respondent":"中山防災課長","answer":"おおむね６カ月以内と申しましても、事前に想定をしておかないと、６カ月以内に基本計画の策定は正直なところ難しいと考えています。行政が公助でやるには限りがあるということでご理解いただきたいと思います。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"こういう場合に具体的にどうするのかというふうに事前に整理しておかないと、職員も含めて被災者ですから、その点を伺わせていただきたい。そういった部分で言えば、何らかの支援も必要になってくるのではないのかなというふうに思っているんですけれども、その点はいかがか尋ねました。","respondent":"中山防災課長","answer":"２つ目の質問のほうからお答えしますけれども、要は、半壊・半焼の住宅の居住者は、実際にはどこにいるのかということです。したがいまして、委員のご指摘のとおり、できるだけ事前にそういう体制整備をしていくということは必要になろうかと思います。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"あれば、いろいろと地震の経験で一部進んでいる話も伺いますけれども、手順はどんなふうに考えているのか教えていただきたい。こういう計画はつくり倒れになってしまったら元も子もありませんから、それだけに少し具体的に伺っているんですけれども、ご説明いただけますか。","respondent":"岩田防災まちづくり事業部長、中山防災課長、片田建築課長","answer":"これは一番最初に防災課長がご説明しましたように、発生後、まずプロセスの大まかな枠組みを今決めたところです。１つの形とすれば、１つの大きな柱… 東京都が仮設住宅に関しては検討しています。棟数については、現在のところ、私どもでまだ考えてございません。建物について引き続き上部構造評点が１以上であれば住み続けられる建物もあれば、避難所のほうでの生活をしていただくようなことになるかと思います… 何世帯必要なのか、何軒必要なのか、そういう意味で、まだつかんでおりませんということです。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひ補っていただきたいということと、その大事さというのが、両面出てくると思うんです。やっぱり自分の家も住宅の耐震化を進めてみる、こういう機運にもつながってくると私は思っているので、ぜひ補って進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"山路委員","kind":"意見","question":"この概要版はやっぱり全区民が読んでほしいし、どこら辺までどういう形で配布されていくかということと、それにはかなりの時間がかかると思うんです。関係ある人たちが動いてくると思うんですが、どのくらいの期間を見ているか、その２点を聞かせてくださいとの意見を述べました。","respondent":"中山防災課長","answer":"私どものいわゆる震災復興の手引きだと言ったのは本冊のほうでございまして、今、委員ご指摘の、ご説明申し上げました概要版は区民向けのものです。","id":"exchange-006"},{"speaker":"南委員","kind":"意見","question":"周知のところと、その辺のプロセス、どんなスケジュールでやっていくのかということをちょっと聞きたいなと思うんです。まちをどうやって挙げて復興に当たっていくかというところは、それでどういうふうな日程で考えているのかということを聞きたいんですとの意見を述べました。","respondent":"中山防災課長","answer":"早急に周知の方法については検討してまいりますので、いましばらくお待ちいただきたいと思います。","id":"exchange-007"},{"speaker":"南委員","kind":"質問・要望","question":"１月末にというふうなことで、できたばかりだとお聞きして、思うんです。３,０００部だから、増刷も含めて、そういうことを率先してやっていただきたいということをちょっと改めて申し上げておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"西本委員","kind":"質問","question":"部長の答弁の中で、個人財産を含めて区画整理をしていくという方向、災害に強いまちを復興しながらつくっていきますよという意味なんでしょうか。出向の方はいらっしゃるにせよ、そこは今後どういうふうに持っていこうとしているのかなというところが非常に心配なんですが、その２点お伺いします。","respondent":"岩田防災まちづくり事業部長","answer":"今のところはいろいろなものに対応していかなければいけないんですけれども、当面は、これはこれからの話になります。庁舎にレベル０からレベル９までの対応マニュアルが全部しまってありまして、これから１つ１つ積み上げていきたいと考えています。","id":"exchange-009"},{"speaker":"西本委員","kind":"質問・要望","question":"ですから、認識が高いですから、そういう方法も考えていいのではないかなと考えています。そこのところだけお考えをお願いします。","respondent":"岩田防災まちづくり事業部長","answer":"２ページの図２というところがありますけれども、災害復旧対策という、いわゆるこの部分なんです。一般の方に対しては、こういったものが必要だと思いますので、これは防災課長のほうで十分検討します。","id":"exchange-010"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/504318?Template=document&Id=6384#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=16&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":25071,"voices":46}},{"id":"h21-20090511-6","meetingId":"h21-cm05","date":"2009年5月11日","dateIso":"2009-05-11","committee":"区民委員会","time":"午後１時０２分～午後２時２５分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を21件整理しています。","topics":[{"id":"topic-01","title":"の定額給付金の進捗状況","agenda":"の定額給付金の進捗状況","exchanges":[{"speaker":"稲川委員","kind":"質問","question":"どういったご苦労があるのか、この問い合わせ件数が１万４,０００件というのは、どういった問い合わせがあったのか。そのトラブルをどうやって回避したのか、それを教えてもらいたいです。","respondent":"中山定額給付金担当課長","answer":"実務的なスキームというのでしょうか、ある意味では、事務を進めながらその状況に合わせて対応してきたということがございました。","id":"exchange-001"},{"speaker":"渡部委員","kind":"確認","question":"その確認が１つ。例えばそういう部分の転居だなんだというのがあったりしておくれていたりする部分があるのかということをお伺いしたいのと、私も実際に申請しました。","respondent":"中山定額給付金担当課長","answer":"それから、確かに可能な限り１００％お届けしたいという意味で事務はやっておりますというご説明は予算特別委員会でもしたところです。ゆうちょ銀行のほうの扱いがまとめてやるという対応になっているために、こうなると、今申し上げたような例外もあるというふうなことです。","id":"exchange-002"},{"speaker":"渡部委員","kind":"質問","question":"８月末でしょうか、９月ぎりぎりの辺で申請書はお届きでしょうか、何らかお出しいただいたでしょうかというようなやりとりは考えられていますか。郵便の紛失とかも考えられたりするわけで、そのままになってしまう危険性というのもちょっとあると思うので、その辺はいかがなんか尋ねました。","respondent":"中山定額給付金担当課長","answer":"あまり多く今の段階でやっても逆の混乱もあるので、ある程度時期を絞って今のようなまだの方についての確認は何らかの形で、これは一般広報とは別に考えていきたいというふうに思っております。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問","question":"現金給付ということで６月中旬からということなんですが、何かちょっと恐れもあると思うので、そこら辺の対策は何かお考えになっているのかお伺いします。","respondent":"中山定額給付金担当課長","answer":"ただ、実は代理申請のあり方というのが非常に難しいのかなと考えています。その代理の方の証明になるもの、これは振り込み以上に非常にリスクがあるというのは認識しておりますので、それとさっき申し上げた警備員の立ち会い。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問","question":"事業の目的について改めてお伺いしたいのと、あと、実施した後にどれだけその目的が達成できているのかという区の見解もあわせてお伺いします。あるいは地域振興基金などの案内も送ったと思うんですが、そちらのほうの状況もどうなっているかということをちょっとお伺いしたいんですけれども。","respondent":"中山定額給付金担当課長、諸岡商業・観光課長、秋山協働・国際担当課長","answer":"基本的にはご案内のとおり、国が生活支援、経済対策という観点から全国の自治体に１００％補助の中でやっていく。… なお、前回ご報告申し上げましたように、販売に当たっては主に区内の郵便局４３カ所での販売です。それから区商連の事務局を合わせて６４６冊売れておりま… 私のほうから、地域振興基金のほうの状況をご報告します。","id":"exchange-005"},{"speaker":"安藤委員","kind":"質問","question":"その事業の目的である生活支援と経済対策という点で、やっぱり一時的なこういった給付金の支給では根本解決にやっぱりならないと思うんですね。そういった点で、区として追加の根本的な営業と暮らしを支える対策がどうしてもこれだけではなくて、お考えをお伺いしたいと思います。","respondent":"宮地地域振興事業部長","answer":"実際には生活の支援、１番で事業を開始することができましたし、着実に戻ってきているという理解でおります。こちらの状況も見ていかなければなりませんし、常にアンテナを張りながら今後の経済対策も考えていきたいというふうに考えております。","id":"exchange-006"},{"speaker":"安藤委員","kind":"意見","question":"ぜひお願いしたいんですが、そういう根本的な対策というのがどうしてもやっぱり必要になってくると思いますので、いろいろ研究もしながらぜひお願いしたいなというふうに思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"若林委員","kind":"質問・要望","question":"たしか受け取りませんというような表記の欄があったと思うんですけれども、そこら辺の数があるのかないのか、わかれば教えてほしいと求めました。品川の今の状況、取り組みといいますか、どういうふうに対応されているのか。","respondent":"中山定額給付金担当課長","answer":"このＤＶの方というのは、要するに、ある意味では福祉的な制度として考えて幾つかのところが実施するという方針を立てているところですので。じゃあ、現在、子ども未来事業部の所管の中で給付事業について対象を決めていく考えだということを検討しているところでございまして。","id":"exchange-008"},{"speaker":"若林委員","kind":"質問","question":"では、相談窓口のほうですけれども、そうすると、事務の終了というと、９月１６日まで。この間にあのフロアを使ってさまざまなイベント、行事が予定されて、環境情報活動センターの部分も含めて、そこら辺はどうなるんか尋ねました。","respondent":"中山定額給付金担当課長","answer":"当初、非常に多くのお客様がおいでになったときは、かなりフロア全体を使ってやっておりました。これからまた６月には現金給付だとかを考えますと、この事務が行われている間、また個別に今後としても相談していく中でやっていきたいと思います。","id":"exchange-009"},{"speaker":"若林委員","kind":"質問・要望","question":"それを今、この７３％の方が実際に受けている中で、逆にそういう区民の方たちに対して、これはばらまきですよ、今さら辞退してと言えるのでしょうか。そういう議論の場ではありませんので、ちょっと不見識な品川区議会議員としての発言があったと私は認識をしておりますので一言言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"安藤委員","kind":"質問","question":"もう１つ別な質問なんですけれども、いいですか。ちょっと具体的なケースでお伺いしたいんですけれども、その方は、こういう方は支給はどうなるのか具体的にお伺いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"安藤委員","kind":"質問","question":"住民登録がない方は、改めて給付期間中に登録すれば受け取れるということなんですけれども、はるか遠くに住民票がある方というのは、その自治体に申請をするということになるということなんか尋ねました。","respondent":"中山定額給付金担当課長","answer":"そういうことです。地方に住民登録があれば、そこで受け取る形になります。","id":"exchange-012"},{"speaker":"宮崎副委員長","kind":"質問","question":"そこのところの考え方を伺いたいということと、３月１９日までに郵送した、例えば届かなかったところがあるかどうか。お知らせを出したんだけれども届かなかったということがあれば、どういうふうに対応するのかというところを、ちょっとそこのところを伺いたい。","respondent":"中山定額給付金担当課長","answer":"これは居住ですから、お住まいが持たれるという前提になりますけれども、その段階で対象になってくるということをご説明したわけです。これは届かないのが当たり前ですので、こういう方は逆に言うと、届かなかったかどうかの確認のしようがないです。","id":"exchange-013"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"場合によったら１軒１軒訪問して確認して、わからないというか、そういう方が非常に多いんですよね。同じような手段で確認ということになると、やっぱり確認できないということになってくると思うんですけれども、私としては一定程度。","respondent":"中山定額給付金担当課長","answer":"分析する中で可能なものについては検討していく余地はあろうかなというふうに思っておりますけれども、申請がないことを電話で確認するケースもある。","id":"exchange-014"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"ですから、訪問調査なんかも含めてやったほうがいいなというふうに思ったところなんですけれども、ぜひ検討していただきたいと。国会で議決された、そういう対応をとっていますけれども、少なくとも漏れなく自治体のほうでやってほしいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"}]},{"id":"topic-02","title":"の区民活動交流施設（旧八潮南小学校跡）の整備","agenda":"の区民活動交流施設（旧八潮南小学校跡）の整備","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"プールの関係なんですけれども、こちらはどうなるのかなというのがわからなかったので質問したいのと、あと、これまで学校施設ということで避難所で９０６人分の避難所機能ということがあったんですが、これはどうなるのかということをお伺いしたいと思います。","respondent":"堀越文化スポーツ振興課長","answer":"ただ、その部分について、それは地域の防災協議会のほうでもこれから検討していこうというふうな話をいただいているというふうに聞いております。それと、済みません、ご質問いただいてあれなんですが、あわせて１点、説明が漏れておりました。","id":"exchange-016"},{"speaker":"安藤委員","kind":"質問","question":"これからそれ以外に全区からの利用希望とかというのがあった場合は、そういうものにも対応するということでよろしいのでしょうか。そこら辺はまだ検討中だというお話だったと思うんですが、その検討の結果どうなったのかということをあわせて聞きたいと思います。","respondent":"堀越文化スポーツ振興課長","answer":"それと、利用希望の調整、全区からということですが、３点目の管理の部分も含めて、運営管理についてはこれから検討していきます。かなり大規模な施設ですので、そういうものを踏まえて、どのような形の管理になっていくかということをこれから検討をしていくです。","id":"exchange-017"},{"speaker":"安藤委員","kind":"質問・要望","question":"これからご意見を聞きながら、とりあえず置いておくということなので、活用方法などを検討していただきたいなと思います。一定どれぐらいまでにめどを、運営の形態をどうするかということをめどをつけていきたいと区としては考えているのか、お伺いできればと思います。","respondent":"堀越文化スポーツ振興課長","answer":"検討中ということで、設備管理等について、日常的にきちんとした体制が必要であるというふうに考えています。実施設計がこれから秋に入ってきますので、それぐらいか、年内ぐらいには一定の方向性をつけていきたいと考えているところです。","id":"exchange-018"},{"speaker":"安藤委員","kind":"意見","question":"区が責任を持てるようなところ、そういう方向でぜひ検討をしていく必要があると思いますので、どうぞよろしくお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"},{"speaker":"宮崎副委員長","kind":"質問","question":"１点だけなんですけれども、駐車場とか駐輪場とか、そういうスペースというのはつくる計画なんか尋ねました。","respondent":"堀越文化スポーツ振興課長","answer":"協議を進めているところなんですけれども、済みません、給食室について説明が漏れていました。その裏に、駐輪場ですとか、駐車スペースがありまして、そういうところの利用について、全体の実施設計を含めて検討していきたいと考えております。","id":"exchange-020"},{"speaker":"宮崎副委員長","kind":"質問","question":"はもうこの旧校舎の今のグラウンドといいますか、トラックの間の広場みたいな、これはどういうふうに使うのか。もう１回聞きたいのと、かなり利用もあるのかなと思うんだけれども、そこら辺の見通しというのはどういうふうに検討されているのか尋ねました。","respondent":"堀越文化スポーツ振興課長","answer":"屋内のイベントスペースとして、その下の２教室分のところをご紹介したんですが、そういう広場的な位置づけで検討していきたいと考えております。","id":"exchange-021"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/911630?Template=document&Id=2548#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":26335,"voices":60}},{"id":"h21-20090511-7","meetingId":"h21-cm05","date":"2009年5月11日","dateIso":"2009-05-11","committee":"厚生委員会","time":"午後１時０２分～午後３時４７分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を17件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"今後の予定のところを、もうちょっとお伺いしたいんです。平成２２年度工事竣工で開設となっていたので、なぜ先になったのかというあたりも、ご説明を。","respondent":"冨岡高齢者福祉課長","answer":"さまざまな躯体のほうの耐震の問題とかが出てまいりまして、今の段階では、平成２２年の早い時期になるかなという予定です。そういう関係で、平成２２年度に竣工で、平成２３年度の頭ぐらいかなという形で、今、進めているところです。","id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問・要望","question":"それから、補助金のことについても、ちょっとお伺いしてもいいでしょうか。多分、１部屋の広さが違ってくると思うんですが、その辺の考え方がどうなっているのか説明を求めました。","respondent":"冨岡高齢者福祉課長","answer":"通常の４３０万円とかというのよりは、申しわけありませんが、改修型だと若干下がってくるです。居室面積につきましては、ユニット型が１３.２m2、従来型については１０.６５m2です。","id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問","question":"居室の面積を、今、教えていただいたんですが、従来型の１０.６５m2を確保するという受けとめ方でよろしいんでしょうか。平成２０年度から２２年度に開設の場合は１.５倍になるという、この辺の扱いはどうなっているのかも、説明を求めました。","respondent":"冨岡高齢者福祉課長","answer":"改修型の創設につきましても、創設と同じでございまして、ユニット型には促進係数がありますけれども、従来型については促進係数はありません。それから、最初のほうの質問ですけれども、従来型の個室を基本に考えて、多面的に検討を、今、しています。","id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問","question":"居室のところは多面的にと、東京都の補助金の絡みとかの折衝で、いつまでに決まるとか、その辺の時期的なものがわかったら説明を求めました。","respondent":"冨岡高齢者福祉課長","answer":"東京都の補助金の内示は、たしか６月にありますので、今、基本設計を詰めているというのは、今月ぐらいまでには、ある程度固めをしまして、その最終的なもので決まっていくということで、それで東京都の内示に向けて動いていくです。","id":"exchange-004"},{"speaker":"浅野委員","kind":"質問","question":"８０人程度という定員ですけれども、そういうようなことは特に考えていなくて、個別に個室があるだけというイメージなのでしょうか。それと今回の方針の違いというのでしょうか、認められつつあるのかということを、わかる範囲で教えてほしいと求めました。","respondent":"冨岡高齢者福祉課長","answer":"今回、ユニット型がちょっと困難であると考えている一番の理由は、やはり、現在ある学校の施設をそのまま改修して使うということ。東京都にもあまり例がないわけですけれども、それが合理性ということで、東京都にもご理解をいただいているです。","id":"exchange-005"},{"speaker":"浅野委員","kind":"意見","question":"そういうような事情が、東京都のほうに認められているのか、認められつつあるということで認識をさせていただきました。今回は２５％ぐらいになっているんですけれども、ショートステイが増えるというような考え方でされているのかどうか、そこら辺をお願いいたしますとの意見を述べました。","respondent":"冨岡高齢者福祉課長","answer":"ショートステイ１０％という規定は、今後、さまざまな事情でショートステイの利用が今まで以上に増えていくだろうという可能性も含めまして。大体２０人ぐらいということになりますと、そういう意味も含めまして、ショートステイ２０人としたところです。","id":"exchange-006"},{"speaker":"浅野委員","kind":"質問","question":"平成２６年に個室化７０％に参酌標準があると思うんですけれども、この個室も、そのパーセントの中に入れられるものなのかどうか。こちらの将来的な計画等、考え方がありましたら、教えてほしいと求めました。","respondent":"冨岡高齢者福祉課長","answer":"これまで独自の考え方によりまして施設整備をしていますし、新たに長期基本計画で、特別養護老人ホームの整備という形で決めていったわけです。その中で決めてまいりますが、そういう形で、前々から申したとおり進めてまいりたいと思っているところです。","id":"exchange-007"},{"speaker":"鈴木（真）委員","kind":"確認","question":"さっきの話ですと、１年ぐらいで終わるんですか。そこら辺がちょっと、工事の日程とか、確認をしておきたいと思ったのが１点です。","respondent":"冨岡高齢者福祉課長","answer":"このペーパーを出した説明会ということは、今までの経緯がありますので、検討会の中で経過報告をさせていただいたです。校庭自体の一般開放の問題がありますので、うまくぶつからないように対応してほしいとか、そういう話がございました。","id":"exchange-008"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"平成２３年度に開設となると、ずっと特別養護老人ホームをつくっていと求めてまいりましたので、ほんとうによかったなと思っています。６月の東京都の内示に向けて基本設計を終わらせ、設計と指定管理者で運営するところは、全く別にされるということで進められているのか尋ねました。","respondent":"冨岡高齢者福祉課長","answer":"できるだけユニット型に近いような形を、当然、設計の中で目指していきたいという方向性を持っております。簡易プロポーザルの基本設計ということで実施をして、八潮南小学校も含めて実施をしておりまして、実施設計の流れの中で。","id":"exchange-009"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"ここごとに共有スペースが大体２カ所ぐらい設けられる、１０人に一つぐらいの共有スペースという感じになるということでいいのでしょうか。そういう点では、避難所機能ということでは、これからどういうふうになっていくのかということについても、お聞かせほしいと求めました。","respondent":"冨岡高齢者福祉課長","answer":"それから、説明会につきましては、当然、法律どおり、工事説明会等を、スケジュールに従いまして実施していくという予定です。今の段階では、図面をお見せできませんので、ユニット型の居住環境を試行しているというところでご理解をいただきたいと考えています。","id":"exchange-010"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"自分でなかなか判断できないと思うので、まずどうしたらいいのかということでは、ここに電話をかけてもいいという受けとめ方でいいのでしょうか。やたらに心配しないで冷静にきちんと対応してほしいという意味では、もう１回、お願いします。","respondent":"山岡健康課長","answer":"場合によっては電話で対応しますので、特にご自分で自己判断して、これはいいというふうに考えなくても結構です。これからやるイベント等でも、これをお配りする予定です。","id":"exchange-011"},{"speaker":"飯沼委員","kind":"質問・要望","question":"フェーズ５まで上がっていますよね、その上がフェーズ６という結構厳しい状況と思う中で、私はその辺もすごく心配しています。その辺の判断は、どういうふうに行われて、どういうふうに伝達されるのかというところを説明を求めました。","respondent":"山岡健康課長","answer":"要するに検疫で隔離している形ですので、今の段階では、特段のイベントに対する措置は考えておりません。あるいは東京都からの何らかのアクション、あるいは要請等に基づいて、危機管理対策本部で判断するということになろうかと思います。","id":"exchange-012"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ぜひ回覧板でも回していただきたい。何とか、その辺工夫をしていただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"鈴木（真）委員","kind":"確認","question":"その中で確認だけ。たしか４,０００万人分ぐらいの対応ができているという話も聞いているんですけれども、どのぐらい対応していただいているのか、一応安心のために。","respondent":"吉田品川区保健所保健予防課長","answer":"区が持っているものとしては、合わせて３,２００人分ぐらいです。まだ疑いの方も出ておりませんので、それには一切手をつけない状況です。","id":"exchange-014"},{"speaker":"鈴木（真）委員","kind":"意見","question":"万が一のことがあったら、区のほうも大変ですし、今の段階でも、いろいろ人的にも大変ご苦労なさっていると思いますが、これからも何もないことを望みながら、対応のほうをとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"},{"speaker":"阿部委員","kind":"質問","question":"１点だけ教えてください。急に相談が増えたときなどに、どういった体制をすぐに組めるのか、その辺のお考えを説明を求めました。","respondent":"山岡健康課長","answer":"一番多い日で３０件台で、１桁台の日もございましたので、それほどの件数ではないと考えています。直ちに保健師のほうの対応ということで、保健所のほうはかなりの数の保健師が詰めますので、そこで対応するということになろうかと思います。","id":"exchange-016"},{"speaker":"阿部委員","kind":"確認","question":"保健所って、今は保健師が何人いらっしゃるのですか、基本的な質問ですみません。つまり、このセンターは、最終的に区内だけで対応していくのかどうかということをお伺いします。","respondent":"山岡健康課長","answer":"基本的には、区の保健師、要するに専門職で対応することを考えております。保健所、保健センターで約３０人の保健師がおりますので、そこで一定程度の数を集めてということになろうかと思います。","id":"exchange-017"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/854582?Template=document&Id=3234#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":14616,"voices":45}},{"id":"h21-20090511-8","meetingId":"h21-cm05","date":"2009年5月11日","dateIso":"2009-05-11","committee":"建設委員会","time":"午後１時０３分～午後１時５０分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を15件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"井上委員","kind":"意見","question":"私はちょっと認識不足ですけれども、毎年、同時開催だったのかということも含めて。今年、そういう変更が何点かあると思うんですけれども、どういう経過でこういう形になっているのかという２点をお願いいたしますとの意見を述べました。","respondent":"工藤環境課長","answer":"わんぱく相撲に関しましては、今年、ＥＣＯフェスティバルと同時に開催して２回目ということになりまして、昨年から同時開催という取り組みです。","id":"exchange-001"},{"speaker":"井上委員","kind":"質問","question":"来年に向けて、もっと地域で活動している小さな活動団体もできるようになるほうが望ましいと思うんですが、そういったところの計画もあるのかどうか。参加団体として申し込んだけれども、参加できなかった人たちがいるのかどうか、その辺の参加団体についての様子を、ちょっと説明を求めました。","respondent":"工藤環境課長","answer":"それがまず１点目です。原則は、すべてこちらの参加は可能になっておりまして、今の実態はそうです。","id":"exchange-002"},{"speaker":"井上委員","kind":"質問","question":"先ほど、募集と、実行委員会の方たちの口コミということだったんですけれども、広報の募集に対する申込みの件数の状況はどうだったのか尋ねました。","respondent":"工藤環境課長","answer":"広報から何件とか、口コミというか、いろいろなつての比率は、ちょっと手元に資料はございませんけれども、大体、８対２ぐらいの割合だと考えています。","id":"exchange-003"},{"speaker":"井上委員","kind":"質問・要望","question":"ただ参加してみませんかというのではなかなか難しいのですが、そういう形での周知がされるように、ぜひ工夫をしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"石田（慎）委員","kind":"質問","question":"このタクシーを区内で広げていこうという考え方があるのか、ただこういうものありますよという紹介にとどまるのか、その辺だけお願いします。広げていこうということだと思うんですが、自転車タクシーはどういうようなお考えなんですか、説明を求めました。","respondent":"工藤環境課長","answer":"考え方としては、こういった乗り物がありますという紹介を、広い意味の環境の中の一つだと考えております。これが区の施策とどう連動するかという部分につきましては、大きな意味での環境の一つだということですので、別の部分と考えております。","id":"exchange-005"},{"speaker":"菊地委員","kind":"質問","question":"図面のところを教えてもらいたいんですけれども、４ページにある全体的な絵で、これは全部中央環状線から入ってきた車が湾岸へ抜ける路線ですよね。逆に、湾岸のほうから入ってくる路線は、これからまた別に説明会をやったりしていくということなんか尋ねました。","respondent":"松代都市計画課長","answer":"左側のほうがアウト、右側のほうがインという形で、料金所１カ所で出入りができるという形になるかと思います。高速湾岸から五反田・池袋方面へ向かう方が、ここでご利用いただくというものです。","id":"exchange-006"},{"speaker":"菊地委員","kind":"意見","question":"住民の皆さんも、仕事との関係で、平日の７時からやるということそのものがすごく難しいのではないのかという気がするんです。その辺のことを、東京都のほうはどういうふうに考えて、こういう平日の設定をしているのかなとの意見を述べました。","respondent":"松代都市計画課長","answer":"土曜日であろうと、日曜日であろうと、地元で求められる説明会等にはきちんと対応するという姿勢で臨んでおります。そういったことで、地元といろいろと調整されて、この日程になっているものと推測しております。","id":"exchange-007"},{"speaker":"菊地委員","kind":"質問","question":"自治会連合会ですか、とらえていらっしゃるのか、どうか。そこを、もう少し説明をお願いします。","respondent":"松代都市計画課長","answer":"個別の説明等に当たっている中で、より多く皆様が参加できる日程、時間等を調整したものと把握しております。インの部分につきましては、薄い部分がありますけれども、そこから今回の品川線に入って行くということでありますので、訂正して、お詫びいたします。","id":"exchange-008"},{"speaker":"菊地委員","kind":"質問","question":"そうすると、またその点についての説明会が開かれるということになるんか尋ねました。","respondent":"松代都市計画課長","answer":"申しわけございません、今回は、今言いましたように、このジャンクション、アウトの部分の橋脚下部工事の説明です。今後、上部工、それから、今申し上げました周辺の付帯工事といったものは別途、発注され、かつ説明会がなされると聞いております。","id":"exchange-009"},{"speaker":"三上委員","kind":"質問","question":"今の説明の中で、区民住宅は１,０５６戸ということでしたが、その中で、今回、募集するのは傾斜型の４２６戸。要するにファミーユ関係は除くということなんか尋ねました。","respondent":"柏原住宅担当課長","answer":"建設型の住宅でファミーユと言っているものがありまして、そのうちの５団地はこの中に入っております。ですので、下神明、西五反田西館、西五反田東館は抜いてあります。","id":"exchange-010"},{"speaker":"三上委員","kind":"質問","question":"この制度が始まったときは、毎年５％上がってきたという形できているんですけれども、もうそろそろ上限にきているところも出ているのではないのか。上限まで来た段階で、家賃を最高額に設定するときに、近隣との絡みから言って、現在、そのあたりはどんな感じになっているんか尋ねました。","respondent":"柏原住宅担当課長","answer":"一番古いところは最高額に近いところに、既にきておりまして、近傍と比べますと、やはりちょっと若干高い状況になっている。同じような間取りの、同程度のところまできていると認識しております。","id":"exchange-011"},{"speaker":"三上委員","kind":"意見","question":"そうすると、募集したって、そんな高いところだったら、公的住宅だといったって意味が何もないという話になりかねないですよね。そこらあたり、国の制度そのものを、それを改善しようという意見は、全く各自治体から出されてきていないものなのか、どうかとの意見を述べました。","respondent":"柏原住宅担当課長","answer":"家賃を下げるであるとか、制度を大きく変えるとか、そういったところまではまだ至っていない状況です。今年度も、東京都、それから国等に強く要望を出していったり、この制度で何かもう少し工夫ができないかとか、それは鋭意、現在も検討しています。","id":"exchange-012"},{"speaker":"三上委員","kind":"質問","question":"制度そのものがもうおかしくなっているんですから、ある意味では、連携しながらでも国にどんどん言っていく必要があるのではないかと思うんです。今からどうするんですかということについて意見をどんどん言っていく必要があると思うんです、そこらあたりはどうなんでしょう。","respondent":"柏原住宅担当課長","answer":"ほかの区との連携も図りながら、ほかの区とも連携しながら、強く訴えていくような検討も含めてやっていきたいという思いはあります。","id":"exchange-013"},{"speaker":"三上委員","kind":"質問","question":"そういう状況が見えてくるわけですから、これはやっぱりどこかでやっぱりきちっとやらなければ、空き家ばっかり増やしていく。もう先が見えているわけだから、そこのところはやっぱりきちっと、何らかの形で言っていってもらいたいと思うんです。","respondent":"岩田防災まちづくり事業部長","answer":"２３区の区長会を通じて、この間、ずっと国に要請をしてまいりました。要綱改正に向けて検討するというふうに明言をされておりましたので、私ども、引き続き国には要望をしてまいりたいと思っています。","id":"exchange-014"},{"speaker":"三上委員","kind":"質問・要望","question":"その要綱改正ということが、今、出たので、とにかく実現できるように、またさらに一生懸命努力していただきたいということを、お願いしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/814084?Template=document&Id=3942#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":13059,"voices":50}},{"id":"h21-20090511-9","meetingId":"h21-cm05","date":"2009年5月11日","dateIso":"2009-05-11","committee":"文教委員会","time":"午後１時０４分～午後３時２３分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を53件整理しています。","topics":[{"id":"topic-01","title":"平成２１年度新入学学校別増減要因一覧","agenda":"平成２１年度新入学学校別増減要因一覧","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"それぞれ、教育委員会がどういうふうに評価しているというのか、そういうところの見解を教えていただきたいなと思います。そこをどう見ているのか、どう分析しているのか、そこをご見解を教えていただけたらと思います。","respondent":"富田学務課長","answer":"指定校変更の数ですが、２００人ほどおりましたが、今年度は１６７人ということで３０人ほど減少しております。中学校につきましては指定校変更、区域外就学は減少しておりますが、小学校ほどの大きな開きではないと考えているところです。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問","question":"この増減要因一覧というものは、学校選択制が始まってから毎年出されているんでしょうか。何か目的があってこういう傾向を追っているわけでしょうから、この傾向が生まれていることをどういうふうに検証し、ご説明いただけますか。","respondent":"富田学務課長","answer":"この増減要因一覧というものは、学校選択制を開始して、ずっと毎年提出、ご報告をさせていただいているものです。学校選択制を実施しておりますけれども、指定校変更もあり、文教委員会にも報告を毎年させていただいているです。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問","question":"町会の方とかから伺うと、みんな言うのが、子どもを地域で育てるという視点が学校選択制によって崩されているのではないかということをよく伺います。どういう検証、見直しが必要なのかということも必要だと思いますし、学校選択制を見直すべきだと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"川西委員","kind":"質問","question":"すいません、ちょっと基礎的なことでまだ理解していない部分があるんですが、伺いたいと思います。ですから、区域外就学というのはそういう人たちのことをいうのか。","respondent":"富田学務課長","answer":"左側の１０月１日の登録者数というものは、住民登録をしている方々の数ということで、それぞれの学校の従来の通学区域内に登録している児童の数です。区内で通学区域以外の学校の希望で移られた方は、指定校変更ということで取り扱いをしております。","id":"exchange-004"},{"speaker":"川西委員","kind":"質問","question":"そうしますと、以前、１１月ごろでしたか、学校が書いてありまして、受け入れ予定数というものがこの委員会で発表されたように思います。それとこの数字との関係というのは、結果としてどうなっているんか尋ねました。","respondent":"富田学務課長","answer":"予定数を超えるんだけれども、オーバーして受け入れ、抽選をしなかった学校というところもかなりの数あるです。２８番大間窪小学校といった学校も、当初の予定を若干オーバーするけれども、就学指定をしたという経緯です。","id":"exchange-005"},{"speaker":"川西委員","kind":"質問","question":"抽選後の戻りという中で、さっき説明されたんですけれども、抽選をした学校というのはどこでしたか。もう一回説明を求めました。","respondent":"富田学務課長","answer":"抽選をしましたのは、６番の城南第二小学校、８番、第二日野小学校、こちらは日野学園です。１０番、第三日野小学校、１５番、原小学校、伊藤学園です。","id":"exchange-006"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"１点だけお伺いしたいと思います。そういうことを、書いてもいいみたいなことというのが、そういう点のフォローということはどう考えられているのかなということを教えていただきたい。","respondent":"市川教育次長","answer":"その対策ということで、教育委員会としてどうなのかということ、これは基本的に学校がどう対応するかということは考えるわけですけれども。こういったことを考えますと、そのことに教育委員会としても私たちは持てる力を注いでいく、こういう体制で臨んでいきたいと考えています。","id":"exchange-007"},{"speaker":"西本委員","kind":"質問","question":"そこで、抽選をしたと、抽選をして戻ってきたのが１１人、この１１人というのは、これは第二日野小学校の子どもさんなんですか。希望申請と指定校変更という関係性がどうなのかなということを説明を求めました。","respondent":"富田学務課長","answer":"続いて、指定校変更と希望申請の関係ですが、また小学校については一貫校以外はブロック内で希望申請できることとしております。抽選で待機になってしまったけれども、さまざま理由をいただいて申請を受けており、可能な限りそういったお子さんについても受け入れをしているです。","id":"exchange-008"},{"speaker":"西本委員","kind":"質問","question":"大体わかったんですが、待機後繰り上げという１１人、これは結局、１１人の戻りが、全員が希望どおり行きましたよという理解でよろしいんか尋ねました。","respondent":"富田学務課長","answer":"この数としては、待機後繰り上げが１１人されたということです。","id":"exchange-009"},{"speaker":"西本委員","kind":"質問・要望","question":"もうちょっと工夫していただきたいなという要望をしたいと思うんですが、あと最後に１点、これは去年かなり厳しく線引きをしているんだと思うんです。今後これがどういう動きになるのか、その考え方を、今後どういう動きになっていくのかをお聞きしたいんですけれども。","respondent":"富田学務課長","answer":"増要因も減少しておりますけれども、減要因のところでも、品川区以外に行かれる方というのもかなり減ってきているという状況もあります。今後、区域外につきましては緩和する方向というよりも、現状維持になるかなということで検討はしてまいりたいと考えております。","id":"exchange-010"},{"speaker":"山元委員","kind":"質問・要望","question":"１つだけ教えていただきたいんですが、少ないのか多いのかを教えていただきたいということと、教えてほしいと求めました。","respondent":"富田学務課長","answer":"今回、私学等の届け出をきちんとしてくださいというお知らせを直前で行いましたので、届け出の方々が増えているのではないかと思われます。その他の方々が今年度、４０人弱ぐらい減少しておりますので、相殺しますと、それほど大きな差異はないのではないかと考えております。","id":"exchange-011"},{"speaker":"川西委員","kind":"質問","question":"先ほどの続きで、最後にわからないこと、実際に抽選の対象になった人数はどこなのか、抽選後戻りの９０名で見ていいんですか、一般の方から今後質問を受けるものですから。","respondent":"富田学務課長","answer":"したがって、希望申請で増になった部分について、基本的には抽選をかけたということです。私学等への進学による辞退を受け、第三日野小学校以外については、皆さん希望の学校に入れたということです。","id":"exchange-012"},{"speaker":"川西委員","kind":"質問","question":"それからもう１つは、実際に抽選をしますよというお知らせというものは行くんですか。今回ですけれども、抽選会場へ来られた方というのは何人ぐらいいらっしゃいましたか。","respondent":"富田学務課長","answer":"１１月中旬に抽選をしていますので、１１月上旬に各抽選対象の保護者のお宅に郵送しておりまして、あまりいらっしゃらないかなということです。全員が来るというような状況ではなく、半数も来なかったように記憶しております。","id":"exchange-013"},{"speaker":"川西委員","kind":"質問","question":"９０よりは多いという、数字が。ですから、３０なのかわかりませんが、実際に自分の子どもがどこに入学できるかということで抽選会場まで足を運んだと理解しておいていいか尋ねました。","respondent":"富田学務課長","answer":"例えば城南第二小学校で言えば１５人、第三日野小学校で言えば５７人という方々を抽選したわけですけれども、かなり少ない数であったと。","id":"exchange-014"},{"speaker":"石田（秀）委員","kind":"意見","question":"人口増もあったり、そういう中学１年は特に多かったんじゃないのかなと、そこら辺はパーセントのほうがいいような気がします。それだけお願いしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"}]},{"id":"topic-02","title":"の子育て応援特別手当の進捗状況","agenda":"の子育て応援特別手当の進捗状況","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"今、冒頭の説明で少し触れられていたんですけれども、この特別手当の目的を教えていただきたいのと、説明の中で、聞き間違いだったらごめんなさい。対象年齢が３歳から６歳ぐらいと言っていたんですけれども、あと何人目の子どもなのかという対象のところを教えていただけますか。","respondent":"安井子育て支援課長","answer":"あいまいなところでお話しして申しわけありませんでした。経済情勢での、幼児教育期における子育ての支援ということを目的として、こちらを支援するという目的となっております。","id":"exchange-016"},{"speaker":"中塚委員","kind":"意見","question":"要は、第２子目の子が３歳から５歳、どこの時点だかよくわからなかったけれども、ということですよね。仮に２歳の双子、この３人のお子さんのところは対象になるのか、ご説明いただけますかとの意見を述べました。","respondent":"安井子育て支援課長","answer":"今の例のケースですけれども、対象にはなりません。","id":"exchange-017"},{"speaker":"中塚委員","kind":"質問","question":"このことを区はどんなふうに考えているのか、支給されない家庭をどうするのか、そこのお考えを伺いたい。でも、これでは形ばかりではないのかなと思うんですけれども、ご見解を伺えますか。","respondent":"古川子ども未来事業部長","answer":"基本的なことですけれども、既にこの制度についてのご認識については、私どもと各委員の方々は共通の認識に立っていらっしゃると思っています。しかも１８歳未満の中での就学前２年間、養育の負担に対する支援ですから、これはすべての方を対象にした子育て支援ではございません。","id":"exchange-018"},{"speaker":"川西委員","kind":"質問","question":"本来は２子とかの条件を別にすれば、３歳から５歳の子どもというのは、区で把握していらっしゃるのは何人ぐらいいらっしゃるんでしょうか。参考に聞いておきたいと思います。","respondent":"小林青少年育成課長","answer":"乳幼児人口ですけれども、３歳、４歳、５歳、平成２１年１月１日が直近の数字です。３歳が２,３３８人、４歳が２,４１８人、５歳は２,２９５人で登録しています。","id":"exchange-019"}]},{"id":"topic-03","title":"平成２１年４月の入園状況","agenda":"平成２１年４月の入園状況","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"教えていただきたいのは、この２園で、その理由を教えていただきたい。この２園では短時間ですけれども、どういった運営なのかよくわからないので、ご説明いただきたい。","respondent":"吉岡保育課長","answer":"短時間保育の枠につきましても、その弾力化の中で対応している部分ですので、定員の枠の中には記載してございません。それから保育料につきましては、他の私立保育園と同様に設定をしています。","id":"exchange-020"},{"speaker":"中塚委員","kind":"質問・要望","question":"教えていただければ、短時間保育の子どものためというんですか、そういうものはないということなんですか。この短時間というものが逆にどう違うのかという、そこがよくわからないので、教えていただきたいのが１つです。","respondent":"吉岡保育課長","answer":"短時間の保育を継続的に必要とするお子さんを対象に開設をしているところでございまして、その辺が通常の保育とは異なっているところです。","id":"exchange-021"},{"speaker":"中塚委員","kind":"意見","question":"私は１,５８９人の人が申し込んで、４月入園がかなわなかった人が４８８人、保育園の入園がかなわなかったわけですよね。そこをどう区は考えているのかということと、この保育園に入れないお子さんをどういうふうに解決していくのかをご説明いただけますかとの意見を述べました。","respondent":"吉岡保育課長","answer":"ご説明をさせていただきましたとおり、直ちに認可保育園を増設するというようなことで対応するというよりも、今後ともそのような方向で対応を図っていくと考えています。","id":"exchange-022"},{"speaker":"中塚委員","kind":"意見","question":"〔「何で４８８人。１２３人ならまだわかるけれども」と呼ぶ者あり〕との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-023"},{"speaker":"中塚委員","kind":"質問","question":"区の計画は区の計画であると、それと保育園入園がそれでかなうのかと、そういうふうに思っているのかどうかを伺いたい。来年に限って言えば、緊急対策でもしっかり打たなければいけないと思うんですけれども、ご説明いただけますか。","respondent":"古川子ども未来事業部長","answer":"必ずしもフルタイムで８時間就労の方だけではございませんので、さらには児童センター等でさまざまな在宅子育て支援の事業をやっております。","id":"exchange-024"},{"speaker":"中塚委員","kind":"質問","question":"それが５年も１０年もお母さん方は待てませんから、時間が限られているわけですから、そこを伺いたい。私は、最後になりますけれども、認可保育園の増設をしっかり位置づけるべきだと思っていますけれども、いかがか尋ねました。","respondent":"古川子ども未来事業部長","answer":"実際に実施した中では、１２３名の中には当然フルタイムの方もいらっしゃいますけれども、それぞれの子育てが行われていると考えています。","id":"exchange-025"},{"speaker":"中塚委員","kind":"質問","question":"これはオアシスルーム……、違うのか。その一時保育というものがどういうものかわからなかったので、何かその辺の説明がよくわからなかったので、そこだけ補足してご説明をお願いします。","respondent":"吉岡保育課長","answer":"オアシスルームは生活支援型の一時保育という位置づけでございまして、こちらは在宅で子育てをしている保護者の方が、リフレッシュですとか。","id":"exchange-026"},{"speaker":"川西委員","kind":"質問","question":"定員の弾力化のことについて１つだけ伺います。１７番の二葉、１９番八ツ山、その辺についてはどんな状況で弾力化を抱えていらっしゃるんか尋ねました。","respondent":"吉岡保育課長","answer":"八ツ山も同様です。一定、地域の特性によって応募の状況に差がありますので、地区によってはそのような状況も生じているものと理解しています。","id":"exchange-027"},{"speaker":"西本委員","kind":"質問","question":"何m2という計算があると思うんですけれども、もっとどうなのか、現状がどうなっているのかなということをお聞きしたいんですが。ある一定の枠が必要なのか、必要ないのか、そこら辺の考え方も説明を求めました。","respondent":"吉岡保育課長","answer":"知人の方ですとか、そういう対応をなさっている方もいらっしゃるでしょうし、何らかの対応をなさっていらっしゃるのであろうと考えております。それから、お子さんの障害の程度によりますけれども、必要に応じて専門に介助をする非常勤職員を配置するような形で対応しています。","id":"exchange-028"},{"speaker":"西本委員","kind":"質問","question":"年度途中だと２５％という話がありますが、現在１０６％で、まだまだ弾力化は図れますねと思ってしまっていいんでしょうか。１、２歳児のところでの定員枠というものをどう考えているのか、その考え方をお聞きします。","respondent":"吉岡保育課長","answer":"認可保育園だけではなくて、認証のご案内をしたり、もろもろの区で実施している制度の中で活用を図るようなご相談もさせていただいているところです。","id":"exchange-029"},{"speaker":"西本委員","kind":"質問・要望","question":"どういう方法があるとか、あとはどういう形をとられているのか、それを知らせるという形をぜひとっていただきたいなと思っています。多分、その１人２人もなくなってしまうということによってのほかのクラスへの影響というんですか、これは要望という形で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"そこら辺を教えていただきたいのと、１、２歳児は足りないような気がするんだよね。３、４、５歳児はまた別だから、ゼロ、１、２歳児の部分だけ説明を求めました。","respondent":"吉岡保育課長","answer":"５月入園の申し込みを受けた結果、手元に持ってございませんが、後ほど調べましてご報告させていただきたいと思います。３歳未満につきまして定数に対する要望が多いという状況は認識していますけれども、その辺の検討については今後の課題であろうかなと考えています。","id":"exchange-031"},{"speaker":"石田（秀）委員","kind":"質問","question":"２歳児の定数減は、２園しかないし、１名とか２名なので５月で埋まるだろう。１、２歳児を希望する、私の認識。","respondent":"吉岡保育課長、古川子ども未来事業部長","answer":"５月で埋まる見込みなのかどうかですけれども、４、５月の時点で完全に埋まるのは多少難しいかなと考えているところです。待機児として生じているということを考えますと… ６月、１０月、増やす考えは基本的にはございません。４月にすべてが埋まって、全体の調整を図ると、このようにご理解いただきたいと思います。","id":"exchange-032"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"４、５歳児の部分をあけていくぐらいの、これは見解は求めない。要望だけにしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"}]},{"id":"topic-04","title":"その他","agenda":"その他","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"そこを教えていただきたいのと、ぜひ原則公開でやっていただきたいと思うんですけれども、いかがか尋ねました。","respondent":"市川教育次長","answer":"設置主体につきましては、教育委員会で設置をいたしまして、教育委員会事務局と子ども未来事業部に事務局を置くと、事務局を共管するです。会議の取り扱い方については、明後日の会合の席上、決定されると思いますが、基本的に公開を原則とすると、このように考えております。","id":"exchange-034"},{"speaker":"西本委員","kind":"質問","question":"１つは、離婚調停中の家族に対してはどういう支援があるのかなと思っているんですが、それで夫にお知らせは行っちゃうわけです。そういうケースなんかはどういう処置をするのか、何か今、検討されていることがあれば説明を求めました。","respondent":"安井子育て支援課長","answer":"あくまでもこれはＤＶ被害者ということで、法律にのっとったＤＶ被害ということで対象者を考えております。各自治体でいろいろ最近、取り組みを始めるというようなところもありますので、重複支給のないような形でやっていきたいと考えております。","id":"exchange-035"},{"speaker":"西本委員","kind":"質問","question":"それは国がこういう方向で決めたということの理解ですか。そこの状況において、品川区としては何か考えていることはないのかということなんですが、いかがか尋ねました。","respondent":"安井子育て支援課長","answer":"自主的に受給ができないと考えておりますので、そういったことで……、こちらは品川区独自と考えております。","id":"exchange-036"},{"speaker":"西本委員","kind":"質問","question":"もうちょっと、今の状況として、必要な方にいかないという状況もあるわけです。ですから品川区でやっている事業であるならば、そこを考えていくということはいただけないんか尋ねました。","respondent":"古川子ども未来事業部長","answer":"ＤＶ被害者について何らかの形で、国の制度が現時点では活用できませんので、各自治体がさまざまな工夫をこらしています。それはご意見として承っておきますが、現時点では他の要件としては考えてございません。","id":"exchange-037"},{"speaker":"西本委員","kind":"質問・要望","question":"要望ということでお聞きほしいと求めましたが、住所を明かすことができないということは、もちろんＤＶの方たちは、それは必須だと思うんです。ですからなかなか難しいということで対応というのは非常にすばらしいことだと思うんですが、同じような、要望にこれはしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"中塚委員","kind":"意見","question":"１００％一般財源ということなんですが、ここでは対象約５０人とありますけれども、相手とどう連絡をとるかということもあると思うけれども……。〔「定額給付金なんだから」と呼ぶ者あり〕との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-039"},{"speaker":"中塚委員","kind":"質問・要望","question":"どんな見込みなのかを教えてほしいのと、もう少し検討の経過というか、検討の過程の議論の経過を少し教えてほしいと求めました。そこら辺がどういう形にこれでなるのか、ちょっとよくわからなかったので、そこを教えていただけますか。","respondent":"安井子育て支援課長","answer":"細かいことを検討していかなければいけないということとか、個別に子どもさんに申請書を送るというような形も考えざるを得ないのかなと考えています。５０人ということで、大体６０万円とか、そのぐらいの金額にはなるのではないかなと考えています。","id":"exchange-040"},{"speaker":"西本委員","kind":"質問","question":"今回で多分、この委員会のメンバーは終わりだと思うんですけれども、一応、継続審議になっている案件があると思うんです。どういう考え方で渡されるのかで、その進展のぐあいをお聞きしたいということもありますし、どうなっているんか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"西本委員","kind":"質問","question":"今、延ばしているという理由の中には、どういう考えで私たちは次の委員会の人たちに継続審議をしていただけるのかということだと思うんです。私たちも責任を持った形で次の委員会の方たちにお願いするということもなかなか難しいかなと思っているんですが、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"西本委員","kind":"確認","question":"今、委員長のお話で状況が大体わかりましたけれども、教育委員会としてどういう認識が、スケジュール的にどういう形をとっていこうとしているのかを確認で。","respondent":"冠木指導課長","answer":"今、３月１７日、それから４月２３日ということで２度ほど機会を持たせていただいて話し合いをさせていただいたところです。それにまた私どもも回答しながらというようなことで、継続的に５月以降も、それ以降もお話し合いを続けてまいりたいと考えております。","id":"exchange-043"},{"speaker":"西本委員","kind":"質問","question":"ということは、移設ということを前提に、これから個々の対応をしていくような話し合いに進んでいるという認識でよろしいんでしょうか。ある程度の理解をして、そういう前向きな形に今、変わってきているという理解でよろしいんか尋ねました。","respondent":"市川教育次長","answer":"私どもは計画は予定どおりに実施させていただきたい、計画の実施にあたっては、どういうことによって対応できるかを今後検討していきたい。","id":"exchange-044"},{"speaker":"西本委員","kind":"意見","question":"こういう継続の中での話し合いをしてほしいとか、各会派の方もいらっしゃると思うんですけれども、引き継ぎをよくお願いしたいなと。どういう方法をとったら一番けじめとしてはいいものなのか、そこは皆さんにお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-045"},{"speaker":"石田（秀）委員","kind":"質問","question":"議会の中で委員会がかわるわけですから、あまりこれを細かく全部やっていくと、次期の方々の考え方も拘束をするという部分にもなる。教育委員会の方々が努力をされているわけですから、また今、ご説明をいただいたようなことがあるわけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"川西委員","kind":"質問","question":"話し合いの中のメンバーですけれども、請願代表者の方も入っておられるんですか、保護者、代表者だけなのかということを１つ伺います。この新１年生の保護者に対しては、事前に計画についてお話ししてあるのかどうかを伺っておきます。","respondent":"冠木指導課長","answer":"２度目のときには、なかなか都合がつかなかったということで保護者の方との対応が基本というような形でさせていただいてあります。１年生に入られたお子様の保護者についての説明は、事前にさせていただいておるところです。","id":"exchange-047"},{"speaker":"西本委員","kind":"質問","question":"私の先ほどの質問の趣旨がずれちゃうといけないと思うので発言させてもらいますと、副委員長の判断のもとでしていただければいいと思うんです。細かいところまでのこうあるべきだとか、そういうことでは決してありません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"山元委員","kind":"質問・要望","question":"そのとらえ方を、まだ必要はないんですが、どのようにとらえたらいいのかを教えていただきたいなと思います。その辺の休校ということに関してのとらえ方をどういうふうにとらえたらいいのかなと思いまして、教えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"石田（秀）委員","kind":"意見","question":"なぜということ、なぜから入って、具体的なことを聞く。これは総務委員会で全部やるという話になっているということなら、委員長と話がそうついていますということなら、それで終わりとの意見を述べました。","respondent":"市川教育次長","answer":"今回の新型インフルエンザのこの間の取り組みの報告および説明については。本委員会で学校あるいは児童・生徒についてのご質問をいただいた場合には、必要な範囲で説明をする、このような姿勢で本日臨んです。","id":"exchange-050"},{"speaker":"石田（秀）委員","kind":"質問","question":"具体的に保育園のことでどうなっているんですかといったら、総務、厚生に人が行っていない、答弁する人が行っていないでしょう。委員長との話で決めてくれというのならそれでもいいけれども、私は本当にすいませんと、逆に皆さんには済みませんと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"},{"speaker":"山元委員","kind":"質問・要望","question":"改めて聞きたいところを質問します。その辺の、まだ出ていないのであれなんですが、なった場合のときのことを教えてほしいと求めました。","respondent":"富田学務課長","answer":"学校等々、あの行動計画等はＨ５Ｎ１ですか、ただし書きの中にあります市区町村単位での判断といったようなことも言われているところです。決定等も含め対応してまいりたいということで、今後、そういった具体的な内容につきまして検討してまいりたいと考えておるところです。","id":"exchange-052"},{"speaker":"中塚委員","kind":"質問・要望","question":"議会の対応は委員長が調整していただきたいなと思いますので、必要に迫られることもあるでしょうから、その辺の判断についてはよろしくお願いします。状況としては世界的大流行というんですか、この検討も進んでいる中ですから、考え方もあわせて教えていただけますか。","respondent":"冠木指導課長、小林青少年育成課長","answer":"学校における取り組みについてですけれども、手洗いの励行であるとか、あるいはマスクの着用等をお願いしています。それから児童・生徒につきましては、現… 保育園、幼稚園等につきましても、基本的な対応は同一です。それともう１つ、そのときにどういった内容にするかはまた別途ご相談した上で対応していくわけ… 補足になりますが、教職員、児童・生徒に、特段今のところ体調が悪いとかというような報告は受けてございません。","id":"exchange-053"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/298846?Template=document&Id=4666#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":41724,"voices":126}},{"id":"h21-20090511-5","meetingId":"h21-cm05","date":"2009年5月11日","dateIso":"2009-05-11","committee":"総務委員会","time":"午後１時０２分～午後２時０７分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を17件整理しています。","topics":[{"id":"topic-01","title":"の新型インフルエンザ対策","agenda":"の新型インフルエンザ対策","exchanges":[{"speaker":"土井委員","kind":"質問","question":"今お伺いしていくと、いわゆる相当な感染力がある新型のものというんですかね。先日から伺ってみていますと、部長に倒れられちゃったら困っちゃうので、うまいぐあいにそこを順繰りでやるように何か発想されているんか尋ねました。","respondent":"伊勢危機管理室長","answer":"案件によればやはり実務的に進めてできる場合があります。それに伴う事務の変更、拡大等がございましたら、やはり区長を本部長にする危機管理対策本部を開催して決めなければいけないと考えております。","id":"exchange-001"},{"speaker":"林委員","kind":"意見","question":"早速ＮＨＫだとか１０チャンネルが取り上げて、品川区がこういうことをやって、いち早く危機管理をやっていると。それとも例えば２３区の区長会とか、そういうところでつくっていこうよということでいったのか、その辺をまず聞かせてくださいとの意見を述べました。","respondent":"伊勢危機管理室長、中川原広報広聴課長","answer":"各発熱相談センターなどは２３区で設置されておりますので、広報で出したかどうかというのは把握しておりませんけれども、この辺の感染予防については……。 私どものほうで４月２６日に第１回の感染症対策本部の席で、区内業者にもご協力いただきまして、こういった形にするに至ったものです。なお、号外の発行については、区独自の内容であります。","id":"exchange-002"},{"speaker":"林委員","kind":"質問","question":"この病院に行かないでくださいという文節というか、これはどういう意味を持っているんですか。厚生委員会でやるのかな。","respondent":"吉田保健予防課長","answer":"そちらの病院にご案内するということで、このような説明をしています。疑いの可能性がある方、発熱相談センターにご連絡をいただいた後、我々のほうで発熱外来という専門の医療機関におつなぎするという意味です。","id":"exchange-003"},{"speaker":"林委員","kind":"意見","question":"こういうことをやるとすると、これから何かのときにいつもこれをやらなければいかんだろう。こういう場合は品川区の施設は閉鎖しますというのを、早く知らせなきゃいけないというのは、これからもこれをやれますかとの意見を述べました。","respondent":"中川原広報広聴課長","answer":"直接行かないでくださいというのが一番大事な初期の対応だということで、国も都も考えて、全国的な対応でございました。今の段階でこういうところまで区としては考えているんですよということを、行事の多い５月のこのときに、周知をさせていただいているところです。","id":"exchange-004"},{"speaker":"林委員","kind":"質問","question":"スムーズというのか、混乱なく休めるんだけれども、保育園、幼稚園というところはドタバタしちゃう。でもこれを１つの考え方とすると、先見性を持って区民の人たちに、やっていけるということと僕らはとらえていいわけか尋ねました。","respondent":"市岡総務部長","answer":"できる限りこういう迅速な対応を今後もいろいろな機会にやっていきたいと思っています。そういう意味が十分にあると思いまして、今回、広報のほうでも頑張っていただいて、こういう形で出したものです。","id":"exchange-005"},{"speaker":"林委員","kind":"質問","question":"最後にお聞きしておくんだけれども、品川区には、正直なところ、感染している人はいないんですね。だれが答えられるのかわからないけれども。","respondent":"吉田保健予防課長","answer":"現在のところそういうご相談はございません。発熱等がございまして、病院をご案内したケースもありますが、すべて陰性でございました。","id":"exchange-006"},{"speaker":"土井委員","kind":"質問","question":"地域で経過を見てもらうという対処、対応がされているのかなんですが、そういう方々はいらっしゃるんですか。先ほどいらっしゃるようにも聞こえたんだけれども。","respondent":"吉田保健予防課長","answer":"現在、検疫所のほうから約５００名超の方を追跡するようにという依頼がございまして、その方には電話連絡等で対応しております。","id":"exchange-007"},{"speaker":"南委員","kind":"質問・要望","question":"わかったんですけれども、どういう形で周知するんですかと聞いたら、ホームページだとおっしゃったんですね。ちょっと教えていただきたいというのが１つと、品川区としてそういう問い合わせをする外国からの帰国者、そこをもう１回確認しておきたいと思います。","respondent":"中川原広報広聴課長、吉田保健予防課長","answer":"先ほど、２６日に区長の指示が出まして、明けまして２７日から全庁的に５月の講座とかイベントとかすべての調査を行いました。いろいろなメディアを通じまして、あらゆる手段をとって、必要な情報の提供に努めていきたいと考えています。 検疫所からの依頼、あるいは発症者ですが、先ほどもお答えさせていただきましたように、検疫所からは現在までに約５００名超の健康調査の依頼があります。","id":"exchange-008"},{"speaker":"南委員","kind":"質問・要望","question":"電話で５月２日に問い合わせしたときには、区としてはどういうふうにその当時は考えていたのかというのを改めて確認したいと思います。それから、それぞれ設置をしているものなのかどうかをちょっと確認したいんですけれども、そのことの関係をちょっと教えていただきたいと思うんです。","respondent":"市岡総務部長","answer":"ここでは電話を１０本特設で引きまして、あるいはお問い合わせがあるだろうと思って、話中にならないような対応をとりました。私どもはコールセンターという一般的な設置の仕方をして、ホームページにも１回それを載せたんですけれども、名称を変更いたしました。","id":"exchange-009"},{"speaker":"南委員","kind":"質問","question":"それはそれとして区民は安心だと思うんですけれども、ちょっと１つだけさっき質問したつもりなんですけれども、紙ベースで早い時期に周知をする。はみ出した部分は情報が届かなかった部分はある程度あるんじゃないかと思うので、その辺の必要性はあるんじゃないかなと思うので、その辺のご答弁を。","respondent":"中川原広報広聴課長","answer":"その中でも無理を言ってあけてもらって、最短で印刷をしました。新聞折り込みも業者に、１１日号の発行とともにということで、これにつきましてはスピーディーな対応だったと区としては考えてあります。","id":"exchange-010"},{"speaker":"須貝委員","kind":"質問","question":"それが弱っている方が行くわけですから、それが相当の数、本当にその対応で私はよかったんじゃないかと考えています。そうなったら取り返しがつかないですから、そういうところの対応というんか尋ねました。","respondent":"伊勢危機管理室長、市岡総務部長","answer":"事業の継続についての啓発、イベントについてはどうするかというのを事前に啓発していくことが、区としての大事な役割になってくると思います。差し上げるということは物理的にも無理かと思いますので… １点だけ補足しますけれども、まさに強毒性の大きな伝染病の場合には、移動の制限とか交通の遮断ということを法律上できるというのがあります。今回はもちろんそういう事態ではありませんので発動することはないと思いますけれども。","id":"exchange-011"},{"speaker":"金野委員","kind":"質問","question":"最近は豚インフルエンザという表現は極力しない、言わないというのがあるんですが、これはどうなんでしょうか。配っているので、ちょっと心配になったんですけれども。","respondent":"伊勢危機管理室長","answer":"当初は豚インフルエンザと言っていたんですけれども、今は新型インフルエンザ、ＡのＨ１Ｎ１とかという表現を使っておりますので、この辺を含めて、この段階ですと豚というのはおかしいですので、訂正していきたいと考えています。","id":"exchange-012"}]},{"id":"topic-02","title":"の平成２１年７月１２日執行、東京都議会議員選挙執行要領","agenda":"の平成２１年７月１２日執行、東京都議会議員選挙執行要領","exchanges":[{"speaker":"土井委員","kind":"質問","question":"投票所で今までと変更があったところはあるんですか。あったと思うんですが、その辺を。","respondent":"早津選挙管理委員会事務局長","answer":"前回の委員会でも申しましたが、投票所一覧表中、第６投票所が都立大塚ろう学校だったものが浅間台小学校に変更です。ついでながら、記載の方法でちょっと変更したものがあります。","id":"exchange-013"},{"speaker":"須貝委員","kind":"質問","question":"仮に国内で先ほどのインフルエンザが流行した場合、その場合には日程の変更とか調整とかはあるんですか。一応それを説明を求めました。","respondent":"早津選挙管理委員会事務局長","answer":"これは実は東京都の選挙管理委員会が執行責任を持っておりまして、都選のほうでも今、検討している最中です。現在の状況ではこのまま進むものと見込んではありますが、状況によっては、変更も検討ということになります。","id":"exchange-014"},{"speaker":"須貝委員","kind":"質問","question":"変更することも、それは検討はするんだろうけれども、可能性としてはいろいろあるという認識でいいか尋ねました。","respondent":"早津選挙管理委員会事務局長","answer":"さまざまなことを考え、実際上、ある選挙が選挙日自体が変更になったということはまだございません。選挙日全体を変えるということはありませんで、検討すべきことが多々あるということで、可能性をいろいろ考えた上で対応策を検討したいと思います。","id":"exchange-015"},{"speaker":"南委員","kind":"確認","question":"ちゃんと確認しておきたいのと、この際伺っておきたいんですけれども、そういう体制が当然ありますよね。たまになんですけれども、選管の指導としては、そういう場合はどういうふうにしているのかというのを改めて伺っておきたいと思います。","respondent":"早津選挙管理委員会事務局長","answer":"それから、入院中の選挙の問題ですけれども、これは入院施設の規模によりまして、指定投票所という指定がされます。公正な選挙とかという観点から、規模があまり小さいと、スタッフ体制がそろっていないとそれは無理だということになります。","id":"exchange-016"},{"speaker":"南委員","kind":"質問","question":"その規模というのはどのくらいか知りたいのと、そういう場合は体制がとれないからというので、しようがないというふうに、しようがないという言葉あれですけれども、やむを得ないというふうに選管としては考えているんか尋ねました。","respondent":"早津選挙管理委員会事務局長","answer":"ちょっと記憶ですが、４０人か５０人以上だったと思います。これはスタッフ等の体制によってなかなかできること、できないことがありますので、その段階に現在はあるです。","id":"exchange-017"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/829737?Template=document&Id=1818#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":19855,"voices":58}},{"id":"h21-20090512-14","meetingId":"h21-cm05","date":"2009年5月12日","dateIso":"2009-05-12","committee":"行財政改革特別委員会","time":"午後１時０２分～午後２時０５分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を27件整理しています。","topics":[{"id":"topic-01","title":"公有財産の有効活用に関すること","agenda":"公有財産の有効活用に関すること","exchanges":[{"speaker":"須藤委員","kind":"質問","question":"７番目の東品川清掃作業所、中継地点としないように収集の方法も変えてきているので、行ったメンバーはみんな感じたと思うんですよね。何とかあそこの活用をしっかりできるように、今の状況をもう少し拡大して考えてもらいたいと思いますが、いかがか尋ねました。","respondent":"日下部企画部長","answer":"立地条件も非常に恵まれているところでもありますし、確かに２０年の縛りはありますが、引き続き東京都と協議をしっかりやっていく。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"資料の３番目の第一日野小学校のところなんですが、中身を紹介していただきたいのと、どうしてそうなったのかという経緯も簡単に説明していただきたい。","respondent":"久保田行財政改革担当課長","answer":"平成１７年から平成１８年にかけまして、特段の進展はないところですけれども、具体的な協議にはまだ至っていないです。そうした中で、ＴＯＣビルの建て替え計画といったものもございまして、協議の中でそうした活用もというところで協議を進めさせていただいたです。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"過去に他にあればどのようなものがあるのか教えていただきたいのと、どういう基準で決まるのかとか、そういった基準みたいなものがあるのかというのをお聞きしたいと思います。","respondent":"久保田行財政改革担当課長","answer":"貸し付けに当たっての考え方ですけれども、通常であれば普通財産という形に切りかえて民間の方に貸し付けるといったところです。それに加えまして、あとは両者での協議を行いまして貸し付け料を決めていくといったところが実態です。","id":"exchange-003"},{"speaker":"安藤委員","kind":"確認","question":"その前の説明では、ちょっとＴＯＣの建て替えに伴い貸し付けになったという経緯がよくわからなかった点があるんですが、今回、ＴＯＣの方の貸し付け料というのも、今言った説明の基本的な考えにのっとって行われるというふうに考えてよろしいのかどうかというのをちょっと確認したいんですけれども。","respondent":"久保田行財政改革担当課長","answer":"ＴＯＣへの貸し付け料の考え方ですけれども、第一日野小学校を駐車場の代替地として活用させてもらえないかという話がございました。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問","question":"貸し付けるときの区としての考え方というんですか、どういう基準でどういうふうに決めていくのかというところの区の考え、姿勢というのをお伺いしたいんですけれども。","respondent":"久保田行財政改革担当課長","answer":"それ以外にも、区民生活にとってメリットがあるのかといったところも非常に大事な観点ではないかと考えているところです。公有財産を民間の方に貸し付けるということ、いわゆる、その財産としての活用を考えているところです。","id":"exchange-005"},{"speaker":"原委員","kind":"質問","question":"３点ほどありまして、一つは単純な話で、この一覧表の７と８の間に境が入っているんですけれども、何か特別な意味があるのか、説明を求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"原委員","kind":"質問・要望","question":"３のところの第一日野小学校、ＴＯＣですか、わかっているところまで。品川区の考え方がわかれば教えていただきたいんですが。","respondent":"久保田行財政改革担当課長","answer":"私どもの方で伺っておりますのは、東京都の関係というところでは、都市計画の関係と、あとはアセスの問題。それと建築計画といったところで東京都との関係があると伺っております。","id":"exchange-007"},{"speaker":"原委員","kind":"意見","question":"これは品川区としてなんですけれども、その辺、もしお話しいただければと。まだないということであれば、その返答だけいただければとの意見を述べました。","respondent":"久保田行財政改革担当課長","answer":"今後、具体的にこの事業計画等が固まってきた段階で、事業者と区としての間の関係で協議をしながら、地元の方にもご説明ということも出てくると思いますので、そうしたところで協議をしながら詰めていくことになろうかと思います。","id":"exchange-008"},{"speaker":"原委員","kind":"質問・要望","question":"もう１点は、合法だよ」というような返事が書いてあると、この間弁護士さんが記事の中に載せられていたと思うんですね。今後において、あくまでも区の財産ですので、その辺のところのお考えをお持ちでしたらお聞かせいただきたいんですけれども。","respondent":"日下部企画部長","answer":"さっきも説明の中でちょっと触れさせていただきましたように、財政上の負担を軽減するといった点では、我々にとっても非常にメリットがあるわけです。","id":"exchange-009"},{"speaker":"原委員","kind":"質問","question":"そうしたらもう少し踏み込んで、民間ではなくて、社会福祉法人ですとか医療法人、この辺がやる場合には、それこそ最高裁判例で、要するに有償じゃなくて無償でやるよという形の展開の可能性が品川区として出てくるのかどうか、その辺を教えていただけますか。","respondent":"日下部企画部長","answer":"しかし、基本的には区の政策目的を実現するための高齢者施設の設置・運営についてということで公募をさせていただいて、それに手を挙げてきた。そういった意味では、今後ともそういうケースが出てくればそのような方法をとることもあり得るのではないかと考えております。","id":"exchange-010"},{"speaker":"原委員","kind":"質問・要望","question":"要望としまして、その都度チェック機能を生かしていただいて、我々委員の方にもその辺のところを。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"阿部委員","kind":"質問","question":"３点ほどお伺いします。先ほどの質問にありました東品川の清掃作業所、その協議なんですが、もうちょっと具体的に教えていただけないか尋ねました。","respondent":"久保田行財政改革担当課長","answer":"第一日野小学校の貸し付けのところでの考え方ですけれども、私ども、考え方としては持っているということはご説明させていただきたいと思います。ただこの場所でそういうことをやるかということではなくて、考え方としてはそういう考え方もあるという認識は持っているところです。","id":"exchange-012"},{"speaker":"阿部委員","kind":"質問・要望","question":"それとも何か思いついたら挙げましょうというレベルの話なのか、体制としてどのようにやっているか、ちょっと確認させてください。ご答弁いただけるものか尋ねました。","respondent":"久保田行財政改革担当課長","answer":"具体的に何か組織を立ち上げて検討するといったところではございませんけれども、跡地活用する場合に、そうしたものの検討が必要かと考えております。そうした条件をそろえた中で、そのほかの行政需要とか、地元の要望とかも踏まえながら活用を考えていければです。","id":"exchange-013"},{"speaker":"菊地委員","kind":"質問","question":"先ほど原委員が質問されていた部分とちょっと共通してしまうのかなと思うんですが、貸し付けをする際に、そこも判断をされるわけですよね。先ほど部長がおっしゃっていた、一民間企業なのかどうかということも一つの線引きなのかもしれないですけれども、その辺を教えていただけますか。","respondent":"久保田行財政改革担当課長","answer":"基本的な考え方ですけれども、原則としては、貸し付けに当たりましては有償で貸し付けるです。貸し付けに当たりまして、区としての政策的な判断等があれば、無償としても貸し付ける場合があるといったご説明をさせていただいたところです。","id":"exchange-014"},{"speaker":"菊地委員","kind":"質問","question":"一体だれがどうやって、どういう形でその確定をしていくのかというのが、今のお話だとよく見えてこないんですよね。その辺をもう少し具体的に教えていただけますか。","respondent":"阿部経理課長","answer":"前後のほか特に必要があるということもありますけれども、原則的には今申し上げたような場合、公共用に使う場合ということになっています。","id":"exchange-015"},{"speaker":"菊地委員","kind":"質問","question":"その公益性を判断するというのも、今、課長がおっしゃっていた委員会での判断ということになるんか尋ねました。","respondent":"阿部経理課長","answer":"貸し付ける場合には、また別に使用料の条例があります。行政財産の貸し付けの使用料の条例がありますので、それにのっとって、行政財産の場合には貸し付け金額を決めて、貸し付けるです。","id":"exchange-016"},{"speaker":"菊地委員","kind":"質問","question":"最後に、今の委員会、担当される方は部長さんたちなのかなと思いますけれども、それは全庁縦断的につくられる委員会という意味合いでしょうか。それとも、例えばまちづくり事業部だったたらまちづくり事業部というような、その事業部での委員会ということなのか、そこだけ最後に説明を求めました。","respondent":"阿部経理課長","answer":"財産を所管するのは総務部ですので、総務部を中心に企画部、あるいは教育部門であれば教育委員会とか、そういう部を中心にした委員会で定めています。","id":"exchange-017"},{"speaker":"石田委員","kind":"質問","question":"１点だけ質問したいんですが、また今後近々に取得の考えがあるのかというのを、わかっている範囲でよろしいのでお願いします。","respondent":"阿部経理課長","answer":"うろ覚えで申しわけないんですけれども、たしか第二延山小学校のところの建て替えに伴いまして、そこを取得していると思います。近々で国有地の取得の予定があるのかということですけれども、現在のところ、具体的にいつどこを取得するかという予定はございません。","id":"exchange-018"},{"speaker":"石田委員","kind":"質問・要望","question":"積極的に検討していただいて、区として何かできることがあれば、積極的な行動を起こしていただければと。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"井上委員","kind":"確認","question":"先ほどの議論の中で２点確認をしたいんですけれども、それからもう２年たっていて、そういうところでいつごろのことなのかと。計画がちょっと長いものでわからないので、その辺の状況を説明を求めました。","respondent":"久保田行財政改革担当課長","answer":"この第一日野小学校が移転しますのが平成２２年４月という予定になってありますので、それ以降という形になると思います。１０年間の暫定的な活用をさせてもらいたいですので、予定としましては平成２２年度から、早ければそういう形があるのかなとは考えているところです。","id":"exchange-020"},{"speaker":"井上委員","kind":"質問","question":"そうすると、建て替えの１０年間の賃貸のところで、あとはそれをどういう形で金額とかいろいろと詰めたものを行政として区民に対する説明を、どういう場を使って公表していこうとされているのか、説明を求めました。","respondent":"久保田行財政改革担当課長","answer":"具体的な協議に入っていくのではないかと考えているところですが、まずは、ＴＯＣ側の開発計画が明らかになった時点からというふうに考えております。","id":"exchange-021"},{"speaker":"井上委員","kind":"質問・要望","question":"質問がちょっと届いていないかなと思うんですけど、１年先の決算特別委員会とか、そういう決算の場で公表していくのか。どういう場で区民が知り得るのかということをお聞きしたので、その辺をお答えほしいと求めました。","respondent":"久保田行財政改革担当課長","answer":"地域の方につきましては、ＴＯＣ側から開発計画の説明がまずはあると思いますので、そうした中でのご説明というところは地域の方にあると思います。","id":"exchange-022"},{"speaker":"安藤委員","kind":"質問・要望","question":"単純にわからなかったので教えていただきたいんですが、来年４月から１０年間貸し付けるというのは、これはもう話が決まってしまっていることなのか。そこら辺で、なぜ１０年間なのかというのがわからなかったので、教えてほしいと求めました。","respondent":"久保田行財政改革担当課長","answer":"４月から１０年間ですけれども、まず、早ければ平成２２年の４月以降ということで１０年間というご説明を先ほどさせていただいたところです。","id":"exchange-023"},{"speaker":"安藤委員","kind":"質問","question":"１０年間かけてやるということですか。近隣の方からもどうしてそうなったのかという質問などもたまに受けることがあるんですが、今、ご説明をお願いしたいと思います。","respondent":"日下部企画部長、阿部経理課長","answer":"賃貸の期限の問題でそこで利用を継続することができなくなったというような経過がありまして、あいているのであればそこをどうしても貸してほしいと。賃料等について、今、手持ちであるかどうか確認をしていますが… 今、企画部長の答弁にもありましたけれども、あそこの施設の維持も含めて貸しているという状態です。もう１点は、十分な対応をしていただいておりますので、その辺については地域の方もご理解いただいていると考えています。","id":"exchange-024"},{"speaker":"安藤委員","kind":"質問","question":"というか、どういう経緯で貸したのかという、その透明性がすごく大事なんじゃないかなということで聞いたんです。今回の総合体育館の場合は、ちょっと例外的なものなのか、それとも基本的な考えにのっとって進んだものなのかということをお伺いします。","respondent":"日下部企画部長","answer":"冒頭の全体説明もさせていただきましたけれども、議会の意見、区民の意見を聞いた上で基本的な方向性を整理していくというのが基本です。そういう意味では非常に例外的なケースと言えるのかなと考えております。","id":"exchange-025"}]},{"id":"topic-02","title":"の特定事件調査のまとめ","agenda":"の特定事件調査のまとめ","exchanges":[{"speaker":"須藤委員","kind":"提案","question":"３番目にまた「経緯等を踏まえ」と、３番目を「学校避難所であったことに鑑み」とかという表現にすると、違った言葉だと思うのでいいかなと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-026"},{"speaker":"井上委員","kind":"質問・要望","question":"区民はそのときに必要なもの、地域の身近なところにそういうところがあれば意見を出したい、こうしてほしいというのは当然な意思表示だと思います。そこのところで暫定活用、改築とか解体とか、ぜひこの委員会での議論も踏まえて考えていただきたいというのを一言伝えたいなと思いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/592995?Template=document&Id=5860#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":18531,"voices":67}},{"id":"h21-20090514-16","meetingId":"h21-cm05","date":"2009年5月14日","dateIso":"2009-05-14","committee":"街づくり特別委員会","time":"午後１時０３分～午後４時０５分","status":"正式会議録","sourceType":"formal","overview":"街づくり特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/504318?Template=document&Id=6386#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=16&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":2261,"voices":10}},{"id":"h21-20090522-8","meetingId":"h21-cm05","date":"2009年5月22日","dateIso":"2009-05-22","committee":"建設委員会","time":"午前１０時０２分～午後４時２１分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/814084?Template=document&Id=3944#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":1882,"voices":10}},{"id":"h21-20090528-9","meetingId":"h21-cm05","date":"2009年5月28日","dateIso":"2009-05-28","committee":"文教委員会","time":"午後１時１２分～午後１時４８分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を12件整理しています。","topics":[{"id":"topic-01","title":"議案審査","agenda":"議案審査","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"その人事院勧告について、教育委員会がどう考えているのか、伺いたいと思っています。伺いたいのは、８月ぐらいですか、これをちょっとご説明ほしいと求めました。","respondent":"田村庶務課長、冠木指導課長","answer":"１３.２％のマイナスということを踏まえて、そういう形で、それに沿ったという話がありました。それを踏まえて、その勧告に沿った対応が区としても必要だという判断から、今回の条例をご提案させてもらったです。 第５５号議案によって影響を受ける教員の数ですが、副園長１０名、教諭２４名の３４名です。それから、学校教育職員、いわゆる区独自採用の教員等ということになりますが、８名です。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"平成２１年度の勧告を行うまでは暫定的なものというご説明がありましたけれども、これはどういう意味なのか、その中身をもう少し教えてください。先ほどちょっと伺ったんですけれども、地域経済への影響をどんなふうに考えているのか、ご説明いただけますか。","respondent":"市川教育次長","answer":"したがって、この秋に予定される本勧告の内容も、かなり厳しいものになるということが見込まれてあります。あらかじめマイナスが見込まれているとすれば、この６月の時期の支給月数を減らすのは、情勢適用の原則にかなった措置だと受け取ってあります。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問","question":"ここをどうお考えなのか伺いたい。私は、この負の連鎖は断ち切らなきゃいけないと思うんですけれども、どんなふうにお考えか尋ねました。","respondent":"市川教育次長","answer":"２点目の負の連鎖が心配されるということですけれども、これは、私は断言いたします。負の連鎖を断ち切るのは、他の政策的な措置で考えるべきだと、このように受けとめてあります。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問","question":"これは委託料にも反映するんでしょうか、そういった影響もどう考えているのかお伺いしたいですけれども、私は。先ほどの区の非常勤と委託先、委託料についてだけ、説明を求めました。","respondent":"市川教育次長","answer":"その一つには公務員給料、あるいは民間企業における給料の水準というものもあるでしょうけれども、ただそれだけで決められるものではございません。これまでもしてきておりませんし、今回も、特にそういう話は聞いてございません。","id":"exchange-004"},{"speaker":"西本委員","kind":"質問・要望","question":"下げるしかないという考え方なのか、その辺がどういう考え方なのかと、ちょっと不思議に思っているので教えていただきたい。やっぱり、当面はこの形でやらざるを得ないというふうに考えているのか、そのお考えをお聞きしたいと思います。","respondent":"田村庶務課長、冠木指導課長","answer":"先ほど教育次長のほうからも説明がありましたが、地方公務員法第１４条によって、情勢適用の原則というのが適用されます。民間の通常の形と、制度的には違うということです。勤勉手当につきましては、区の職員に準じて定めてありますので、今回の２３区の特別区人事委員会勧告に従っての提案です。","id":"exchange-005"},{"speaker":"西本委員","kind":"質問・要望","question":"最後のほうですが、現状はわかります。しかし、そういう仕方をすることも一つあってもいいのではないかなという形で、今後の検討課題ということで検討してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"川西委員","kind":"意見","question":"ちょっと基礎的なことを、この際に聞いておきたいんですが、世間一般的な夏のボーナスのところで、期末手当と勤勉手当となぜ分かれているのか。そういうところのことを、ちょっと承知しておきたいんですとの意見を述べました。","respondent":"冠木指導課長","answer":"期末手当につきましては、基本的に、在職期間、このぐらいを勤めたということからの算出でございまして、勤勉手当のほうは、人事考課等々を反映した形でのものというふうにご理解いただければと思います。","id":"exchange-007"},{"speaker":"川西委員","kind":"質問・要望","question":"勤勉手続それぞれ規則のようなものが定められていて、在職期間とか、人事考課とかいう判定基準というのが別にあるわけですね。それはまた別の機会に教えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"ところが人事委員会で０.３月とか、０.４月と出たら、ちょっと再度確認をしたいと思っているんです。だから、あえて凍結という言葉をつかっているのかということを、再度、確認をしておきたいと思います。","respondent":"田村庶務課長","answer":"今回は０.２月ですが、それで足りないということも出てくる可能性もあるし、景気の情勢と調査の結果次第ということになります。その意味から、凍結という言い方で、暫定的な措置で、今回、そういう措置をとるという解釈です。","id":"exchange-009"},{"speaker":"石田（秀）委員","kind":"質問","question":"０.２月とか０.１５月なんですけれども、それが０.４月と出てきたら、今度まだ議案で精算行為が出てくるわけですか。相差が０.３月とか０.４月とかいうのが後で出てきたら、精算行為というのは自動的に、例えば冬の賞与とかでもっと引かれちゃうわけではないか尋ねました。","respondent":"市川教育次長","answer":"プラスになることはまずないと思いますけれども、見込みで申し上げますと、今回は、一応０.２月と。月数を変更すれば、条例改正の審議を、それぞれの所管委員会でお願いをするという運びになろうかと思います。","id":"exchange-010"},{"speaker":"石田（秀）委員","kind":"意見","question":"最初から０.５月でいこうとかやれば、そういうもとの部分を直すという考え方もあっていいんじゃないのかなと思うけれども、それはどうなのか。こんなことで聞いていいのかとの意見を述べました。","respondent":"市川教育次長","answer":"今年の１２月と来年の３月の支給分から精算することになると、妥当な措置だろうということが、一つ言えるかと思います。後段のご質問については、ご意見として承っておきます。","id":"exchange-011"},{"speaker":"中塚委員","kind":"質問・要望","question":"当事者間の合意を尊重する立場で、あえて反対はしませんけれども、しっかり地域経済を自治体が支えていってほしいと求めました。賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/298846?Template=document&Id=4668#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":10253,"voices":39}},{"id":"h21-20090528-5","meetingId":"h21-cm05","date":"2009年5月28日","dateIso":"2009-05-28","committee":"総務委員会","time":"午後１時０８分～午後１時４１分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を10件整理しています。","topics":[{"id":"topic-01","title":"する条例、(2) 第５２号議案、品川区教育委員会教育長の給与および旅費ならびに勤務時間その他の勤務条件に関する条例の一部を改正する条例、(3) 第５３号議案…","agenda":"する条例、(2) 第５２号議案、品川区教育委員会教育長の給与および旅費ならびに勤務時間その他の勤務条件に関する条例の一部を改正する条例、(3) 第５３号議案…","exchanges":[{"speaker":"林委員","kind":"質問","question":"それから、人事委員会の意見聴取についてというのを添付していただいているんですけれども、再任用については、ここには入らなくていいんですか。その二つを説明を求めました。","respondent":"伊勢総務課長、榎本人事課長","answer":"議案につきましては、基本的には組織順ということで、特別職のほうから第５１号議案という形になっています。副区長が説明しました第５１号議案から第５５号議案ですが、説明とましては、こういう説明になっております。 意見聴取の部分につきましては、再任用職員分は、普通の職員のところで含んでおりますので、条例としては、職員の給与条例の中に再任用部分も含んで、給料表もすべて入っておりますので、職員と一緒というものです。","id":"exchange-001"},{"speaker":"林委員","kind":"質問","question":"ここの２行目に、「平成２１年６月の区長、間に区議会議員がきている。区長、副区長、教育長ときて、区議会議員だと思うんですけれども、これも何か決まりがあって、こういうふうに並べてあるんか尋ねました。","respondent":"伊勢総務課長、市岡総務部長","answer":"区議会議員の報酬を規定しているということで、その後に区議会議員を持ってきまして、そして教育長の改正。それから、常勤監査委員も区長の条例がかかっておりまして、それで変わるということで… 今回、監査委員に関しては、条例改正が議案としては必要ないんです。したがって、言ってみれば、議案ではないけれども、連動して同じように凍結するという意味で一番最後につけたです。","id":"exchange-002"},{"speaker":"林委員","kind":"質問","question":"最後にします。副区長とくるのが、議員の言い方に直すと、そういう並びにならないんか尋ねました。","respondent":"伊勢総務課長","answer":"第５１号議案を見ていただくとわかるように、これはあくまでも、区長と副区長の給与等の関係の条例ということで、一つのまとまりということでご理解いただければと思います。","id":"exchange-003"},{"speaker":"須貝委員","kind":"質問","question":"今回、このように臨時の特例措置ということで出たんですが、こういうことは今までもあったのでしょうか。ちょっとその辺を説明を求めました。","respondent":"榎本人事課長","answer":"特別区人事委員会は昭和５３年にできまして、それ以来初めてのものです。背景としましては、民間企業の動向を踏まえると、やはりそれぞれの立場からの臨時勧告が必要だろうということで勧告がなされたということです。","id":"exchange-004"},{"speaker":"須貝委員","kind":"質問","question":"もう１点。これは結局、臨時ですから、別に時期はこだわらずにいつでも、特別区人事委員会からの臨時勧告が出せるのかどうか、その辺を説明を求めました。","respondent":"榎本人事課長","answer":"権限的には、いつでも出せるという形になります。今回、この５月の時期に出したのは、手続的に間に合わないという意味でのぎりぎりの時期での臨時的な勧告と理解しております。","id":"exchange-005"},{"speaker":"土井委員","kind":"意見","question":"今、その話が出たので、人事院で勧告をする場合、民間給料等を一定の数調査をして、それに基づいて出てくるという形になるんですね。今回のものは、同じように調査をされたのかどうかということだけ聞かせてくださいとの意見を述べました。","respondent":"榎本人事課長","answer":"今回は、人事院は緊急調査をしましたけれども、特別区人事委員会については独自の調査はしておりません。実際には、情勢適用と、国の人事院勧告と、他団体との均衡というものを考えまして、臨時的な勧告をしたものです。","id":"exchange-006"},{"speaker":"土井委員","kind":"質問","question":"いずれにしても、それを、労働組合も含めて納得をしたというか、合意をしたということですから、よろしいのではないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"南委員","kind":"質問・要望","question":"そういうものも実地調査というんですか、そして今回はどうなのかということを、ちょっと改めて教えてほしいと求めました。","respondent":"榎本人事課長","answer":"平成２１年度の勧告分につきましては、今、調査に入っているところです。今回につきましては調査を実施しない形で、平成２１年度の本調査を待って、今回の部分が出ているというものです。","id":"exchange-008"},{"speaker":"南委員","kind":"質問・要望","question":"これで果たしていくのかどうか、今求められていると、私は思っているんです。そういう論調の新聞報道も結構あると思うんですけれども、その辺についての認識は、区はどういうふうにとらえているんか尋ねました。","respondent":"榎本人事課長","answer":"１００人未満の企業については、回答した企業ですけれども、マイナス２８.３％という数が出ています。１、２、一時的でも凍結をして調整を図っておいたほうがいいのではないかという認識を持っています。","id":"exchange-009"},{"speaker":"南委員","kind":"質問・要望","question":"私どもの議員が人事院総裁に質問したときに、改めてやっぱり、マイナス効果のほうが大きいと言わなくてはいけないのではないかと思います。当該のところが妥結しているわけですから、しかし、そういう考え方もしっかり受けとめておいていただきたいということを言っておきたいと思います。","respondent":"須藤委員長","answer":"今の態度表明的なものも少し含んでいるので、委員長としては、その辺を判断しなくてはいけないんですが、反対はしませんという考えでの態度表明ですね。","id":"exchange-010"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/829737?Template=document&Id=1820#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":8914,"voices":37}},{"id":"h21-20090601-6","meetingId":"h21-cm06","date":"2009年6月1日","dateIso":"2009-06-01","committee":"区民委員会","time":"午後１時０２分～午後２時５５分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を8件整理しています。","topics":[{"id":"topic-01","title":"の２番目、事務事業概要","agenda":"の２番目、事務事業概要","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１つは、この地域センターの耐震診断というのはどういう計画でどこまで進んでいるのかということを教えてほしいと求めました。希望する人がもっと受けられるような体制ができないのかなと思うんですけれど、そこのところをまず教えてほしいと求めました。","respondent":"中山地域活動課長、秋山協働・国際担当課長","answer":"ここは民間住宅との協議を行って、それから実施していくという形になっておりますので、２１年度中には何らかの形で耐震診断を。そういう形での対応になっておりますので、基本的にはきちんと耐震診断をやっていき… いろいろ食事サービス等もありますので、その中でこういう数字が変化しているという形で考えているところです。","id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私はちょっと介護の関係の方からこういうお話を伺ったので、担当課としては、希望すれば受けられるということでいいんですね。それから、この不況下の品川区の中小企業の実態は、されているのであればその実態も教えてほしいと求めました。","respondent":"中山地域活動課長、福島ものづくり・経営支援課長","answer":"先ほどちょっと説明が漏れましたけれども、すべての地域センターをやるのかというと、たしか昭和５７年度以降だと思います。そういうことですので、整備はきちんと優先して進めていくという区の方針です。 東京商工リサーチのほうで調べておりまして、負債額１,０００万円以上のところですが、平成２０年では８２件の倒産が品川区内でございました。今年になってからは１月が４件、２月が１１件と、ここまでの報告は来ております。","id":"exchange-002"},{"speaker":"南副委員長","kind":"質問・要望","question":"基本的な考え方として、そこがどの程度避難場所というものを確保していくか基本的な考え方を伺いたいのと、その辺を教えていただきたいのが１つです。それに関連して、大きいところと小さいところの協力関係という点ではあっていいのかなと思って伺っていたんですが、年間予算２００万円なんですよね。","respondent":"堀越文化スポーツ振興課長、諸岡商業・観光課長","answer":"ただ防災の計画上、避難人口等のいろいろな推移を見まして、より具体的な対応については考えていくと。防災課、区全体でいろいろ課題について検討を始めていると聞いておりますので… これを年４回ほど予定しておりまして、それに参加する店を商店街連合会のほうで募集しますので、そのためのチラシの作成ですとか管理運営等です。","id":"exchange-003"},{"speaker":"南副委員長","kind":"質問・要望","question":"そのことを申し上げておきたいと思うし、その辺の考え方として、行政としてどういうふうに思っておられるのか伺いたいと思います。それは当然そういう方向でお願いしたいと思うんですが、その辺がさっきは見えなかったので、改めて伺いたいと思います。","respondent":"諸岡商業・観光課長","answer":"大型店との連携等ですけれども、こういった中で大型店との連携を新たに考えて、検討協議していけばいいなと考えています。商店街につきましてもこういった支援を活用していただいて、そういった意味で引き続きこういった支援を活用していただくように。","id":"exchange-004"},{"speaker":"三上委員","kind":"確認","question":"１つ確認させてもらいたいんですが、臨海斎場の件で、今申込みをして何日ぐらい待つような状況にあるんでしょうか。あそこは炉を設置できる場所はまだあるはずだけれども、そのあたりの活用について検討しているのかどうか、あわせてお伺いしたいんですが。","respondent":"梶戸籍住民課長","answer":"はっきり何年度とはまだ言えない状態ですけれども、現在の火葬炉が混み合っているという状況では、早晩入れていくべきだろうとは考えてあります。そちらのほうが決まりましたら、ご報告申し上げていきたいと思います。","id":"exchange-005"},{"speaker":"三上委員","kind":"質問・要望","question":"今こういう状況にあるということですから、当然それを想定してスペースをつくってきているだけに、やはり早急に検討すべきだと私は思います。品川区から積極的に働きかけていって、この問題についても具体的な計画になるように進めていただきたいということをお願いしたいと思います。","respondent":"梶戸籍住民課長","answer":"今、三上委員からご指摘がございました。一部事務組合の５区の中の１つの区ではありますけれども、そういった形できちっとした意見を申し上げていきたいと考えております。","id":"exchange-006"},{"speaker":"川西委員長","kind":"提案","question":"先ほど配食サービスで、８月は商店街から提供という新提案を私は初めて聞きまして、大変結構なお話だと思います。それからもう１つですけれど、１年も忘れていまして今思い出したんですけれども、そういうことはできるのかどうか伺いたいと思いますとの意見を述べました。","respondent":"中山地域活動課長、秋山協働・国際担当課長、矢部生活安全担当課長","answer":"例年比較の中で挙げられているのと、実行委員会形式ですので、そこの報告にゆだねているということがあります。イベントをやったときの参加資料とかを含め… 夏休みの件に関しましては区民委員会で３月にご報告させていただいているところですけれども、商店街連合会を通じてお願いをする形をとる予定です。現在も禁止地域以外の場所につきましても、「歩きたばこ禁止」という横断幕は張らせていただいています。","id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"今日、こういうことについて調査をしていきたいということで決めるということでしょうか。今日、事務事業概要を伺ったところですので、これを受けてちょっと検討して、次回に意見を出させていただけたらいいなと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/911630?Template=document&Id=2550#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":35219,"voices":69}},{"id":"h21-20090601-7","meetingId":"h21-cm06","date":"2009年6月1日","dateIso":"2009-06-01","committee":"厚生委員会","time":"午後１時０２分～午後３時３９分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を12件整理しています。","topics":[{"id":"topic-01","title":"事務事業概要を行います。 この事務事業概要につきましては、改選後の初めての委員会で、各所管の事業概要","agenda":"事務事業概要を行います。 この事務事業概要につきましては、改選後の初めての委員会で、各所管の事業概要","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"７ページですか、これは認定を受けた方のうち１.４％だけが非該当というのは、こういうものなんでしょうか。現在既に影響が出ているところをつかんでいれば教えていただきたいのと、今後どうなっていくかという見通しなどがあればお伺いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"もちろん質問の仕方などは資料の概要にかかわるということは意識してやりますけれども、この１冊について質疑を受け付けてというような形でやっていただけると、ぜひ次回からそのように工夫していただけるとありがたいということをまず委員長に要望したいんですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"２１万人でしたか、こちらで言うところの１ページですか、これはどういうふうに考えたらいいのかということをお伺いしたいと思います。その捕捉率の現状をどう考えるかというところと、生活保護の制度そのものがどういう制度なのかということを、いかがか尋ねました。","respondent":"平澤生活福祉課長","answer":"まず初めに保護の実施状況なんですが、先ほどの事務事業概要の５ページのところでご説明させていただきましたのは。生活保護の考え方自体が大変違うというふうに聞いているところですけれども、日本の場合には、なかなか難しいのかなと思っているところです。","id":"exchange-003"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"５７ページの養護老人ホーム、所得の低い人でも入れるというあたりが、どう把握をされているのかなというのをちょっとお伺いしたいのが１点。無届けの老人ホームが４４６カ所あって、届出がされていない場合どういうふうに変わっていくのかというのをちょっと教えてほしい。","respondent":"平澤生活福祉課長、冨岡高齢者福祉課長、本城国保医療年金課長","answer":"今年の４月１４日、それぞれ１０カ所、１３名ということでお答えさせていただきました。なお、こういった施設の中で、危険とか… このまとめ方につきましては、ご指摘の、民間が設置したのかどうかというのがわかりやすいということを踏まえまして検討させていただきたいと考えています。 制度のアウトラインをご説明するような形になっておりますが、運用も含めて、今後引き続き検討していきたいと考えています。","id":"exchange-004"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"高齢者福祉課長に伺ったらいいんでしょうか。ただ区の施設だけで受けとめるだけじゃなくて、２回になってしまったんですが、お答えいただけたらと思います。","respondent":"木下健康福祉事業部長","answer":"このようなことも踏まえながら、これはまさに国、都道府県段階で十分検討していただきたいと私どもの方も思っているところです。なお、もう少し支援を厚くしてほしいというようなことを上げておりまして、土地代も含めてとかというようなこともあったかと思いますけれども。","id":"exchange-005"},{"speaker":"飯沼副委員長","kind":"質問","question":"５７ページの養護老人ホームというのは、これはもうつくらないということですか。これはどこに該当するものか尋ねました。","respondent":"冨岡高齢者福祉課長","answer":"これは都の方でつくっているところでございまして、福祉法人ですね。申請された方は、区として措置をするという流れになっておりまして、傾向としては減っている状況です。","id":"exchange-006"},{"speaker":"安藤委員","kind":"質問・要望","question":"品川区がなぜ捕捉率が低いのでしょうかということの中で、理由というか、それはどういうふうに考えればいいのかというのをお伺いしたいと思います。事務事業概要ですから、それで命を落としている人も全国にいるわけですから、ぜひ改善して載せてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"金野委員","kind":"確認","question":"１点、医療機関ではなかなか検査を拒まれるところがある、その点はどのぐらい協力をしてくれるような形まで進んでいるのでしょうか。今後の対策としてどこまでするよう、その働きかけの仕方というのでしょうか、そこの確認をさせてください。","respondent":"吉田品川区保健所保健予防課長","answer":"現在、検査につきましては、流行地からお戻りになって症状のある方に進めているといったことです。発熱外来を開設している医療機関では実施ができるわけですが、一応お願いはしていますけれども、できないことも場合によってはあるということです。","id":"exchange-008"},{"speaker":"金野委員","kind":"質問","question":"妊婦さん、それから特別な内臓疾患のある方がこれにかかると非常に重症になるということですが、その方々に対してはどのような。その方の近くに高熱を出されている方がいて、心配だ、熱が上がってきそうだというようなところでの事前の対応というのはどうなんか尋ねました。","respondent":"吉田品川区保健所保健予防課長","answer":"現在、まだ地域では流行がございませんので、一応重くなりやすいということでの啓発は既にホームページ等でさせていただいているところです。地域の医療機関と検討を進めて、妊婦の方、比較的早期に投薬していただくといったことも含めて相談を進めてまいりたいと考えています。","id":"exchange-009"},{"speaker":"安藤委員","kind":"質問","question":"数の面で足りているのかということをお伺いしたいのと、ポートランドの方が中止になるという話もるる伺っているんですけれども、そういった基準というものはあるんか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"安藤委員","kind":"確認","question":"ではちょっと確認なんですが、中止しないかという判断は、保健センターで出すわけじゃないということなんですか。それに関しては保健センター、保健所の管轄外ということなんか尋ねました。","respondent":"吉田品川区保健所保健予防課長","answer":"ご指摘の内容につきましては、すべて、新型インフルエンザ対策危機管理対策本部の会議で、区長以下ですべて検討して決定しているとこです。全庁的に対応していることです。","id":"exchange-011"},{"speaker":"飯沼副委員長","kind":"質問","question":"発熱センターは庁内に１か所設置をされているわけなんですけれども、入院設備が何床ぐらいあるのか。早く終息してほしいなと願っていますが、区独自の体制がとれるのか、その辺もちょっと説明を求めました。","respondent":"吉田品川区保健所保健予防課長","answer":"ただ、現状では十分そこで対応できるという形になっています。何カ所かも非公開になっております。","id":"exchange-012"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/854582?Template=document&Id=3236#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":46167,"voices":80}},{"id":"h21-20090601-8","meetingId":"h21-cm06","date":"2009年6月1日","dateIso":"2009-06-01","committee":"建設委員会","time":"午後１時０２分～午後２時４０分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を7件整理しています。","topics":[{"id":"topic-01","title":"の１番目、幹部職員紹介","agenda":"の１番目、幹部職員紹介","exchanges":[{"speaker":"菊地委員","kind":"質問・要望","question":"随分以前にお聞きしたんですけれども、平成２１年度以降に、これからという問題になっているんですか。ちょっとそこだけ教えていただきたいんです。","respondent":"藤田水とみどりの課長","answer":"スケジュール的には、今のところ、従来から変更になっているものではございません。平成２１年度、今、進めているところです。","id":"exchange-001"},{"speaker":"藤原委員","kind":"質問","question":"簡単にお伺いしますが、せっかく組織改正したのに、と思うことがあるんですけれども、公園に関してお伺いしたいんです。何課が公園の何をするとか、まず、教えてくれますか。","respondent":"松代都市計画課長","answer":"防災まちづくり事業部のほうで担うのは、主に公園を計画し、つくるほうのハードの部分。都市環境事業部のほうでは、その財産を管理し、日常の維持管理をする、そういう大きな分けを、今回、しております。","id":"exchange-002"},{"speaker":"藤原委員","kind":"質問","question":"わざわざ部を越えて変える必要が何であるんですか。せっかく道路公園課というのがあって一本にしていたのに、分ける必要って全くないと思うんですけれども。","respondent":"岩田防災まちづくり事業部長","answer":"物事を考えるときに、必ずぶつかるんです。つくるほうと、維持管理するほうは、基本的には分けるという考え方で組織を維持しております。","id":"exchange-003"},{"speaker":"武内委員","kind":"提案","question":"我々も、正直言って、今まで何かを提案するときにも、実際に戸惑っているんですね。そうは言っても２カ月経っていますので、まだ２カ月なのであれなんですけれども、ちょっとご紹介いただければうれしいかなと思っていますとの意見を述べました。","respondent":"家壽田都市整備下水道課長、岩田防災まちづくり事業部長","answer":"どんな補助があり、どんな技術があるかということが、一つ建設の部隊で集約されました。これはすべて大きなメリットと考えておりまして、２カ月でありますが、感じております。 気がつかない部分をいろいろご提案をいただくのは、私どもとしては、ほんとうに助かっておるんです。きちっとお答えをするような形にしたほうが、一つ言ったことが、そういうふうに協力をさせていただきたいと思います。","id":"exchange-004"},{"speaker":"武内委員","kind":"質問・要望","question":"私も、たまたま外に出ていたので、３０分ぐらいの間にびしょびしょになってしまったんです。その辺のことが、もし何か被害が出ているとかあれば、教えていただきたいんですが。","respondent":"中山防災課長","answer":"特に被害は出ておりません。","id":"exchange-005"},{"speaker":"菊地委員","kind":"提案","question":"ということがあって、今の委員長の提案は、そのことと密接に関連をしているのかなと思うんですけれども。今の委員長の提案は、例えば、次回の委員会で、そういう話をしますということなのか、それとも、文章でということなのか、ちょっとその辺をとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"},{"speaker":"伊藤委員長","kind":"提案","question":"委員と理事者の関係の中で、まずは材料となるものを、皆様からご提案していただきたいと思っています。ですから、まとめますと、６月１２日までに出していただくのが、調査事項、所管事務調査でありますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/814084?Template=document&Id=3946#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":33086,"voices":64}},{"id":"h21-20090601-9","meetingId":"h21-cm06","date":"2009年6月1日","dateIso":"2009-06-01","committee":"文教委員会","time":"午後１時０４分～午後３時５０分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を31件整理しています。","topics":[{"id":"topic-01","title":"幹部職員紹介","agenda":"幹部職員紹介","exchanges":[{"speaker":"本間委員","kind":"意見","question":"民主品川の本間隆です。どうぞとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"},{"speaker":"中塚委員","kind":"意見","question":"共産党の中塚亮です。どうぞとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-002"}]},{"id":"topic-02","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"井上委員","kind":"提案","question":"今年度、放課後の障害児の方々の提案をされたと思うんですけれども、その辺の実情がわかるところがあれば教えてほしいと求めました。４４ページの教育センターの３,７００万円余の予算なんですが、確認なんですが、説明を求めました。","respondent":"和氣小中一貫教育担当課長、田村庶務課長、冠木指導課長","answer":"連携グループの中で、連携グループ独自で問題をつくって、そこで学力調査をやろうというものです。学校予算内でつくっているです。 それで、今回切れるところを実績も踏まえて１校そちらのほうに委託という形の動きです。それ以外については総合評価制度によって実績のある会社に委託して… その金額につきましては、この３億３,０７２万５,０００円というのが教育センターの建築の部分の金額ですので、よろしくお願いいたします。","id":"exchange-003"},{"speaker":"井上委員","kind":"意見","question":"すまいるスクールのところで、３８校のところで、ぴゅあ・さぽーとが１校受け持つということは、ほかの委託と同じ形でぴゅあ・さぽーとが委託事業者として契約がされたという意味なのか、ちょっとそこがよくわからないとの意見を述べました。","respondent":"田村庶務課長","answer":"残りの学校、ぴゅあ・さぽーとを除いた学校は、総合評価として順位付をして委託をしました。ぴゅあ・さぽーとについては先ほど実績や体制等も既に実績があるということで、特命随契ということで委託した、そのようなことです。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問","question":"そういったところでイメージがつかみにくかったので、その目的とどういう事業なのか、もう少し中身を教えてください。変更した点というか、考え方といいますか、そこを教えていただけますか。","respondent":"市川教育次長、和氣小中一貫教育担当課長","answer":"大きな変更点は、生涯学習とスポーツの振興のところで区長部局で実施される施策との一体的な運営というこの辺の組み替えをしたものです。学校教育に関しましては、従来と大きな変更点は特にございません。 連携グループ、確かにおっしゃるようにさまざまな形態がありますので、そこに応じてその連携の中でどう学力を伸ばすことができているかどうかということを確認するためのテストを独自につくって実施するです。","id":"exchange-005"},{"speaker":"中塚委員","kind":"意見","question":"それはなぜかということと、基本方針の考え方に変更があるのか、ご説明いただけますかとの意見を述べました。","respondent":"市川教育次長","answer":"先ほど申し上げましたけれども、生涯学習に関すること以外は大きな変更点はございません。先ほどご指摘になった点は、特に品川区教育委員会の教育目標であり、基本方針であるということを意識して表現に手を入れた経過があります。","id":"exchange-006"},{"speaker":"中塚委員","kind":"質問・要望","question":"今回からなくなったものですから、その理由が、今の説明じゃよくわからなかったので教えていただきたい。それと、今までずっと掲げられていたと思うんですけれども、その辺はどうなんか尋ねました。","respondent":"市川教育次長","answer":"当然我々にとっては法令遵守義務というのは課せられているわけです。この基本方針の中で、それを伝えたいか、そこのところに考えを至らせたものだということは先ほど申し上げたとおりです。","id":"exchange-007"},{"speaker":"中塚委員","kind":"確認","question":"権利だったり人権だったり、基本的人権について、憲法でも平和のうちに生存する権利を有することを確認すると。もちろん公務員の方々ですから、入区の際に日本国憲法の尊重の宣言をしていると思うんですけれども、その辺をどんなふうに理解しているのか。","respondent":"市川教育次長","answer":"私どもが教育行政で何を考え、何を行うか、これはまさに行政施策の結果として区民の皆さんに評価をしていただくことです。私どもの姿勢をこの基本方針の中でうたったわけでございまして、私どもが伝えるべきことは、こういうことでご理解をいただければと思います。","id":"exchange-008"},{"speaker":"西本委員","kind":"質問・要望","question":"連携を図っていくということだと思うんですけれども、ここの位置づけというのは今後どういうふうになっていくのでしょうか。いかがか尋ねました。","respondent":"冠木指導課長、田村庶務課長","answer":"幼稚園および小学校の連携をより一層推進するとともに、保・幼・小の連携の推進に関する検討委員会というのを立ち上げさせていただいたところです。それから小学校の先生方がともに研修していく場の検討とか… ただし、やはり学校に関する、学校における体育に関すること、あるいは文化財の保護に関することというのは除かれるということになります。","id":"exchange-009"},{"speaker":"西本委員","kind":"質問","question":"それから、保・幼・小になったんですね。幼・保・小とずっと聞いていたような気がするんですけど、保・幼・小というふうにしたのは何か意味があるんか尋ねました。","respondent":"冠木指導課長","answer":"０歳児から保育園のほうがありますので、年齢順です。","id":"exchange-010"},{"speaker":"西本委員","kind":"質問","question":"ただ、年齢が上がっていったりして、４歳児、５歳児という形になると、私立幼稚園とか幼稚園という方もかなりいらっしゃるんじゃないかなと。圧倒的に私立幼稚園のほうが多いわけですから、それは別々に考えていったほうがいいのか、ここはいかがか尋ねました。","respondent":"冠木指導課長","answer":"今回の検討委員会の考え方としまして、品川区全体として検討していきましょうという趣旨ですので、そういうようなところでいろいろな検討がこれからなされるのかなというふうに思ってあります。","id":"exchange-011"},{"speaker":"浅野委員","kind":"質問","question":"これは具体的にはまた平成２１年度計画で出てくるかと思うんですけれども、具体的に何か平成２１年度で行っていくのかどうかということ。指導課のほうにちょっと記載がなかったので、あと、こちちのほうは具体的にどこの部署がそういうことを検討していくのかなということをお伺いします。","respondent":"富田学務課長","answer":"これから、こういったところとあわせて来年度以降の計画ということでこれからまとめてまいりたいと思っているところです。平成２３年７月ですか、指導課、学校と学務課と調整を図りながら計画をまとめてまいりたいと考えています。","id":"exchange-012"},{"speaker":"林副委員長","kind":"質問","question":"ですから、品川で誇るべき小中一貫を世に問うているわけだから、それはそれで謙虚に考えるところは持つべきだろう、それは指摘をしておきます。１５歳までの子どもの健全教育を品川区の教育長の向こうを張ってやっているわけですから。","respondent":"若月教育長","answer":"いずれにいたしましても、今ご指摘いただいたこと、こんなふうに考えているところです。どうぞよろしくお願いいたします。","id":"exchange-013"},{"speaker":"井上委員","kind":"質問","question":"９ページの地区別施設というような考え方なんですけれども、どういうふうに考えているのかちょっとよくわからないんですが、検討課題としてどういうふうなものを見られているのか説明を求めました。","respondent":"古川子ども未来事業部長","answer":"なかなか説明だけでは十分でなかったかもしれませんけれども、６ブロックにそれぞれ担当する園長を示しながら、幼稚園の事業を実施してまいりました。私の考え方と違ってまいりますので、この経営委員会の中で３地区共通の課題ですとか、そういう組織を考えました。","id":"exchange-014"},{"speaker":"井上委員","kind":"意見","question":"連携をされていくべきで、そういうところも続いているんだというようなものが視角で見られるほうがいいと思うんですけど、そういう部分についての配慮というのは何かないのかとの意見を述べました。","respondent":"古川子ども未来事業部長","answer":"９ページに書きましたが、あくまでも、組織における指揮命令権限が及ぶ範囲ということで申しました。そして子ども未来事業部が所管する施設ということで限定的な表というふうにご理解いただければ大変ありがたいなと考えております。","id":"exchange-015"},{"speaker":"井上委員","kind":"質問","question":"わかりました。本来であれば、別物であるべきということを一定私たちは押さえておきながら、ここのところはどんなふうにこれを進めていかれる予定なんか尋ねました。","respondent":"小林青少年育成課長","answer":"現行では作った内容をきちっと年２回程度なんですけど確認をして進めていくという体制を継続してまいりたいと考えています。少なくとも５年すべての任期を一律カバーするというふうには考えておりませんので、登用という点で更新を含めて対応してまいりたいと考えております。","id":"exchange-016"},{"speaker":"井上委員","kind":"質問・要望","question":"そのまま充て職といわれる方たちは替わっていますけれども、そういう意味で同じ方でしたので、そこが本当に機能したかどうかということを評価しながら今後のことですのでぜひ検討していっていただきたいということは要望させていただいて終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"中塚委員","kind":"質問・要望","question":"子ども未来事業部の事務事業概要について教えていただきたいんですけど、総合実施計画となってきて、その１年目ということですか。今後１０年間の区政運営を示した長期基本計画と平成２１年度の事務事業概要との関係、位置づけについて教えていただけますか。","respondent":"古川子ども未来事業部長","answer":"実施計画はご覧のとおり３カ年の実施計画事業についてまたその中で明らかにしております。この事務事業概要にお示しした各事業の中にそれぞれの実施時期、実施内容については毎年度事務事業の検討そして予算の編成。","id":"exchange-018"},{"speaker":"中塚委員","kind":"質問・要望","question":"いわゆる計画における主要課題、この中で就労と子育ての両立支援として保育園待機児童の解消というふうに掲げている文章があるわけですよね。伺いたいのは、それを教えていただきたいのと、ご説明いただけますか。","respondent":"吉岡保育課長","answer":"あるいはまた認証保育所の誘致、あるいはまた認可保育園の定員の弾力化等々によりまして対応を図っているところですけれども、昨年度につきましても。","id":"exchange-019"},{"speaker":"中塚委員","kind":"質問・要望","question":"それと、この事務事業概要の中に、それはどう具体化されているのかというのも伺いたい。そんな話が広がっているんですけれども、どうも答弁がかみ合っていないので教えていただきたいんですけど、いかがでしょう。","respondent":"吉岡保育課長","answer":"先ほども申し上げましたが、さまざまな待機児の解消につきましては、区としてもできる限りの努力をして対応をとってきているところです。","id":"exchange-020"},{"speaker":"中塚委員","kind":"質問・要望","question":"待機児解消に向けて、この１０年間で一定のスパンを持って何を目指しているのかという、そこを伺いたい。２３区の中でも幾つかの自治体で緊急に保育園整備が始まっていると伺っている。","respondent":"古川子ども未来事業部長","answer":"上位計画から事務事業概要の説明の中にはさまざまな今後実施していくべき事業について当然私どもは明らかにしているというふうに考えております。真に保育的な就労支援のための施設、施設だけではない多様な就労支援のあり方は当然あるわけですので、このように考えております。","id":"exchange-021"},{"speaker":"中塚委員","kind":"質問・要望","question":"最後に部長に伺いたいのは、今の子どもたちがどういう状況に置かれているのかというのを全体の考え方を示しているわけですよね。何を検討すべきなのか、そこはしっかりお考えを聞かせてほしいと求めましたけど、いかがでしょう。","respondent":"古川子ども未来事業部長","answer":"しかしながら、すべての家庭のそれぞれの状況に応じた施策を考えていく必要があろうかと考えています。そうではない環境の中での就労支援というのも当然ありますので、認可保育園だけではない、こういうことです。","id":"exchange-022"},{"speaker":"西本委員","kind":"質問・要望","question":"地域をそういう形で見ていきたいというふうなお考えでのことなのか、保育園、全体の中での位置づけみたいなものを教えてほしいと思います。１７ページの緊急一時保育のところで、行った方がいらっしゃるんですが、これは保育ママ制度というふうな感覚で考えていいんか尋ねました。","respondent":"古川子ども未来事業部長、安井子育て支援課長、吉岡保育課長","answer":"そういう視点を地域という中からその資源をお互いが連携しながら活用していく、そういう試みをこれからやっていきたい、こういうことです。… 平成２０年度については、そういった効率の部分について分担しながら進めていくという形でこれからも進めてまいります。ひとり親医療費助成ですとか… こちらは１７ページの一番上の段にもお伝えしていますとおり、対象が若干、性格が違うというふうに考えております。","id":"exchange-023"},{"speaker":"西本委員","kind":"質問・要望","question":"これからおいおい委員会のほうでご要望していきたいと思いますけれども、そういうのも見ていただきたいなというふうに思っております。家庭によって子どもたちがどう置かれているのかというところを今後一緒に考えていきたいと思いますので、これは意見という形でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"林副委員長","kind":"質問・要望","question":"さっきもちょっと言ったように確認だけさせていただきたい。どっちの、そういうことはやっていくんだろうねということを確認しておきたいんですけれども、どちらからでも結構です。","respondent":"吉岡保育課長、市川教育次長","answer":"６００人を超える保育士がおりますので、それぞれいろんな考え方を持っていると思います。しかしながら、考え方は考え方といたしまして、取り組む姿勢には委員おっしゃるとおり全く問題はないというふうに考えております。先ほど教育委員会の事務事業の説明の中で保・幼・小の連携、片やただいま子ども未来事業部のほうからも説明がございました。","id":"exchange-025"},{"speaker":"井上委員","kind":"質問","question":"中学校１０校のその延期に対する今後の対応と、この期間で関西方面ではない修学旅行の実施校というのはあったんか尋ねました。","respondent":"冠木指導課長","answer":"それから、今後ですけれども、今１０校の校長には延期ということを前提にして代理店等との調整に入っていただいているところです。今のところ、延期できないという報告は入っておりませんで、１０校とも延期で実施できる見込みです。","id":"exchange-026"},{"speaker":"井上委員","kind":"質問","question":"実施した学校があるんでしょうかというのが一つと、財政的なもので区が支援しなければいけない状況なのか、そういったところで何か今わかっていることというのはあるんか尋ねました。","respondent":"冠木指導課長","answer":"かなり１０校の旅行の日程が非常に多様化しておりまして、いろんな対応が必要になってくるということで、それぞれの学校が今対応しています。なお、まだ今のところ具体的な通知が来ておりませんので、それをまた見ながら検討してまいりたいというふうに考えてあります。","id":"exchange-027"},{"speaker":"西本委員","kind":"質問","question":"９年生というのは受験が絡んでくるんですよね。そうなると、教育委員会の中でもそういう検討の時間も必要なんじゃないかと思いますが、いかがか尋ねました。","respondent":"市川教育次長","answer":"この修学旅行の取扱いに限らず、新型インフルエンザの感染拡大についての国の考え方というのは、いろいろ今関係者によって検討されているようです。","id":"exchange-028"},{"speaker":"中塚委員","kind":"質問","question":"今後まだどうなるかなかなかわかりませんけど、そういうことの問題意識というのはどんなふうにお考えになられているのか、保育園のほうもそれぞれ教えていただけますか。","respondent":"市川教育次長","answer":"あるいはそれぞれの事業部が対応してきておりますけども、ここはやはり、また具体的な幾つかの施策を実施してきたわけです。したがいまして、ご質問ですけれども、この時期、ご質問の内容について答えることは差し控えさせていただきたい、このように考えます。","id":"exchange-029"},{"speaker":"西本委員","kind":"質問・要望","question":"私たち今年の一つの仕事の中で、その審議も引き継いでいますよということは皆さんにお知らせいただいたほうがと思うんですね。いつになるかは、正副委員長で考えていただきたいと思うんですけど、そういう案件もありますよということはご紹介ほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"堺委員長","kind":"提案","question":"今年の２月１９日請願として受理いたしました、区立城南第二小学校特別支援学級の存続を求める請願、この件だと思います。特にほかにないようですので、今後の委員会の運営について、私のほうからご提案をさせてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-031"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/298846?Template=document&Id=4670#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":51412,"voices":106}},{"id":"h21-20090601-5","meetingId":"h21-cm06","date":"2009年6月1日","dateIso":"2009-06-01","committee":"総務委員会","time":"午後 １時０４分～午後 ３時１９分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を25件整理しています。","topics":[{"id":"topic-01","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"宮崎委員","kind":"質問","question":"とりあえずちょっと１点聞きたいんですけれども、昨年度は２回開催と伺ったんですけれども、これは定例で行っているんでしょうか。今、かなり世界的な状況も変わってきているので、開催の考え方というんですか、どういう考え方で行われているのか尋ねました。","respondent":"福田会計管理者","answer":"年２回といいますのは、一昨年を振り返りますと、一昨年は年に１回でございました。２回、できるだけ直近のデータに基づきまして、金融機関の状況を分析したというものです。","id":"exchange-001"},{"speaker":"宮崎委員","kind":"質問","question":"金融機関の指定のところでは、現在、みずほ銀行を指定しているんですけれども、仮に例えば変更等の必要があるとなった場合、その手続だとかというのはどういうふうにしていくのか、どこで判断していくのか、どういう手続があるのかということについてはいかがか尋ねました。","respondent":"福田会計管理者","answer":"手続といたしましては、まず形式的には公募をするということになってまいります。こういう手続になってあります。","id":"exchange-002"},{"speaker":"宮崎委員","kind":"質問","question":"その公募する前の段階での、これは公募しなければいけないなという判断というか、それはさっきの金融機関調査会というところがやっていくのか、どうなんか尋ねました。","respondent":"福田会計管理者","answer":"金融機関調査会で指定金融機関がどうかということにつきまして、これは判断することはおそらく必要ないだろうと考えております。これは先ほど申しましたように法に基づく制度です。","id":"exchange-003"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"１点、もう１点は中に入っちゃいますのでやめますけれども、１点だけ教えていただきたいんですが、組織改正がありました。これで見る限り何もそういうものがないわけで、議会はどういうふうに改めて我々は理解しておけばいいのかというところだけ説明を求めました。","respondent":"本間副区長","answer":"説明をさせていただいたとおりでございまして、ただ会計管理室の置かれておりますただいま説明させていただいたような、重要性が増してきている。","id":"exchange-004"},{"speaker":"石田（秀）委員","kind":"質問","question":"それは事業部が、例えば事業部長、企画部長、各部長の、例えば取りまとめというか、トップクラスとしてご意見を伺ってもいいのか、我々だけにね。内部と言われていても、我々にわかるようにご説明していただかないと、どういうふうにしたらいいのかなというのがわからないなと思って。","respondent":"本間副区長","answer":"副区長の補佐という役割が出てまいりますが、公金管理という立場から、そういう意味では独立的な要素もある組織だです。身分も一般職ですし、位置づけ等は内部の組織の問題になってありますが、この４月１日に行ったということでご理解のほどよろしくお願いいたします。","id":"exchange-005"},{"speaker":"石田（秀）委員","kind":"質問","question":"もう１つ、１点だけ、説明の中で。それがあまりに認識の違いがあると、我々も応援をするときに違う方向の応援をしてもしようがないなと思ったので、それがわかれば教えてほしい。","respondent":"日下部企画部長","answer":"財調についてのいろいろな問題といいますか、課題があったということで、先ほど企画財政課長のほうからご説明申し上げました。ちょっと小さめの問題とありますが、区側としてはやはりこの問題の解決に向けて全力を挙げなければいけない、このように認識をしています。","id":"exchange-006"},{"speaker":"石田（秀）委員","kind":"質問","question":"それが２なのか、３なのか、４なのか、５なのかという算定を本当にできるのか。何でもいいからとりあえず配分を先に取っちゃおうというと、そこら辺の感覚がもし違うとか、思いがあるなら教えてもらいたいなと思います。","respondent":"金子企画財政課長","answer":"都区間で協議をいたしまして、逆に最後にお金の問題をきちんと整理をしようじゃないかという形になったという経緯があります。しっかりと最後のところでお金の問題も決着をつけるように、これは最大限の努力をしていく、このような決意で臨んでいくということかと思います。","id":"exchange-007"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"現実２年間であまりにもそこが進まなかったわけじゃないですか。それが必ず今年中にはそこはやる話になっちゃうような気がしてならないので、ぜひそれをしっかり注視していただきたいなと、これは意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"宮崎委員","kind":"質問・要望","question":"１点だけ聞かせていただきたいんですけれども、同和のところで１点だけ伺いたいんですけれども。前は１人同和相談員を配置しているということを聞いていたんですけれども、同じような体制なのか、そこら辺のところはどうか尋ねました。","respondent":"中山人権啓発課長","answer":"同和生活相談についてのお尋ねですが、現在は同和生活相談員１名ということで運営をしているところです。年間２５０件ぐらいのご相談を受け付けております。","id":"exchange-009"},{"speaker":"宮崎委員","kind":"質問","question":"ですから、啓発を全部やるのか、それとも何でもやるよというのかどうなのか。ほかの課との連携といいますか、啓発と言いながら相談をあえて持ってくるという、そこら辺の意味というのを聞いておきたいと思います。","respondent":"中山人権啓発課長","answer":"ここで言っている、広報広聴課のほうでやっている人権身の上相談というのは、またそれ以外の幅広い人権に関する相談ということで伺っております。男女のほうはうちのほうで持っておりますので、男女のことに関する相談は人権啓発課のほうでやっているところです。","id":"exchange-010"},{"speaker":"宮崎委員","kind":"質問","question":"そうすると、区民相談でやっている人権というのは、同和と男女共同参画に関すること以外をやるというふうに線引きをしているということなんですか。年間２５０件という話だったんですけれども、あえて分けるというんですか、そこのところはどうなんか尋ねました。","respondent":"中山人権啓発課長","answer":"そういう意味では、やはりそのところをよく理解している方が相談に乗ってくださったほうが安心して話ができる。実際、件数としても上がっておりますし、個別に設ける必要があるのかなと考えているところです。","id":"exchange-011"},{"speaker":"宮崎委員","kind":"質問・要望","question":"具体的に品川区として本当にやらなければいけないのかどうかというところは、私どもによく見えないんですね。私は今までも言ってきていますけれども、見直しということを求めていきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"}]},{"id":"topic-02","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"石田（秀）委員","kind":"質問・要望","question":"基本的に延期はいいんだけれども、ゴーを出すのは、どこがゴーを出すんですか。延期はいいんだけれども、ゴーを出すというのはどこと我々は理解すればいいんか尋ねました。","respondent":"市岡総務部長","answer":"区の新型インフルエンザに対する対処方針を具体的に決めているのは危機管理対策本部ですので、区長がトップの会議体で決めております。その判断に基づいて、学校の修学旅行の実施ということは教育委員会の権限ですので、教育委員会が判断するということになろうかと思います。","id":"exchange-013"},{"speaker":"石田（秀）委員","kind":"意見","question":"どうしてこういうことを聞くかというと、延期になったところがもう１回予約をしようといって動いているんです。そういうところまで面倒を見てあげないと、今回のことはちょっとかわいそうだなと思うので、どうかなとの意見を述べました。","respondent":"市岡総務部長","answer":"品川区として一致して責任を持って行いますが、その前提としては全体的な国や都を含めた情勢判断というのが不可欠だと考えています。学校、保護者の方々にご理解いただけるような、安心していけるような体制にぜひとも進めていきたいと考えております。","id":"exchange-014"},{"speaker":"須貝委員","kind":"質問","question":"そうしたら、中で今度一つの密室ですから。役所、学校、それぞれ区の施設は密室ですから、その辺に対して、やはりできるだけの対応策も必要なのかなと。","respondent":"伊勢総務課長","answer":"啓発用にもある時期マスクを使っていたことがありますが、そういう備蓄についても、これからどれぐらい必要なのか検証していきたいと思ってあります。我々もこれから検証して、秋に変化するかわかりませんけれども、それに備えて考えていきたいと考えています。","id":"exchange-015"},{"speaker":"宮崎委員","kind":"質問","question":"あるいは東京都、あるいは国でやるにしても、そういうのは実際にあるんでしょうか。あったんか尋ねました。","respondent":"市岡総務部長","answer":"それからこの春、危機管理室のほうでいわゆる事業継続計画というのをつくっておりまして、その中でかなりのことは想定しました。我々としては委員おっしゃられるようないろいろな意味での連携、あるいは備えを万全にということでとらせていただいた体制だと考えているところです。","id":"exchange-016"},{"speaker":"石田（秀）委員","kind":"質問","question":"既存不適格が解消されるという理解でいいのかということが１点、よくわからないで見ているのかもしれないけれども、何m2になるのかな。残されたところは地上３階建てと書いてあるんだけれども、実際何m2の建物になるのかなということを教えていただければ。","respondent":"宍戸施設整備課長","answer":"道路から２ｍ後退するという意味での既存不適格につきましては、日影規制については解消されないということだったと思います。それと既存の面積ですが、延べ床面積で６７５m2です。","id":"exchange-017"},{"speaker":"本多委員","kind":"質問・要望","question":"残りの６校については、契約の準備的にこの夏休みを生かせるのかどうか、その辺を教えていただきたいんですけれども。","respondent":"宍戸施設整備課長","answer":"９,０００万円まで金額が至らないものですから、報告に入っていないというものです。平成２２年度、平成２３年度の工事になる清水台小学校、その２校が今年の夏休みではない工事となってしまうというものです。","id":"exchange-018"},{"speaker":"須貝委員","kind":"質問","question":"ちょっと教えてほしいんですが、それから電気設備工事費、機械設備工事費がありますね。総額として、電気は幾ら、機械は幾らで、耐震補強を含めて総額幾らになるかという総額を説明を求めました。","respondent":"宍戸施設整備課長","answer":"１校ごとということになるといろいろあるんですけれども、基本的には今年、１０校分といたしまして、合計の金額が１３億８,０００万円余ということですので、平均して１億３,０００万円余です。","id":"exchange-019"},{"speaker":"須貝委員","kind":"質問","question":"今回、あくまで耐震補強工事ということで総務委員会で話として出てくるわけですから、その辺は今までもそういうことはなかったんですか。あくまで耐震補強の９,０００万円以上ということで、ほかの類似した費用、総額幾らという話では今までも報告としてはなったんか尋ねました。","respondent":"阿部経理課長","answer":"先ほど来ご説明しましたけれども、一応９,０００万円以上の契約案件を当委員会に報告しているんです。電気設備工事等につきましては９,０００万円未満ですので、どこどこと契約をしたという報告を先ほど関連別途工事の中で説明したです。","id":"exchange-020"},{"speaker":"須貝委員","kind":"意見","question":"民間でも何でもそうですが、一応総額がこういうふうにかかりましたということは、この場で報告だけでもしていいんじゃないかなと。あくまで契約だけの範囲でとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-021"},{"speaker":"須貝委員","kind":"質問・要望","question":"あくまで契約に関してはこの契約、９,０００万円以上に対して今回審議していただきたいという話で持っていくのが筋じゃないかなと思いますので、それは意見だけ言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"宮崎委員","kind":"質問・要望","question":"ちょっと確認しておきたいんですけれども、先ほどの９,０００万円以下の４校の話なんですが、これは工事はいつぐらいまでに終わるんですか。できたら具体的にどこの学校はいつぐらいというのがわかったら、教えてほしいと求めました。","respondent":"宍戸施設整備課長","answer":"１校ずつ工期がどうだったかというのはわからないんですけれども、大体９月末かおおむね１０月末まで工期はとらせていただいていると思います。残りの４校につきましては、具体的には鈴ケ森小学校、延山小学校、中延小学校、大崎中学校です。","id":"exchange-023"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"宮崎委員","kind":"意見","question":"建設関係の組合のほうからも請願があって、実際にどういうふうになっているのかというのをこの委員会でも調査すべきなのではないかなと思っています。仕事がないというのが１つあるんですけれども、労賃が安いということがありますので、実際に調査すべきだと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-024"},{"speaker":"土井委員","kind":"質問・要望","question":"先ほどもありましたけれども、都区協議については、節目節目のところで委員長にお計らいいただいて、ご報告をいただく。意見を述べするという機会をつくっていただきたいなと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/829737?Template=document&Id=1822#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":43316,"voices":126}},{"id":"h21-20090602-14","meetingId":"h21-cm06","date":"2009年6月2日","dateIso":"2009-06-02","committee":"行財政改革特別委員会","time":"午後１時０４分～午後３時０４分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を28件整理しています。","topics":[{"id":"topic-01","title":"調査事項概要","agenda":"調査事項概要","exchanges":[{"speaker":"須藤委員","kind":"質問","question":"なかなか大変だよというので何年か前にも質問をしたことがあるし、荏原署、そのあたりは高齢化社会を踏まえてどういうふうに考えているのかが１点。どういうふうになっているのか、品川区直接ではないところの区有施設に対しての支払いの方法がどうなっているか、そのあたりを説明を求めました。","respondent":"岩田防災まちづくり事業部長、久保田行財政改革担当課長","answer":"撤去も含めて考えるという方針は持っておりますけれども、これは現実の交通事故の実態を見ますと、交通事故の９割が交差点付近で起きております。国道、区道の横断歩道橋はほとんどありませんので… 公共料金支払基金を使いまして支払っているものでございまして、対象の範囲ということでは、区の直営の施設です。指定管理者のほうから光熱水費のほうは直接払っているというところが基本となっています。","id":"exchange-001"},{"speaker":"川西委員","kind":"質問・要望","question":"跡地活用についての区のほうのこの現在の社会情勢をいろいろ勘案した中で、重点的に区としてどういうふうにしていきたいかというのを、できるできないは別にして、３つぐらい挙げて教えてほしいと求めました。","respondent":"久保田行財政改革担当課長","answer":"３点目といたしましては、財産としての有効活用といったところもあるかというふうに考えているところです。例えば、それぞれの施設の立地や周辺の状況、また区全体の行政需要等を勘案しながら検討をしていきたいというふうに考えているところです。","id":"exchange-002"},{"speaker":"川西委員","kind":"質問・要望","question":"地域で野球場、サッカー場の要望があることも承知はしておりますけれども、そういうふうに考えていくべきではないか。やはり子どもたちにもっと夢を持たせてほしいというふうに思うと、東大井とかありますけれども、併設施設でちょっと手狭です。","respondent":"久保田行財政改革担当課長","answer":"施設の配置全体の中でも、先ほどご説明がありましたけれども、施設の全体についても検討はしていかなければならないというふうに認識しています。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"国と都と区の負担の分担というのは、大体どういうふうになるのかというのがちょっとわからないものですから教えてほしいと求めました。他自治体はどうなのかということもあわせてお伺いしたいと思います。","respondent":"久保田行財政改革担当課長、金子企画財政課長、家壽田都市整備下水道課長","answer":"２点目のほうですけれども、これまでご説明しましたとおり、また特性等に応じて検討していくです。そうしたものを踏まえながら、区としましては… 国庫補助あるいは都補助、財調の対象になると、こういったようないろいろなケースがあります。区の基本的な考え方としましては… 橋梁の予防的修繕について簡単にご説明いたします。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問・要望","question":"もう一度そこら辺の庁内での過程というんですか、どういうメンバーで行われて、そういう案に至るのかということを教えてほしいと求めました。もししていたら、品川区の現状というのはどういうことなんか尋ねました。","respondent":"久保田行財政改革担当課長","answer":"すべてのものを一律にこういう仕組みがあって検討しているというところではないということはこれまでご説明してきたとおりです。区の行政需要や地域の要望等も踏まえながら、庁内でのそういう検討の組織を立ち上げまして、検討を進めていくです。","id":"exchange-005"},{"speaker":"安藤委員","kind":"質問・要望","question":"区としてこれから工夫をしていけるようなところというのはどういうところがあるかというか、もしあれば教えていただきたいんですけれども、お願いします。","respondent":"久保田行財政改革担当課長","answer":"その施設の内容や必要に応じましてパブリックコメントを実施してまいりまして、荏原平塚と、区民の方から意見をちょうだいしたです。策定過程の中において、私どもとしては、区民の意見も十分聞いていきたいというふうに考えているところです。","id":"exchange-006"},{"speaker":"安藤委員","kind":"質問","question":"区の案に基本的な方向、例えばその施設をどういう種類の施設にするのかという基本的な区の案をまず出して、それに対する意見を伺っているんです。ですから、そこら辺でちょっと違うと思うんですけれども、いかがか尋ねました。","respondent":"久保田行財政改革担当課長","answer":"私ども、１０月ぐらいから議会のほうに案もお示しいたしまして、利用計画案ということを取りまとめてパブリックコメントという運びになったです。区民の方もそうした機会をとらえまして、私どもに自分たちの要望等も伝えてきているといったところです。","id":"exchange-007"},{"speaker":"渡部委員","kind":"質問","question":"お考えでしょうか、どうでしょうかというのがまず１つと、研究とかをされているのかというところをお教えください。２点お願いします。","respondent":"久保田行財政改革担当課長","answer":"平成２５年ということもありますので、現時点で具体的にどういった形で検討というところをまさに検討の前の検討というところをやっているところです。","id":"exchange-008"},{"speaker":"阿部委員","kind":"質問","question":"３点ほどお伺いしたいと思います。実質的な第１回ですので、ちょっと話し合いの進め方、議論の進め方についてどうしていくのかというのも今日お話があったらいいかなと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"山内委員","kind":"質問・要望","question":"ただ、低いところはじゃあどうしたらいいのかなということをこうやってお示しされるときに、そういうことをまずされているのかというのが１点。そこをちょっと教えていただきたいんですけれども。","respondent":"久保田行財政改革担当課長","answer":"午後、夜間ごとの利用率ですので、そういったものを踏まえて検討はしています。五反田、また企業等も研修や会社説明会でも使っているといったこともありますので、一定程度の利用率があるのかなというふうに考えております。","id":"exchange-010"},{"speaker":"山内委員","kind":"質問","question":"ちょっと内容を変えました、極端に上がりましたとか、そういうような過去に事例というのはあるんですか。地域センター、文化センターを含めて、何か画期的なことをしたら数字が上がったよとか、そういうようなことというのは過去にあったのかなと。","respondent":"久保田行財政改革担当課長","answer":"例えば、改築等をして施設の中の設備等をよくしたりなんかすれば、そうした中では利用率は上がってきているのかなというふうに思います。ちょっと大崎第一の例を出してあれですけれども、そうした意味では利用率のほうも多少は上がっているのかなというふうに分析はしています。","id":"exchange-011"},{"speaker":"中塚委員","kind":"質問・要望","question":"幾つか伺いたいんですけれども、このほか、ほかにいろいろ進めてきたものというのがあると思うんですよね。その辺ちょっと、どういうふうに区分けがあるのか、これに載っていないほかにどんな施設があるのか、ちょっと教えていただけますか。","respondent":"久保田行財政改革担当課長","answer":"今回こちら資料にまとめたもの、冒頭でもご説明をさせていただきましたけれども、活用の用途がまだ未定のものというところが１点。昨年の行革委員会のほうで検討をいただきご報告をさせていただきましたけれども。","id":"exchange-012"},{"speaker":"中塚委員","kind":"質問・要望","question":"そういう民間というんですか、そういう品川区のかかわり方といいますか、考え方というのをどういうふうにお持ちなのか教えていただきたい。もともと国営ですから、どういうものなのか、ご説明いただけますか。","respondent":"久保田行財政改革担当課長","answer":"区の跡地活用ですので、こういった形で区の所有している区有施設の有効活用という観点から跡地一覧ということで載せさせていただいているところです。","id":"exchange-013"},{"speaker":"中塚委員","kind":"質問","question":"今のところ、下神明のＪＴの社宅のところは何ら意向がないという、そういうことなのか、ちょっとそこがよくわからなかったので教えてください。基本方針をどういうふうに変えてきたのか、それとも何も変わらないのかわからないですけれども、ちょっとその考え方をあわせて教えていただけますか。","respondent":"日下部企画部長、岩田防災まちづくり事業部長","answer":"私どもが今、パブリックコメントを実施するに当たって対象としておりますものについては、やはりこれはすべてパブリックコメントの対象にする。これはやはり庁内的な検討をいたしまして、八潮のまちづくり検討委員会が創設されて… したがって、こういった場合に行政はどう対応していくかというのは、基本的にこれは私どもが市街地整備基本方針の中で打ち出しておりますように。","id":"exchange-014"},{"speaker":"中塚委員","kind":"質問・要望","question":"地域の要望だったり、そういう視点に立って検討するに当たって、品川区も住民要望をしっかり受けとめてやるべきだなとも思います。そういう子どもや地域の思いというのも大切にすべきではないかなと思うんですけれども、わかりますかね、ちょっとお考えを聞かせていただけますか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"中塚委員","kind":"質問","question":"地域センター、この間で見ると学童もそうですけれども、そこを利用していた人たちの思いというものがあるわけですよね。そういうのをどう受けとめながら跡地利用を考えていくのかということを聞いているんですけれども、いかがか尋ねました。","respondent":"日下部企画部長","answer":"これはもう以前からそういう形で取り組んでおりますけれども、それはそれとして区としても受けとめていく、そういう考え方にかわりはございません。","id":"exchange-016"},{"speaker":"中塚委員","kind":"質問","question":"もう１つ、跡地活用を考える区の考え方のスタンスを伺いたいなと思ったのは、学校あき施設の問題もいろいろ状況が変わってくると思うんですよね。計画中のものも、今進んでいるものも含めて、そこはどういう視点でどういう考え方なのかご説明いただけますか。","respondent":"岩田防災まちづくり事業部長","answer":"特に子育て支援等の施設や、教育委員会なり、保育の部局が推定をしながら長期的な計画を立てていく。ただ、それで近隣のそういう施設にどの程度の負担をかけるかということを十分検討した上で行政指導をしていく、今後も起きないと考えております。","id":"exchange-017"},{"speaker":"中塚委員","kind":"意見","question":"今の保育園不足は、義務化していないというところがあると思いますので、ちょっと今の部長の意見は違うなと思います。意見でとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"},{"speaker":"市川委員","kind":"質問・要望","question":"地域の要望を聞いていくということなんですけれども、要望を聞くということと、その辺の品川区全体を見たときの施設の地域のバランスみたいなものを区としてはどういうふうに考えていらっしゃるのか。","respondent":"久保田行財政改革担当課長","answer":"そうした中で区全体として必要なものというもので活用を図っていかなければならないというところは基本的な考え方として持ってあります。そうした中では、そういう全体の配置というものもにらみながら検討はしていかなければならないというふうに認識しています。","id":"exchange-019"},{"speaker":"市川委員","kind":"質問・要望","question":"バランスよく配置していただきたいなという希望があるんですけれども、区民の要望に対して区として暫定的に区民の方に建物を建て替える前に、そういう考え方はないのかということをお聞きします。","respondent":"久保田行財政改革担当課長","answer":"私どもも跡地の活用について検討していく中では、暫定的な活用といったものも必要だというふうに考えております。そうしたものも踏まえながら、その先の有効活用というところも検討はしていかなければならないです。","id":"exchange-020"},{"speaker":"市川委員","kind":"質問・要望","question":"ぜひこの場でどういう仕組みをとって跡地活用について考えていくのかというのは、この委員会でぜひ議論をしていただきたいというふうに思います。それからもう１点、それとも集計をしていないのか、その辺を説明を求めました。","respondent":"久保田行財政改革担当課長","answer":"そういったもので集計はしていないというご説明をさせていただきましたので、委員会資料として提供していくことは、お時間をいただくことになりますけれども可能だというふうに考えております。","id":"exchange-021"},{"speaker":"山元委員","kind":"質問・要望","question":"１つ教えてほしいと求めました。全部で７７個なのかというのを１つ教えていただきたいということと、内容というんですか、もしわかっているならば教えてほしいと求めました。","respondent":"家壽田都市整備下水道課長","answer":"品川区内にある７７というのは、それから我々区が管理する区道で、合わせて７７の橋梁というふうなことです。これからまさに検討していく段階ですので、かつ最終的にはそれを区の計画として取りまとめていくことになるかというふうに思います。","id":"exchange-022"},{"speaker":"山元委員","kind":"質問・要望","question":"でも、すごく愛着のある橋があるんですね。それは直していただきたい気持ちと同時に、あくまでも修繕で、壊すのでなく修繕ですよね。","respondent":"家壽田都市整備下水道課長","answer":"短い橋でも歴史のある浜川橋のようなものは、または安全性とか経済性を考えたら、かけ替えるという方向になるかもしれません。それも含めてかなり広範囲に、景観であるとか愛着、それから財政面、安全面、幅広く考えて議論していくのが今回の長寿命化計画だと考えています。","id":"exchange-023"},{"speaker":"中塚委員","kind":"質問","question":"１点だけ伺いたいことがあったんですけれども、例えば単純に効率を考えると、利用率というのは限りなく１００％に近づけようとなる。そういうところををどんなふうにお考えになっているのか、そこの考え方を教えていただけますか。","respondent":"久保田行財政改革担当課長","answer":"そうした中で、できる限り１００％ということであれば、１００％に近いという数字ではなかなか利用の勝手が悪くなるといった現状もあります。７割から８割程度ということであれば、そうした中で７割、８割程度というのは１つの基準かなというふうには考えているところです。","id":"exchange-024"}]},{"id":"topic-02","title":"の３、その他","agenda":"の３、その他","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"区全体の行政需要がどうなのかとか、区の中でのバランスがどうなのかという観点も２つ目として必要だということも出されました。高齢者施設はどうなのか、そういったところで実際に今どういうような状況になっているのかというのを大いに参考にしていくべきだと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"中塚委員","kind":"質問・要望","question":"求められているのか、人口から比べれば今後どういうものが必要になってくるのか、そういった資料をお願いしたいと思います。そういう実施を区に求めていくことになるのか、どうしていこうかというのは、ぜひ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"川西委員","kind":"質問・要望","question":"こういうところには規模が小さいから出てこないで、これまで何年かの経緯でそういう小さい小規模施設がどのように住民の要望があり必要だと思うので。現在、区が所有しているものを羅列すればいいだけですから、今後の跡地活用についての意見もこの委員会で議論できようかなというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"若林委員","kind":"質問・要望","question":"１つ私は、平成２１年度からスタートするこの長期基本計画を、これを無視した議論は一切私はできないというふうに当然思っております。単年度、また区のお考えも聞きたいという意味で、長計を忘れてはいけませんよということは申し上げておきたいなというふうに思っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/592995?Template=document&Id=5862#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":40586,"voices":104}},{"id":"h21-20090603-15","meetingId":"h21-cm06","date":"2009年6月3日","dateIso":"2009-06-03","committee":"環境対策特別委員会","time":"午後１時０３分～午後２時３６分","status":"正式会議録","sourceType":"formal","overview":"環境対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を30件整理しています。","topics":[{"id":"topic-01","title":"調査事項概要","agenda":"調査事項概要","exchanges":[{"speaker":"南委員","kind":"確認","question":"どんな見解を持っているのかを、ちょっと改めて伺っておきたいと思いますし、対策を取るには。ですから、その辺の見解というか、そこをちょっとお伺いしたい。","respondent":"藤田水とみどりの課長、工藤環境課長","answer":"トータルで活気あるまちにしていくという考えで、もう少し話がスムーズに進むとか、そういったような形での支援をしていきたいと考えております。東京都との連携がどのように図っていけるのか、そういったような検討をして… 温室効果ガスの排出の抑制等のための総合的、かつ計画的な施策を策定して、実施するように努めるものとするという努力義務があります。","id":"exchange-001"},{"speaker":"南委員","kind":"質問・要望","question":"その辺だけちょっと意見を伺っておきたいと思います。地域の方々の要望で、改めてちょっと教えていただきたいのですが、ちょっとそこだけ伺いたいと思います。","respondent":"工藤環境課長、藤田水とみどりの課長","answer":"家庭に対しての支援というものもありますし、事業所に対しての支援と、ターゲットを絞ってやるということが必要だと考えています。今後の取り組みとしましては、こういった今の事業をどうもっと強力に進めていくのかということと… そういったところでは、活用上の運行のルールといいますか、そういったものをつくったりしているところもあります。","id":"exchange-002"},{"speaker":"伊藤委員","kind":"質問・要望","question":"それから、５カ年計画をまたさらに努力していくということがありますから、それのことを教えていただきたいこと。それから、これからつくろうとされている温暖化対策地域推進計画との連携をどういうふうにとっていくのかということを、ぜひ聞かせてください。","respondent":"工藤環境課長","answer":"前年度比でどれぐらいになったのか、５年間で目標の６％にどんな形で到達していくのかということを進めていくものが、この計画の内容です。考え方としては、そういった部分と整合性はとっていきたいと考えているところです。","id":"exchange-003"},{"speaker":"伊藤委員","kind":"質問・要望","question":"これは５年以上経過をして、そういうふうな方法でやってきたということはありますが、実際にどうだったかということを知りたいです。ですから、非常に難しいことを求めることになるんだけれども、品川区としてはそれをやらなければいけないわけですから。","respondent":"工藤環境課長","answer":"どういった形でというところが、委員ご質問のとおり、私どもも一番難しい作業になろうかと思います。その辺の数値に関しましては、十分に今後、検討をしていきたいと考えているところです。","id":"exchange-004"},{"speaker":"飯沼委員","kind":"質問・要望","question":"この辺をどう考えていくのかというところを、１０件ではちょっと寂しいなと思ったので、その辺をお伺いしたい。その進め方というか、内容において、どういうふうに進めていくのかという中身を、ちょっとお伺いしたいと思います。","respondent":"柏原住宅担当課長、工藤環境課長","answer":"説明がちょっと足りなかった部分もありますので、追加します。例えば、こういった区では助成を行っておりますとか、そういったＰＲをしていきたいと考えています。 品川区の地球温暖化対策の地域推進計画の策定に当たっての進め方を、品川区地球温暖化対策の地域推進協議会というものを設置しまして、この計画をつくってまいりたいと考えているところであります。","id":"exchange-005"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そこが１点。所得制限とかなくなったとしたら、また希望の枠も増えてくるのかなと思うので、ぜひこの辺はさらに進めていただきたいという思いを伝えたいんです。","respondent":"柏原住宅担当課長","answer":"それから、申込みの所得の制限ですが、前年度まではございました。ただ、国、都が所得制限を設けておりませんので、国と都との併給が可能ということにしましたので、所得制限を設けないでしてみるということです。","id":"exchange-006"},{"speaker":"飯沼委員","kind":"質問","question":"さっきの地域推進協議会というのは、住民のメンバーを入れて、これから設置をされるということなんでしょうか。ちょっとそこのところを、もうちょっと詳しく説明を求めました。","respondent":"工藤環境課長","answer":"地域推進協議会についてのお尋ねですけれども、私ども、まさに今、設置しようです。いろいろと区民の公募の方と、さまざまな団体の方からの推薦を受けまして、メンバーがほぼ固まりつつあるところです。","id":"exchange-007"},{"speaker":"大沢委員","kind":"質問","question":"環境課の１ページということで説明を伺いましたけれども、１６ページと、さっきされましたか。逆に、説明がされないで、１番の温暖化対策事業の１から４までということで、これに主眼を置くのであれば、温暖化対策……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"確認させていただきたいんですが、単位が灯という単位で約２万灯で、１基について何灯かあるんですか。単位の確認をさせてください。","respondent":"齋藤道路公園課長","answer":"街路灯は、ランプをかえる場合もあります、清掃をする場合もあります。そういった場合、灯を単位で考えておりますが、取りかえる場合は、全部かえますので基という単位でとらえて整備しております。","id":"exchange-009"},{"speaker":"稲川委員","kind":"質問・要望","question":"お伺いするだけになってしまうと思うんですが、どういった運河、水辺の活用にするのか。例えば、両脇に商店でいろいろ人が集まるようなもの目指しているのか、ちょっとその辺の理想像を教えてほしいと求めました。","respondent":"藤田水とみどりの課長","answer":"望ましい姿といいますか、目指すべきところですけれども、私は、答えは一つではないと思っています。その地域に合った形で、まちが活性化していけばいいと考えております。","id":"exchange-010"},{"speaker":"稲川委員","kind":"質問","question":"僕の質問の前にも、にぎわいとか、活性化というような話が出たんですけれども、最終的には、水とみどりにとどまることなく、例えば商業・観光課とタイアップした都市型観光を追求していくと、そこまで行き着くんですか、そこだけ。","respondent":"藤田水とみどりの課長","answer":"観光のほうでは、今、観光アクションプランとかいったものをつくっております。やはりトータルでいろいろ盛り上がっていくために、それぞれ別で動かすのではなく、お互いに連携しながら進めていくべき事業だと考えています。","id":"exchange-011"},{"speaker":"林委員","kind":"確認","question":"委員長に確認します。水とみどりの課長というのは、水辺の整備もやるんか尋ねました。","respondent":"藤田水とみどりの課長","answer":"今回の組織の考え方の中では、整備という、ある程度計画を立てて進めていこうという部分と両方あろうかと思います。実際にトンカチをたたいていろいろ物をつくっていこうという部分については、私どもの所管でなく、都市整備下水道課の所管になってきます。","id":"exchange-012"},{"speaker":"林委員","kind":"質問","question":"それについての議論は、この中でやるということで、先ほど、大沢委員の質問に、建設委員会との話で調整がついているということでした。とすれば、水辺の整備ということを、この中でやるんか尋ねました。","respondent":"山路委員長","answer":"課長に説明していただいたんですが、今までの継続はありますけれども、ここから選ばせていただいたと認識をしております。","id":"exchange-013"},{"speaker":"林委員","kind":"質問","question":"いろいろ質問している人がいるんですけれども、ここまでやるんですかという質問が出てこないから、僕は質問しているんです。水辺の整備ということも、この委員会でやるんか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"林委員","kind":"意見","question":"こういう進め方をして、特別委員会だから、１年後にはきちんとした意見を出しますという話にならないといけないわけですよ。ここに書いてあるのは、水辺と書いてあるんですよとの意見を述べました。","respondent":"山路委員長","answer":"水とみどりのネットワーク化推進の中に、水辺の実態調査とみどりの実態調査が含まれて、その辺に関して、この委員会は取り組んでいこうということで、今回、取り上げているわけです。","id":"exchange-015"},{"speaker":"林委員","kind":"意見","question":"とすると、では、水辺の整備というふうにとっていいんですね。水辺の現状把握をするというのを説明した、それをよしとする了解ならば、水辺の整備ということも、この委員会で扱っていかなきゃならないでしょうとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-016"},{"speaker":"林委員","kind":"質問","question":"その中の１の水と親しむという、１ページ、２ページを、水とみどり課長が説明したわけですよ。ここに出ているから、水辺の活用ということは、水辺の整備に関しても入っていってオーケーですね、という質問なんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"林委員","kind":"質問","question":"いいですか、ダブらないですねというのは、表題に水辺の整備とここには出ているんだから、入っていきますよということを言っているんです。水上バスをつくるのかというところまで、水辺の活用ということになれば入っていきますよ、この委員会で。","respondent":"山路委員長","answer":"新・水とみどりのネットワーク構想の進捗状況と、親水公園の検討と、水辺の活用ということで分けさせていただいたわけです。細かくそこまで説明が至らなかったのは申しわけございませんが、そういう感じで取り上げていきたいです。","id":"exchange-018"},{"speaker":"林委員","kind":"質問・要望","question":"あるいは要望等をまとめるときに、１年間やってきたのに、建設委員会との折り合いの話になると。だから、そういうのではないんですねということだけは、みんな確認されているんか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"林委員","kind":"意見","question":"やっていないという話が、どうも。水辺整備、それから、水辺の活用、ここには水辺の活用という字が出ているんですけれども、これは除くとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-020"},{"speaker":"林委員","kind":"確認","question":"確認しておきますけれども。議会運営委員会がつくったのに抵触しちゃうと困りますよ、後で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"林委員","kind":"意見","question":"だからその辺はもう１回、委員会を開いたら、こういう意見が出てきたので、もう１回、それこそ整備をしますというふうにして、話を整えてください。それは、委員長にお願いしておきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-022"},{"speaker":"林委員","kind":"確認","question":"品川区行政が直接かかわる４番と、１番に対しては、そういうふうに理解していいんですか。１と４番の違いを、僕は確認しておきたいんです。","respondent":"工藤環境課長","answer":"法定根拠として、４番目の品川区としての実行計画というのは、温暖化対策推進法による法定計画という位置づけです。温暖化対策の計画をつくって推進に努めるという形になっておりますので、根本の考え方の違いはありますけれども、そういったものです。","id":"exchange-023"},{"speaker":"林委員","kind":"質問","question":"京都議定書の二次みたいなものになってくるわけですから、すぐに行政に、それを自治体とすれば目標にしていくということは出てくると思うんです。環境課というのは、そういうことにどういうふうに対応しようとしているわけなのか、一言聞かせておいてください。","respondent":"工藤環境課長","answer":"当然、品川区の目標という部分を検討していかなければいけないと考えていますので、今後の動向を見ながら考えていかなければいけないと思っています。当然、そういった国等の世界の動向を見据えながら、いろいろと計画の策定をしてまいりたいと思っているところです。","id":"exchange-024"},{"speaker":"林委員","kind":"意見","question":"日本がどういうふうに合意と言ったらいいのか、日本がどういう態度、そこで数字が出てくる。この委員会で、品川区の目標が達成できるようなものができればいいと思っていますので、お願いしておきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-025"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"今の現状がどうなっているのか、特に品川区の状況がどうなっているのか、それも全部つまびらかに議会に出していただきたい。あるいは、そういう豪勢な活動をしていただきたいと思っているので、その点はよろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"浅野委員","kind":"意見","question":"１９９０年の基準値、その５年後にさらに三つの代替フロンとか、そこら辺のガスが加えられたと思うんです。そのための勉強会みたいなものを開いていただければと思うんですけれども、これは正副委員長にお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-027"},{"speaker":"林委員","kind":"質問","question":"だけれども、人間社会で経済がなくなるということは考えてはいけないんですから、そういうところの経済と環境という文章も出てくる。ものづくり・経営支援課というのが品川区にあるわけですから、地球に対して、あるいは未来に対してということも考えていかなきゃいけない。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"飯沼委員","kind":"意見","question":"ＩＰＣＣの見解のところが、昨年の１２月のＣＯＰ１５の今の中期目標とか、いろいろな学者がいろいろな説を言っていますよね。もし出すのだったら、私も何人か持っていますので、いろいろな立場の方の意見を出し合って論議をしていくということをお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-029"},{"speaker":"伊藤委員","kind":"質問・要望","question":"だけれども、それに対して、品川区のところで、到底到達できないものがあるわけですから、そのことを十分に切り分けしてほしいんです。できないことをここで求めていくことは、実際的には無理な話ですから、実効ある委員会運営をいただきますようにお願いをしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/485957?Template=document&Id=6166#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=15&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":25934,"voices":94}}]);
